  // ═══════════════════════════════════════════════════════════
  // ═══════════════════════════════════════════════════════════
  // STOCK BREAKS - identifies line products with 0 stock in any warehouse
  // ═══════════════════════════════════════════════════════════
  app.get('/api/dashboard/stock-breaks', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      // Warehouses that determine quiebre/alert status
      // Only these 4 warehouses are evaluated for stock breaks
      const RELEVANT_WAREHOUSES = [
        'BODEGA CONCEPCION',
        'BODEGA DEL SUR',
        'PRODUCTOS TERMINADOS',
        'SANTIAGO',
      ];

      // Helper to check if a warehouse name is relevant for quiebre evaluation
      const isRelevantWarehouse = (name: string): boolean => {
        const upper = (name || '').toUpperCase().trim();
        return RELEVANT_WAREHOUSES.some(rw => upper === rw);
      };

      // Get all warehouse-level stock for line products (those in price_list)
      const result = await db.execute(sql`
        SELECT 
          pl.codigo as sku,
          pl.producto,
          pl.unidad as formato,
          ip.nombre_bodega as bodega_nombre,
          COALESCE(ip.stock2, 0)::numeric as stock
        FROM price_list pl
        INNER JOIN inventory_products ip ON ip.sku = pl.codigo
        WHERE pl.codigo IS NOT NULL AND pl.codigo != ''
        ORDER BY pl.producto, pl.codigo, ip.nombre_bodega
      `);

      const rows = (result as any).rows || [];

      // Group by SKU and collect warehouse details
      const skuMap = new Map<string, {
        sku: string;
        producto: string;
        formato: string;
        bodegas: { nombre: string; stock: number; isRelevant: boolean }[];
        hasQuiebre: boolean;
        stockTotal: number;
      }>();

      for (const row of rows) {
        const stock = parseFloat(row.stock) || 0;
        const bodegaNombre = row.bodega_nombre || '—';
        const relevant = isRelevantWarehouse(bodegaNombre);

        if (!skuMap.has(row.sku)) {
          skuMap.set(row.sku, {
            sku: row.sku,
            producto: row.producto || 'Sin nombre',
            formato: row.formato || '—',
            bodegas: [],
            hasQuiebre: false,
            stockTotal: 0,
          });
        }
        const entry = skuMap.get(row.sku)!;
        entry.bodegas.push({
          nombre: bodegaNombre,
          stock: Math.round(stock * 100) / 100,
          isRelevant: relevant,
        });
        entry.stockTotal += stock;
        // Only mark quiebre if the warehouse is one of the relevant ones
        if (stock <= 0 && relevant) {
          entry.hasQuiebre = true;
        }
      }

      // Filter only products with quiebre in at least 1 RELEVANT warehouse
      const items = Array.from(skuMap.values())
        .filter(item => item.hasQuiebre)
        .map(item => ({
          ...item,
          stockTotal: Math.round(item.stockTotal * 100) / 100,
        }));

      // Get distinct warehouse names for column headers
      const warehouseSet = new Set<string>();
      for (const item of items) {
        for (const b of item.bodegas) {
          warehouseSet.add(b.nombre);
        }
      }
      const warehouses = Array.from(warehouseSet).sort();

      // Count total line products that exist in inventory
      const totalResult = await db.execute(sql`
        SELECT COUNT(DISTINCT pl.codigo) as total 
        FROM price_list pl
        INNER JOIN inventory_products ip ON ip.sku = pl.codigo
        WHERE pl.codigo IS NOT NULL AND pl.codigo != ''
      `);
      const totalLinea = Number((totalResult as any).rows?.[0]?.total) || 0;

      res.json({
        summary: {
          totalLinea,
          conQuiebre: items.length,
          warehouses,
          relevantWarehouses: RELEVANT_WAREHOUSES,
        },
        items,
      });
    } catch (error: any) {
      console.error('Error fetching stock breaks:', error?.message || error);
      res.status(500).json({ message: 'Error al consultar quiebres de stock', detail: error?.message });
    }
  }));

  // CONSOLIDATED DASHBOARD INIT - reduces ~12 API calls to 1
  // ═══════════════════════════════════════════════════════════
  app.get('/api/dashboard/init', requireCommercialAccess, requireOwnSalespersonQuery, responseCacheMiddleware(120), asyncHandler(async (req: any, res: any) => {
    const { period, filterType, segment, salesperson, client, product, branch, endDateStr } = req.query;

    const dateRange = getDateRange(period as string, filterType as string);
    const currentStartDate = dateRange.startDate || '';
    const currentEndDate = dateRange.endDate || '';

    // Calculate YTD parameters
    const today = new Date();
    let currentYear = today.getFullYear();
    if (typeof endDateStr === 'string' && (endDateStr as string).match(/^\d{4}/)) {
      currentYear = parseInt((endDateStr as string).substring(0, 4), 10);
    }

    // Scope de datos para encargado_area (sucursales asignadas); [] => sin restricción
    const clientScope = await getEncargadoScopeKoens(req.user);

    const filters = {
      segment: segment as string,
      salesperson: salesperson as string,
      client: client as string,
      product: product as string,
      branch: branch as string,
      clientScope,
    };

    // Run ALL queries in parallel - single HTTP roundtrip, multiple DB queries
    const [
      metrics,
      bestYear,
      availablePeriods,
      yearlyTotals,
    ] = await Promise.all([
      // 1. Main sales metrics (78ms)
      currentStartDate && currentEndDate
        ? storage.getSalesMetrics({
            startDate: currentStartDate,
            endDate: currentEndDate,
            salesperson: salesperson as string,
            segment: segment as string,
            client: client as string,
            product: product as string,
            branch: branch as string,
            clientScope,
          } as any)
        : null,
      // 2. Best year historical (1.1s but cached 5min)
      storage.getBestYearHistorical(filters),
      // 3. Available periods (163ms but cached 5min)
      storage.getAvailablePeriods(),
      // 4. Yearly totals (parallel internally, ~100ms)
      storage.getYearlyTotals(currentYear, filters, endDateStr as string),
    ]);

    res.json({
      metrics,
      bestYear,
      availablePeriods,
      yearlyTotals,
    });
  }));

  // ═══════════════════════════════════════════════════════════
  // CONSOLIDATED KPI DATA - reduces ~10 API calls to 1
  // ═══════════════════════════════════════════════════════════
  app.get('/api/dashboard/kpi-data', requireCommercialAccess, responseCacheMiddleware(120), asyncHandler(async (req: any, res: any) => {
    const { period, filterType, segment, salesperson, client, product, comparePeriod, ytdRangeStr, endDateStr } = req.query;

    const dateRange = getDateRange(period as string, filterType as string);
    const startDate = dateRange.startDate || '';
    const endDate = dateRange.endDate || '';

    // Calculate year for yearly totals
    const today = new Date();
    let currentYear = today.getFullYear();
    if (typeof endDateStr === 'string' && endDateStr.match(/^\d{4}/)) {
      currentYear = parseInt(endDateStr.substring(0, 4), 10);
    }

    // Scope de datos para encargado_area (sucursales asignadas); [] => sin restricción
    const clientScope = await getEncargadoScopeKoens(req.user);

    const filters = {
      segment: segment as string,
      salesperson: salesperson as string,
      client: client as string,
      product: product as string,
      clientScope,
    };

    // Parse comparison period date range if provided
    let compDateRange: any = {};
    if (comparePeriod) {
      if ((comparePeriod as string).includes('_')) {
        const [from, to] = (comparePeriod as string).split('_');
        compDateRange = { startDate: from, endDate: to };
      } else {
        compDateRange = getDateRange(comparePeriod as string, filterType as string);
      }
    }

    // Parse YTD range
    let ytdStart: string | undefined;
    let ytdEnd: string | undefined;
    if (ytdRangeStr && (ytdRangeStr as string).includes('_')) {
      const [from, to] = (ytdRangeStr as string).split('_');
      ytdStart = from;
      ytdEnd = to;
    }

    // Run ALL queries in parallel - this is the key optimization
    let metricsResult, comparisonMetricsResult, nvvMetricsResult, nvvGlobalMetricsResult;
    let gdvGlobalMetricsResult, yearlyTotalsResult, nvvYearlyMetricsResult, bestYearResult, budgetDataResult;
    
    try {
      [
        metricsResult,
        comparisonMetricsResult,
        nvvMetricsResult,
        nvvGlobalMetricsResult,
        gdvGlobalMetricsResult,
        yearlyTotalsResult,
        nvvYearlyMetricsResult,
        bestYearResult,
        budgetDataResult,
      ] = await Promise.all([
        // 1. Main sales metrics
        startDate && endDate
          ? storage.getSalesMetrics({
              startDate, endDate,
              salesperson: salesperson as string,
              segment: segment as string,
              client: client as string,
              product: product as string,
              clientScope,
            } as any)
          : Promise.resolve(null),
        // 2. Comparison period metrics (optional)
        compDateRange.startDate && compDateRange.endDate
          ? storage.getSalesMetrics({
              startDate: compDateRange.startDate,
              endDate: compDateRange.endDate,
              salesperson: salesperson as string,
              segment: segment as string,
              client: client as string,
              product: product as string,
              clientScope,
            } as any)
          : Promise.resolve(null),
        // 3. NVV metrics (period filtered)
        storage.getNvvSummaryMetrics({
          ...(startDate ? { startDate: new Date(startDate) } : {}),
          ...(endDate ? { endDate: new Date(endDate) } : {}),
          salesperson: salesperson as string,
          segment: segment as string,
          client: client as string,
          clientScope,
        }),
        // 4. NVV global (no date filters)
        storage.getNvvSummaryMetrics({
          salesperson: salesperson as string,
          segment: segment as string,
          client: client as string,
          clientScope,
        }),
        // 5. GDV global pending
        storage.getGdvPendingGlobal({
          salesperson: salesperson as string,
          segment: segment as string,
          client: client as string,
          clientScope,
        }),
        // 6. Yearly totals
        storage.getYearlyTotals(currentYear, filters, endDateStr as string),
        // 7. NVV yearly metrics
        ytdStart && ytdEnd
          ? storage.getNvvSummaryMetrics({
              startDate: new Date(ytdStart),
              endDate: new Date(ytdEnd),
              salesperson: salesperson as string,
              segment: segment as string,
              client: client as string,
              clientScope,
            })
          : Promise.resolve(null),
        // 8. Best year
        storage.getBestYearHistorical(filters),
        // 9. Budget data
        db.select().from(presupuestoVentas).where(eq(presupuestoVentas.anio, currentYear)),
      ]);
    } catch (err: any) {
      console.error('[KPI-DATA] Error in consolidated query:', err.message || err);
      throw err;
    }

    res.json({
      metrics: metricsResult,
      comparisonMetrics: comparisonMetricsResult,
      nvvMetrics: nvvMetricsResult,
      nvvGlobalMetrics: nvvGlobalMetricsResult,
      gdvGlobalMetrics: gdvGlobalMetricsResult,
      yearlyTotals: yearlyTotalsResult,
      nvvYearlyMetrics: nvvYearlyMetricsResult,
      bestYear: bestYearResult,
      budgetData: budgetDataResult,
    });
  }));

