  // Excel Export - All sales details (XLSX for maximum compatibility)
  app.get("/api/sales/export-csv", requireAuth, async (req, res) => {
    try {
      const { period, filterType = "month", segment, salesperson, client, branch } = req.query;
      const dateRange = getDateRange(period as string, filterType as string);

      // Build conditions
      const conditions: any[] = [
        sql`${factVentas.tido} != 'GDV'`
      ];

      if (dateRange.startDate) {
        conditions.push(sql`${factVentas.feemdo} >= ${dateRange.startDate}`);
      }
      if (dateRange.endDate) {
        conditions.push(sql`${factVentas.feemdo} <= ${dateRange.endDate}`);
      }
      if (segment) {
        conditions.push(segmentEq(factVentas.noruen, segment as string));
      }
      if (salesperson) {
        conditions.push(eq(factVentas.nokofu, salesperson as string));
      }
      if (client) {
        conditions.push(eq(factVentas.nokoen, client as string));
      }
      if (branch) {
        conditions.push(eq(factVentas.nosudo, branch as string));
      }

      const rows = await db
        .select({
          fecha: factVentas.feemdo,
          tipoDocumento: factVentas.tido,
          numeroDocumento: factVentas.nudo,
          segmento: factVentas.noruen,
          sucursal: factVentas.nosudo,
          vendedor: factVentas.nokofu,
          cliente: factVentas.nokoen,
          codigoProducto: factVentas.koprct,
          producto: factVentas.nokoprct,
          familia: factVentas.nofmpr,
          subfamilia: factVentas.nopfpr,
          cantidadUD1: factVentas.caprco1,
          unidadUD1: factVentas.ud01pr,
          cantidadUD2: factVentas.caprco2,
          unidadUD2: factVentas.ud02pr,
          precioUnitario: factVentas.ppprne,
          montoNeto: factVentas.vaneli,
          montoBruto: factVentas.vabrli,
          montoTotal: factVentas.monto,
          bodega: factVentas.nobosuli,
          ordenCompra: factVentas.ocdo,
        })
        .from(factVentas)
        .where(and(...conditions))
        .orderBy(sql`${factVentas.feemdo} DESC, ${factVentas.nudo} DESC`);

      // Build Excel data
      const excelData = rows.map(row => ({
        'Fecha': row.fecha || '',
        'Tipo Documento': row.tipoDocumento || '',
        'Nro Documento': row.numeroDocumento || '',
        'Segmento': canonicalSegmentName(row.segmento) || '',
        'Sucursal': row.sucursal || '',
        'Vendedor': row.vendedor || '',
        'Cliente': row.cliente || '',
        'Código Producto': row.codigoProducto || '',
        'Producto': row.producto || '',
        'Familia': row.familia || '',
        'Subfamilia': row.subfamilia || '',
        'Cantidad UD1': row.cantidadUD1 != null ? Number(row.cantidadUD1) : '',
        'Unidad UD1': row.unidadUD1 || '',
        'Cantidad UD2': row.cantidadUD2 != null ? Number(row.cantidadUD2) : '',
        'Unidad UD2': row.unidadUD2 || '',
        'Precio Unitario': row.precioUnitario != null ? Number(row.precioUnitario) : '',
        'Monto Neto': row.montoNeto != null ? Number(row.montoNeto) : '',
        'Monto Bruto': row.montoBruto != null ? Number(row.montoBruto) : '',
        'Monto Total': row.montoTotal != null ? Number(row.montoTotal) : '',
        'Bodega': row.bodega || '',
        'Orden Compra': row.ordenCompra || '',
      }));

      const wb = XLSX.utils.book_new();
      const ws = XLSX.utils.json_to_sheet(excelData);

      // Auto-size columns for better readability
      const colWidths = [
        { wch: 12 }, // Fecha
        { wch: 15 }, // Tipo Documento
        { wch: 15 }, // Nro Documento
        { wch: 20 }, // Segmento
        { wch: 18 }, // Sucursal
        { wch: 25 }, // Vendedor
        { wch: 30 }, // Cliente
        { wch: 18 }, // Código Producto
        { wch: 35 }, // Producto
        { wch: 20 }, // Familia
        { wch: 20 }, // Subfamilia
        { wch: 14 }, // Cantidad UD1
        { wch: 12 }, // Unidad UD1
        { wch: 14 }, // Cantidad UD2
        { wch: 12 }, // Unidad UD2
        { wch: 16 }, // Precio Unitario
        { wch: 14 }, // Monto Neto
        { wch: 14 }, // Monto Bruto
        { wch: 14 }, // Monto Total
        { wch: 20 }, // Bodega
        { wch: 16 }, // Orden Compra
      ];
      ws['!cols'] = colWidths;

      XLSX.utils.book_append_sheet(wb, ws, 'Ventas');

      const excelBuffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

      const now = new Date();
      const filename = `ventas_${now.toISOString().split('T')[0]}.xlsx`;

      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send(excelBuffer);
    } catch (error) {
      console.error("Error exporting sales Excel:", error);
      res.status(500).json({ message: "Failed to export sales Excel" });
    }
  });

