  // Goals progress endpoint
  app.get('/api/goals/progress', requireCommercialAccess, responseCacheMiddleware(120), async (req, res) => {
    try {
      const { selectedPeriod, type, target } = req.query;
      const filterPeriod = selectedPeriod as string;
      const filterType = type as string;
      const filterTarget = target as string;

      // Normalize function to handle case and accent insensitive comparison
      const normalize = (str: string | null | undefined): string => {
        if (!str) return '';
        return str
          .toString()
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '') // Remove diacritics (accents)
          .toLowerCase()
          .trim();
      };

      // Scope de datos para encargado_area (sucursales asignadas); [] => sin restricción
      const clientScope = await getEncargadoScopeKoens((req as any).user);

      const allGoals = await storage.getGoals();

      // Filter goals by selected period - only show goals for the specific period
      let filteredGoals = filterPeriod
        ? allGoals.filter(goal => goal.period === filterPeriod)
        : allGoals;

      // Additional filtering by type and target if provided
      if (filterType && filterType !== "all") {
        filteredGoals = filteredGoals.filter(goal => goal.type === filterType);

        // If a specific target is provided, filter by it with normalized comparison.
        // canonicalSegmentName unifica los alias del segmento Industrial (ex "Modular")
        // para que una meta vieja matchee con el filtro nuevo; no afecta a vendedores.
        if (filterTarget) {
          filteredGoals = filteredGoals.filter(goal => normalize(canonicalSegmentName(goal.target)) === normalize(canonicalSegmentName(filterTarget)));
        }
      }

      // If no goals found for the filters, return empty array (this will hide the section)
      if (filteredGoals.length === 0) {
        res.json([]);
        return;
      }

      const goalsWithProgress = await Promise.all(
        filteredGoals.map(async (goal) => {
          let currentSales = 0;

          switch (goal.type) {
            case 'global':
              currentSales = await storage.getGlobalSalesForPeriod(goal.period, clientScope);
              break;
            case 'segment':
              if (goal.target) {
                currentSales = await storage.getSegmentSalesForPeriod(goal.target, goal.period, clientScope);
              }
              break;
            case 'salesperson':
              if (goal.target) {
                currentSales = await storage.getSalespersonSalesForPeriod(goal.target, goal.period, clientScope);
              }
              break;
          }

          const targetAmount = parseFloat(goal.amount);
          const percentage = targetAmount > 0 ? (currentSales / targetAmount) * 100 : 0;
          const remaining = Math.max(0, targetAmount - currentSales);

          return {
            ...goal,
            currentSales,
            targetAmount,
            percentage: Math.min(100, percentage),
            remaining,
            isCompleted: percentage >= 100
          };
        })
      );

      res.json(goalsWithProgress);
    } catch (error) {
      console.error("Error fetching goals progress:", error);
      res.status(500).json({ message: "Failed to fetch goals progress" });
    }
  });

