  // Create new eCommerce product (admin/supervisor only)
  app.post('/api/ecommerce/products', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    const {
      ecommerceProductSchema
    } = await import('@shared/schema');

    // Validate request body
    const validationResult = ecommerceProductSchema.safeParse(req.body);
    if (!validationResult.success) {
      return res.status(400).json({
        message: 'Validation error',
        errors: validationResult.error.errors
      });
    }

    // Check if slug is available
    const slugAvailable = await storage.validateProductSlug(validationResult.data.slug);
    if (!slugAvailable) {
      return res.status(400).json({
        message: 'Slug already exists. Please choose a different slug.'
      });
    }

    // Convert schema data to EcommerceProduct format for storage
    const ecommerceProduct = {
      id: validationResult.data.kopr,
      createdAt: new Date(),
      updatedAt: new Date(),
      descripcion: validationResult.data.name,
      priceListId: validationResult.data.kopr, // Using kopr as priceListId
      activo: validationResult.data.ecomActive,
      categoria: validationResult.data.category || null,
      imagenUrl: validationResult.data.images?.[0]?.url || null,
      precioEcommerce: validationResult.data.ecomPrice?.toString() || null,
      orden: null,
    };
    const product = await storage.createEcommerceProduct(ecommerceProduct);
    invalidateStoreCache();
    res.status(201).json(product);
  }));

  // Update eCommerce product (admin/supervisor only)
  app.patch('/api/ecommerce/products/:kopr', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    const { kopr } = req.params;
    const {
      updateEcommerceProductSchema
    } = await import('@shared/schema');

    // Validate request body
    const validationResult = updateEcommerceProductSchema.safeParse(req.body);
    if (!validationResult.success) {
      return res.status(400).json({
        message: 'Validation error',
        errors: validationResult.error.errors
      });
    }

    // If slug is being updated, check availability
    if (validationResult.data.slug) {
      const slugAvailable = await storage.validateProductSlug(validationResult.data.slug, kopr);
      if (!slugAvailable) {
        return res.status(400).json({
          message: 'Slug already exists. Please choose a different slug.'
        });
      }
    }

    try {
      const product = await storage.updateEcommerceProduct(kopr, validationResult.data);
      invalidateStoreCache();
      res.json(product);
    } catch (error: any) {
      if (error.message.includes('not found')) {
        return res.status(404).json({ message: 'Product not found' });
      }
      throw error;
    }
  }));

  // Toggle eCommerce active status (admin/supervisor only)
  app.patch('/api/ecommerce/products/:kopr/toggle-active', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    // Will invalidate store cache at the end
    const { kopr } = req.params;

    try {
      const product = await storage.toggleEcommerceActive(kopr);
      invalidateStoreCache();
      res.json(product);
    } catch (error: any) {
      if (error.message.includes('not found')) {
        return res.status(404).json({ message: 'Product not found' });
      }
      throw error;
    }
  }));

  // Get available eCommerce categories (admin/supervisor only)
  app.get('/api/ecommerce/categories', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    const categories = await storage.getEcommerceCategories();
    res.json(categories);
  }));

  // Validate product slug availability (admin/supervisor only)
  app.post('/api/ecommerce/products/validate-slug', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    const { slug, excludeKopr } = req.body;

    if (!slug) {
      return res.status(400).json({ message: 'Slug is required' });
    }

    const isAvailable = await storage.validateProductSlug(slug, excludeKopr);
    res.json({ available: isAvailable });
  }));

  // ===================== End eCommerce API Routes =====================

  // ===================== eCommerce Orders API Routes =====================

  // Resolve authoritative prices for order items based on customer's assigned price list (lcen).
  // Overwrites frontend-supplied unitPrice to prevent price-list mismatches.
  // Items without a resolvable SKU keep their original unitPrice and are flagged.
  //
  // Special cases (used by "pedido sugerido" flow):
  //   - Items with `type: 'custom'` are passed through with their `unitPrice` (no lookup).
  //   - Items with an explicit `priceTier` use that tier's price from price_list / mix / offers
  //     instead of the client's lcen, and convenio discount is NOT applied (the salesperson
  //     already chose the final tier).
  async function resolveItemsPricing(items: any[], client: any | null) {
    const priceListCode = (effectivePriceList(client) || 'LP01').toUpperCase();
    const branchDiscountPct = client?.branchDiscountPercent ? parseFloat(client.branchDiscountPercent as string) || 0 : 0;
    const useCustomList = priceListCode !== 'LP01';

    // Targeting de ofertas: una oferta aplica si es para todos (all_clients) o si
    // este cliente está en su lista. Matcheamos por id exacto o por mismo RUT (para
    // cubrir todas las sucursales de una empresa al elegir la casa matriz). Cliente
    // nulo/anónimo => solo aplican las ofertas all_clients.
    const offerClientId = (client?.id || '').toString();
    const offerClientRut = (client?.rten || '').toString().trim();
    const offerAudienceClause = sql`(
      offers.all_clients = true
      OR EXISTS (
        SELECT 1 FROM price_list_offer_clients oc
        JOIN clients oc_c ON oc_c.id = oc.client_id
        WHERE oc.offer_id = offers.id
          AND (oc_c.id = ${offerClientId} OR (${offerClientRut} <> '' AND oc_c.rten = ${offerClientRut}))
      )
    )`;

    const VALID_TIERS = new Set(['lista', 'desc10', 'desc10_5', 'desc10_5_3', 'minimo', 'canalDigital', 'mix', 'oferta']);

    const skus = Array.from(new Set(
      items
        .filter((it: any) => it?.type !== 'custom')
        .map((it: any) => (it.sku || it.productCode || '').toString().trim().toUpperCase())
        .filter(Boolean)
    ));

    // Maps keyed by uppercased SKU
    const listPriceMap = new Map<string, number>();
    const offerPriceMap = new Map<string, number>();
    // Full per-tier maps (only populated when at least one item asks for a specific tier).
    const tierPriceMaps: Record<string, Map<string, number>> = {
      lista: new Map(),
      desc10: new Map(),
      desc10_5: new Map(),
      desc10_5_3: new Map(),
      minimo: new Map(),
      canalDigital: new Map(),
      mix: new Map(),
      oferta: new Map(),
    };
    const needsTierLookup = items.some((it: any) => it?.priceTier && VALID_TIERS.has(it.priceTier));

    if (skus.length > 0) {
      const skuList = sql.join(skus.map(s => sql`${s}`), sql`, `);
      const result: any = useCustomList
        ? await db.execute(sql`
            SELECT UPPER(pl.codigo) AS codigo,
                   COALESCE(cpli.precio, pl.lista) AS precio,
                   COALESCE(offers.precio, pl.offer_price) AS offer_price
            FROM price_list pl
            LEFT JOIN custom_price_list_items cpli
              ON UPPER(cpli.codigo) = UPPER(pl.codigo)
             AND cpli.list_code = ${priceListCode}
            LEFT JOIN price_list_offers offers
              ON UPPER(offers.codigo) = UPPER(pl.codigo) AND (offers.paused IS NULL OR offers.paused = false) AND ${offerAudienceClause}
            WHERE UPPER(pl.codigo) IN (${skuList})
          `)
        : await db.execute(sql`
            SELECT UPPER(pl.codigo) AS codigo,
                   pl.lista AS precio,
                   COALESCE(offers.precio, pl.offer_price) AS offer_price
            FROM price_list pl
            LEFT JOIN price_list_offers offers
              ON UPPER(offers.codigo) = UPPER(pl.codigo) AND (offers.paused IS NULL OR offers.paused = false) AND ${offerAudienceClause}
            WHERE UPPER(pl.codigo) IN (${skuList})
          `);
      const rows = Array.isArray(result) ? result : (result.rows || []);
      for (const row of rows as any[]) {
        if (!row.codigo) continue;
        if (row.precio != null) listPriceMap.set(row.codigo, parseFloat(row.precio));
        if (row.offer_price != null && parseFloat(row.offer_price) > 0) {
          offerPriceMap.set(row.codigo, parseFloat(row.offer_price));
        }
      }

      if (needsTierLookup) {
        const tierRes: any = await db.execute(sql`
          SELECT UPPER(pl.codigo) AS codigo,
                 pl.lista, pl.desc10, pl.desc10_5, pl.desc10_5_3, pl.minimo, pl.canal_digital,
                 pl.offer_price,
                 mix.precio AS mix_precio,
                 offers.precio AS offer_precio
          FROM price_list pl
          LEFT JOIN price_list_mix mix
            ON UPPER(mix.codigo) = UPPER(pl.codigo)
          LEFT JOIN price_list_offers offers
            ON UPPER(offers.codigo) = UPPER(pl.codigo) AND (offers.paused IS NULL OR offers.paused = false) AND ${offerAudienceClause}
          WHERE UPPER(pl.codigo) IN (${skuList})
        `);
        const tierRows = Array.isArray(tierRes) ? tierRes : (tierRes.rows || []);
        for (const row of tierRows as any[]) {
          if (!row.codigo) continue;
          const setIfPositive = (map: Map<string, number>, v: any) => {
            const n = parseFloat(v?.toString() || '0');
            if (n > 0) map.set(row.codigo, n);
          };
          // lista fallback: si viene 0/null pero hay desc10, derivamos lista = desc10 / 0.9
          let listaVal = parseFloat(row.lista?.toString() || '0');
          if (!(listaVal > 0)) {
            const d10 = parseFloat(row.desc10?.toString() || '0');
            if (d10 > 0) listaVal = Math.round(d10 / 0.9);
          }
          if (listaVal > 0) tierPriceMaps.lista.set(row.codigo, listaVal);
          setIfPositive(tierPriceMaps.desc10, row.desc10);
          setIfPositive(tierPriceMaps.desc10_5, row.desc10_5);
          setIfPositive(tierPriceMaps.desc10_5_3, row.desc10_5_3);
          setIfPositive(tierPriceMaps.minimo, row.minimo);
          setIfPositive(tierPriceMaps.canalDigital, row.canal_digital);
          setIfPositive(tierPriceMaps.mix, row.mix_precio);
          const offerVal = parseFloat(row.offer_precio?.toString() || row.offer_price?.toString() || '0');
          if (offerVal > 0) tierPriceMaps.oferta.set(row.codigo, offerVal);
        }
      }
    }

    const warnings: string[] = [];
    const discountFactor = branchDiscountPct > 0 && branchDiscountPct <= 100 ? 1 - branchDiscountPct / 100 : 1;

    const resolvedItems = items.map((it: any) => {
      // ── Producto personalizado: pass-through, sin lookup ────────────────
      if (it?.type === 'custom') {
        const customUnit = Math.max(0, Math.round(Number(it.unitPrice ?? it.price ?? 0) || 0));
        const qty = Number(it.quantity) || 0;
        const total = Math.round(customUnit * qty);
        return {
          ...it,
          type: 'custom',
          unitPrice: customUnit,
          totalPrice: total,
          discountAmount: 0,
          unitPriceAfterDiscount: customUnit,
          totalPriceAfterDiscount: total,
          priceSource: 'custom',
          isOffer: false,
        };
      }

      const sku = (it.sku || it.productCode || '').toString().trim().toUpperCase();

      // ── Tier explícito elegido por el vendedor (sugerido) ────────────────
      if (it?.priceTier && VALID_TIERS.has(it.priceTier)) {
        const tier = it.priceTier as keyof typeof tierPriceMaps;
        const tierPrice = sku ? tierPriceMaps[tier]?.get(sku) : undefined;
        if (tierPrice != null && tierPrice > 0) {
          const unitPrice = Math.max(0, Math.round(tierPrice));
          const qty = Number(it.quantity) || 0;
          const totalPrice = Math.round(unitPrice * qty);
          return {
            ...it,
            unitPrice,
            totalPrice,
            discountAmount: 0,
            unitPriceAfterDiscount: unitPrice,
            totalPriceAfterDiscount: totalPrice,
            priceSource: `tier:${tier}`,
            isOffer: tier === 'oferta',
          };
        }
        warnings.push(`Tier ${tier} no disponible para SKU ${sku || '(sin SKU)'}: usando lista del cliente`);
      }

      // ── Comportamiento default: lista del cliente + offers + convenio ────
      const listPrice = sku ? listPriceMap.get(sku) : undefined;
      const offerPrice = sku ? offerPriceMap.get(sku) : undefined;

      if (listPrice == null && offerPrice == null) {
        warnings.push(`SKU no encontrado en lista ${priceListCode}: ${sku || it.productName || '(sin SKU)'}`);
        const fallback = Number(it.unitPrice ?? it.price ?? 0) || 0;
        const qty = Number(it.quantity) || 0;
        return {
          ...it,
          unitPrice: fallback,
          totalPrice: Math.round(fallback * qty),
          priceSource: 'fallback',
          isOffer: false,
        };
      }

      // If the SKU is on offer, use offer price as-is — do NOT apply convenio/branch discount.
      // Otherwise use list price with branch discount applied.
      const usingOffer = offerPrice != null;
      const unitPrice = usingOffer
        ? Math.max(0, Math.round(offerPrice!))
        : Math.max(0, Math.round((listPrice ?? 0) * discountFactor));
      const qty = Number(it.quantity) || 0;
      const totalPrice = Math.round(unitPrice * qty);

      return {
        ...it,
        unitPrice,
        totalPrice,
        discountAmount: 0,
        unitPriceAfterDiscount: unitPrice,
        totalPriceAfterDiscount: totalPrice,
        priceSource: usingOffer ? 'offer' : priceListCode,
        isOffer: usingOffer,
        ...(usingOffer
          ? {}
          : (branchDiscountPct > 0 ? { convenioPct: branchDiscountPct, originalUnitPrice: Math.round(listPrice ?? 0) } : {})),
      };
    });

    const subtotal = resolvedItems.reduce((s: number, it: any) => s + (Number(it.totalPrice) || 0), 0);
    const tax = Math.round(subtotal * 0.19);
    const total = subtotal + tax;

    return { items: resolvedItems, subtotal, tax, total, priceListUsed: priceListCode, branchDiscountPct, warnings };
  }

  // Resuelve el registro de cliente (tabla clients) + email destino a partir de
  // cualquiera de los identificadores. Usado por la creación y la preview de sugeridos.
  async function resolveSuggestedClient(opts: { clientUserId?: string | null; clientCode?: string | null; clientName?: string | null }): Promise<
    { ok: true; clientRecord: any; destEmail: string } | { ok: false; status: number; message: string }
  > {
    const { clientUserId, clientCode, clientName } = opts;
    if (!clientUserId && !clientCode && !clientName) {
      return { ok: false, status: 400, message: 'Debes indicar el cliente destino (userId, código o nombre).' };
    }

    const { clients: clientsTbl, users: usersTbl, salespeopleUsers: spUsersTbl } = await import('@shared/schema');
    const { eq: eqOp, and: andOp, isNotNull: isNotNullOp } = await import('drizzle-orm');

    let clientRecord: any = null;
    if (clientUserId) {
      const [byUser] = await db.select().from(clientsTbl).where(eqOp(clientsTbl.userId, clientUserId)).limit(1);
      if (byUser) clientRecord = byUser;
    }
    if (!clientRecord && clientCode) {
      const [byCode] = await db.select().from(clientsTbl)
        .where(andOp(eqOp(clientsTbl.koen, clientCode), isNotNullOp(clientsTbl.userId)))
        .limit(1);
      if (byCode) clientRecord = byCode;
      if (!clientRecord) {
        const [anyCode] = await db.select().from(clientsTbl).where(eqOp(clientsTbl.koen, clientCode)).limit(1);
        if (anyCode) clientRecord = anyCode;
      }
    }
    if (!clientRecord && clientName) {
      const [byName] = await db.select().from(clientsTbl)
        .where(andOp(eqOp(clientsTbl.nokoen, clientName), isNotNullOp(clientsTbl.userId)))
        .limit(1);
      if (byName) clientRecord = byName;
      if (!clientRecord) {
        const [anyName] = await db.select().from(clientsTbl).where(eqOp(clientsTbl.nokoen, clientName)).limit(1);
        if (anyName) clientRecord = anyName;
      }
    }

    if (!clientRecord) {
      return { ok: false, status: 404, message: 'No se encontró el cliente en la base de datos.' };
    }
    if (!clientRecord.userId) {
      return { ok: false, status: 400, message: 'Este cliente aún no tiene cuenta de usuario en el portal. Pídele que se registre antes de enviar un sugerido.' };
    }

    // `foen` es el teléfono, no el email: tomamos el primer email VÁLIDO de las fuentes reales y caemos a la cuenta del portal.
    const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const pickEmail = (...vals: Array<string | null | undefined>): string | null => {
      for (const v of vals) {
        const e = (v || '').trim();
        if (EMAIL_RE.test(e)) return e;
      }
      return null;
    };

    // El correo "principal" es el de la cuenta de portal (salespeople_users): es el que la
    // ficha muestra y edita (PATCH .../contact-info escribe ahí primero y lo espeja a
    // clients.email). Por eso lo resolvemos primero, con los mismos vínculos que GET
    // /api/users/clients, para enviar siempre a la dirección que ve el usuario.
    let destEmail: string | null = null;
    const tryDestFrom = async (cond: any) => {
      if (destEmail) return;
      try {
        const [sp] = await db.select().from(spUsersTbl).where(cond).limit(1);
        destEmail = pickEmail(sp?.email, sp?.publicEmail);
      } catch (_) { /* noop */ }
    };
    await tryDestFrom(eqOp(spUsersTbl.clientId, clientRecord.id));
    if (clientRecord.userId) await tryDestFrom(eqOp(spUsersTbl.id, clientRecord.userId));
    if (clientRecord.rten) await tryDestFrom(eqOp(spUsersTbl.clientRut, clientRecord.rten));

    // Respaldos: cuenta legacy (tabla users) y, por último, el correo espejado en la ficha SAP.
    if (!destEmail) {
      try {
        const [u] = await db.select().from(usersTbl).where(eqOp(usersTbl.id, clientRecord.userId)).limit(1);
        destEmail = pickEmail(u?.email);
      } catch (_) { /* noop */ }
    }
    if (!destEmail) destEmail = pickEmail(clientRecord.email, clientRecord.emailcomer);

    if (!destEmail) {
      return { ok: false, status: 400, message: 'El cliente no tiene un email válido registrado para recibir el sugerido.' };
    }

    return { ok: true, clientRecord, destEmail };
  }

  // Create order from client (authenticated clients only)
  app.post('/api/ecommerce/orders/client', requireAuth, asyncHandler(async (req: any, res: any) => {
    // Validate user is authenticated
    if (!req.user || !req.user.id) {
      return res.status(401).json({ message: 'No autenticado' });
    }

    try {
      // Validate request body - use relaxed schema without server-populated fields
      const clientOrderSchema = z.object({
        items: z.array(z.object({
          productId: z.string().optional(),
          productName: z.string(),
          sku: z.string().optional(),
          quantity: z.number().positive(),
          unitPrice: z.number().nonnegative(),
          totalPrice: z.number().nonnegative(),
          discountAmount: z.number().nonnegative().optional(),
          unitPriceAfterDiscount: z.number().nonnegative().optional(),
          totalPriceAfterDiscount: z.number().nonnegative().optional(),
        }).passthrough()),
        subtotal: z.number().nonnegative(),
        tax: z.number().nonnegative(),
        total: z.number().nonnegative(),
        discount: z.number().nonnegative().optional(),
        appliedCoupons: z.array(z.object({
          code: z.string(),
          type: z.string(),
          discount: z.number().nonnegative(),
          description: z.string().optional().nullable(),
          appliesTo: z.string().optional().nullable(),
          productSku: z.string().optional().nullable(),
        })).optional(),
        notes: z.string().optional().nullable(),
        shippingAddress: z.string().optional().nullable(),
        paymentCondition: z.string().optional().nullable(),
        paymentMethod: z.string().optional(),
        purchaseOrderPdfUrl: z.string().optional().nullable(),
        branchId: z.string().optional().nullable(),
      });

      const validationResult = clientOrderSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({
          message: 'Error de validación',
          errors: validationResult.error.errors
        });
      }

      const orderData = validationResult.data;
      const clientId = req.user.id;

      // Get client details to find assigned salesperson and price list (non-blocking).
      // If the cart carried a specific branchId (sucursal seleccionada en la tienda),
      // preferimos ESE registro: suele tener su propio lcen / branchDiscountPercent
      // y es el que el cliente vio al comprar. Sin branchId caemos al cliente por
      // defecto del usuario (comportamiento previo).
      let client: any = null;
      try {
        if (orderData.branchId) {
          const { clients: clientsTbl } = await import('@shared/schema');
          const { eq: eqOp } = await import('drizzle-orm');
          const { db: dbLookup } = await import('./db');
          const [branchRecord] = await dbLookup
            .select()
            .from(clientsTbl)
            .where(eqOp(clientsTbl.id, orderData.branchId))
            .limit(1);
          if (branchRecord) client = branchRecord;
        }
        if (!client) {
          client = await storage.getClientByUserId(clientId);
        }
      } catch (clientErr) {
        console.warn('Warning: Could not fetch client details, proceeding without:', clientErr);
      }

      // Enforce OC para clientes MCT. Identificamos MCT por el nombre del cliente
      // (nokoen) o el de su casa matriz: la nomenclatura interna es "MCT <plaza>"
      // (ej. "MCT CONCEPCION"). Sin OC no se permite crear el pedido.
      try {
        let names = `${client?.nokoen || ''} ${client?.gien || ''}`;
        if (client?.parentClientId) {
          const { clients: clientsTbl } = await import('@shared/schema');
          const { eq: eqOp } = await import('drizzle-orm');
          const { db: dbLookup } = await import('./db');
          const [parent] = await dbLookup
            .select({ nokoen: clientsTbl.nokoen, gien: clientsTbl.gien })
            .from(clientsTbl)
            .where(eqOp(clientsTbl.id, client.parentClientId))
            .limit(1);
          if (parent) names += ` ${parent.nokoen || ''} ${parent.gien || ''}`;
        }
        const isMCT = /\bMCT\b/i.test(names);
        if (isMCT && !orderData.purchaseOrderPdfUrl) {
          return res.status(400).json({
            message: 'Los clientes MCT deben adjuntar la Orden de Compra (PDF) para confirmar el pedido.',
          });
        }
      } catch (segErr) {
        console.warn('Warning: Could not validate MCT OC requirement:', segErr);
      }

      // Authoritative server-side price resolution based on customer's assigned lcen price list.
      // Overrides frontend-supplied unitPrice to eliminate price-list mismatches.
      // Candado de precios: el cliente NO puede elegir lista (priceTier) ni colar
      // productos "custom" (precio libre). Eso lo hace sólo el equipo comercial.
      // Limpiamos esos campos para que cada línea se resuelva con la lista de
      // contrato del cliente (lcen) + ofertas + descuento por sucursal.
      const sanitizedItems = (orderData.items as any[]).map((it: any) => {
        const { priceTier, type, ...rest } = it;
        return rest;
      });
      const resolved = await resolveItemsPricing(sanitizedItems, client);
      if (resolved.warnings.length) {
        console.warn(`[orders/client] Price resolution warnings for user ${clientId}:`, resolved.warnings);
      }
      console.log(`[orders/client] Applied price list ${resolved.priceListUsed}${resolved.branchDiscountPct ? ` + ${resolved.branchDiscountPct}% branch discount` : ''} for user ${clientId}`);

      // Prepare order data with client and salesperson info
      const isCreditMethod = orderData.paymentMethod === 'credit';
      // Si el pedido trae OC adjunta, queda en pendiente aunque sea a crédito:
      // la recepcionista debe revisarlo y aprobar antes de consumir el cupo.
      const hasPurchaseOrder = !!orderData.purchaseOrderPdfUrl;
      const shouldAutoApprove = isCreditMethod && !hasPurchaseOrder;

      const orderToCreate: any = {
        items: resolved.items,
        subtotal: String(resolved.subtotal),
        tax: String(resolved.tax),
        total: String(resolved.total),
        branchDiscountPercent: String(resolved.branchDiscountPct || 0),
        priceListUsed: resolved.priceListUsed,
        clientId,
        // Usamos el nokoen del cliente (ej. "ELECTROCOM S.A. - MCT VALDIVIA") cuando
        // está disponible, así el panel admin/recepción y el portal del cliente
        // identifican el pedido por la razón social/sucursal — no por el nombre del
        // usuario operador. Caemos al nombre del user sólo si no hay registro de cliente.
        clientName: client?.nokoen
          || (req.user.firstName ? `${req.user.firstName} ${req.user.lastName || ''}`.trim() : (req.user.email || 'Cliente')),
        clientEmail: req.user.email,
        assignedSalespersonId: client?.assignedSalespersonUserId || null,
        assignedSalespersonName: null,
        status: shouldAutoApprove ? 'approved' : 'pending',
        paymentCondition: isCreditMethod ? 'Crédito' : 'Transferencia',
        notes: orderData.notes || null,
        shippingAddress: orderData.shippingAddress || null,
        purchaseOrderPdfUrl: orderData.purchaseOrderPdfUrl || null,
        ...(shouldAutoApprove ? { approvedAt: new Date(), approvedById: clientId } : {}),
      };

      // If there's an assigned salesperson, get their name
      if (client?.assignedSalespersonUserId) {
        try {
          const salesperson = await storage.getUser(client.assignedSalespersonUserId);
          if (salesperson) {
            orderToCreate.assignedSalespersonName = salesperson.salespersonName || salesperson.email || 'Vendedor';
          }
        } catch (spErr) {
          console.warn('Warning: Could not fetch salesperson details:', spErr);
        }
      }

      // Create the order
      const order = await storage.createEcommerceOrder(orderToCreate);

      // Process credit updates if the order is automatically approved (credit payment).
      // OC-attached credit orders stay pending — credit is consumed when the receptionist approves.
      if (shouldAutoApprove) {
        try {
          const { salespeopleUsers, users, clients } = await import('@shared/schema');
          const { eq, or, desc } = await import('drizzle-orm');
          const { db } = await import('./db');
          
          let clientRecordMatch = null;
          if (clientId) {
            // Find user to map to client
            const sUser = await db.select().from(salespeopleUsers).where(eq(salespeopleUsers.id, clientId)).limit(1);
            const legacyUser = sUser.length === 0 ? await db.select().from(users).where(eq(users.id, clientId)).limit(1) : null;
            
            const userName = sUser[0]?.salespersonName || legacyUser[0]?.firstName || null;
            
            if (userName) {
              const possibleClients = await db.select().from(clients)
                .where(or(
                  eq(clients.userId, clientId),
                  eq(clients.nokoen, userName.toUpperCase())
                ))
                .orderBy(desc(clients.updatedAt))
                .limit(1);
                
              if (possibleClients.length > 0) {
                clientRecordMatch = possibleClients[0];
              }
            }
          }
          
          if (clientRecordMatch && clientRecordMatch.crlt) {
            const limit = parseFloat(clientRecordMatch.crlt) || 0;
            const used = parseFloat(clientRecordMatch.crsd || '0') || 0;
            const orderTotal = resolved.total;

            const newUsed = used + orderTotal;
            const newAvailable = Math.max(0, limit - newUsed);

            await db.update(clients).set({
              crsd: newUsed.toString(),
              cren: newAvailable.toString()
            }).where(eq(clients.id, clientRecordMatch.id));
          }
        } catch (e) {
          console.error('Error updating client credit on direct order approval:', e);
        }
      }

      // Create notification for salesperson or admin (non-blocking)
      try {
        const notificationUserId = orderToCreate.assignedSalespersonId || await storage.getAdminUserId();
        if (notificationUserId) {
          await storage.createNotification({
            userId: notificationUserId,
            type: 'ecommerce_order',
            title: hasPurchaseOrder
              ? 'Pedido con OC — requiere revisión'
              : 'Nuevo pedido de cliente',
            message: `${orderToCreate.clientName} ha realizado un pedido por $${resolved.total.toFixed(0)}${hasPurchaseOrder ? ' con OC adjunta. Revisa antes de aprobar.' : ''}`,
            relatedOrderId: order.id,
            read: false
          });
        }
      } catch (notifErr) {
        console.warn('Warning: Notification creation failed, order was still created:', notifErr);
      }

      // Email notification for new store order (pedido_nuevo)
      try {
        await NotifyHelper.notifyNuevaOrden(
          order.id,
          orderToCreate.clientName || 'Cliente',
          Number(resolved.total) || 0
        );
      } catch (notifErr) {
        console.warn('Warning: notifyNuevaOrden failed:', notifErr);
      }

      // Customer-facing auto-confirmation email
      try {
        if (orderToCreate.clientEmail) {
          const { buildOrderReceivedEmail } = await import('./email-templates');
          const items = (resolved.items || []).map((it: any) => ({
            name: it.productName || it.name || it.sku || 'Producto',
            quantity: Number(it.quantity) || 1,
            price: Number(it.totalPriceAfterDiscount ?? it.totalPrice) || undefined,
          }));
          const built = buildOrderReceivedEmail({
            clientName: orderToCreate.clientName || 'Cliente',
            orderNumber: order.id,
            total: Number(resolved.total) || 0,
            items,
          });
          await NotifyHelper.sendAutoCustomerEmail({
            notificationType: 'ecommerce_sale_auto',
            to: orderToCreate.clientEmail,
            subject: built.subject,
            html: built.html,
          });
        }
      } catch (autoErr) {
        console.warn('Warning: auto-confirmation email failed:', autoErr);
      }

      // Internal staff notification — pedidos de Panorámica Market.
      // Va siempre (no depende del toggle de emailNotificationSettings) a
      // contacto@pinturaspanoramica.cl con copia a fparra@pinturaspanoramica.cl.
      try {
        const { buildOrderInternalNotifyEmail } = await import('./email-templates');
        const itemsForEmail = (resolved.items || []).map((it: any) => ({
          name: it.productName || it.name || it.sku || 'Producto',
          quantity: Number(it.quantity) || 1,
          price: Number(it.totalPriceAfterDiscount ?? it.totalPrice) || undefined,
        }));
        const built = buildOrderInternalNotifyEmail({
          orderNumber: order.id,
          clientName: orderToCreate.clientName || 'Cliente',
          clientEmail: orderToCreate.clientEmail || null,
          clientRut: client?.ruen || null,
          clientPhone: (client as any)?.foen || (client as any)?.fichaOverrides?.phone || null,
          total: Number(resolved.total) || 0,
          subtotal: Number(resolved.subtotal) || 0,
          tax: Number(resolved.tax) || 0,
          paymentCondition: orderToCreate.paymentCondition || null,
          shippingAddress: orderToCreate.shippingAddress || null,
          notes: orderToCreate.notes || null,
          status: orderToCreate.status === 'approved' ? 'Aprobado' : 'Pendiente de aprobación',
          items: itemsForEmail,
        });
        await emailService.sendEmail({
          to: 'contacto@pinturaspanoramica.cl',
          cc: 'fparra@pinturaspanoramica.cl',
          subject: built.subject,
          html: built.html,
        });
      } catch (internalErr) {
        console.warn('Warning: internal order notification email failed:', internalErr);
      }

      res.status(201).json(order);
    } catch (error: any) {
      console.error('Error creating client order:', error);
      res.status(500).json({ message: 'Error al crear el pedido', detail: error?.message || 'Unknown error' });
    }
  }));

  // ==================================================================================
  // PEDIDOS SUGERIDOS — admin/supervisor envía un pedido pre-armado al cliente.
  // El cliente recibe correo y puede aceptar / modificar / rechazar desde su portal.
  // ==================================================================================

  // Admin/Supervisor crea un sugerido para un cliente.
  app.post('/api/ecommerce/orders/suggested', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const suggestedBy = req.user;
      const schema = z.object({
        // Identificadores del cliente — al menos uno debe permitir resolver al usuario
        clientUserId: z.string().optional().nullable(),
        clientCode: z.string().optional().nullable(),
        clientName: z.string().optional().nullable(),
        items: z.array(z.object({
          type: z.enum(['standard', 'custom']).optional(),
          productId: z.string().optional(),
          productName: z.string(),
          sku: z.string().optional(),
          customSku: z.string().optional(),
          quantity: z.number().positive(),
          unitPrice: z.number().nonnegative().optional(),
          totalPrice: z.number().nonnegative().optional(),
          priceTier: z.enum(['lista', 'desc10', 'desc10_5', 'desc10_5_3', 'minimo', 'canalDigital', 'mix', 'oferta']).optional(),
          productUnit: z.string().optional(),
          productColor: z.string().optional(),
          costOfProduction: z.number().nonnegative().optional(),
          profitMargin: z.number().optional(),
          pricingMode: z.enum(['calculated', 'direct']).optional(),
        }).passthrough()).min(1, 'Debes agregar al menos un producto'),
        notes: z.string().optional().nullable(),
        sendEmail: z.boolean().optional(),
        teamRecipient: z.string().optional().nullable(),
        teamCc: z.string().optional().nullable(),
        teamMessage: z.string().optional().nullable(),
      });
      const parsed = schema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      }
      const { clientUserId, clientCode, clientName, items, notes, sendEmail: shouldSendEmail = true, teamRecipient, teamCc, teamMessage } = parsed.data;

      const clientResolution = await resolveSuggestedClient({ clientUserId, clientCode, clientName });
      if (!clientResolution.ok) {
        return res.status(clientResolution.status).json({ message: clientResolution.message });
      }
      const { clientRecord, destEmail } = clientResolution;

      // Resolver precios con la lista del cliente destino
      const resolved = await resolveItemsPricing(items, clientRecord);
      if (resolved.warnings.length) {
        console.warn(`[orders/suggested] price resolution warnings:`, resolved.warnings);
      }

      const suggestedByName = (suggestedBy.salespersonName
        || `${suggestedBy.firstName || ''} ${suggestedBy.lastName || ''}`.trim()
        || suggestedBy.email
        || 'Equipo Panorámica').trim();

      const order = await storage.createEcommerceOrder({
        items: resolved.items,
        subtotal: String(resolved.subtotal),
        tax: String(resolved.tax),
        total: String(resolved.total),
        branchDiscountPercent: String(resolved.branchDiscountPct || 0),
        priceListUsed: resolved.priceListUsed,
        clientId: clientRecord.userId,
        clientName: clientRecord.nokoen || clientRecord.gien || 'Cliente',
        clientEmail: destEmail,
        assignedSalespersonId: clientRecord.assignedSalespersonUserId || null,
        status: 'suggested_pending',
        notes: notes || null,
        isSuggested: true,
        suggestedById: suggestedBy.id,
        suggestedByName,
        suggestedAt: new Date(),
      });

      // Notificación interna al vendedor asignado (no bloquea)
      try {
        if (clientRecord.assignedSalespersonUserId) {
          await storage.createNotification({
            userId: clientRecord.assignedSalespersonUserId,
            type: 'ecommerce_order',
            title: 'Sugerido enviado a cliente',
            message: `${suggestedByName} envió un pedido sugerido a ${order.clientName} por $${Number(resolved.total).toFixed(0)}`,
            relatedOrderId: order.id,
            read: false,
          });
        }
      } catch (notifErr) {
        console.warn('Warning: notification for suggested order failed:', notifErr);
      }

      // Envío de correos (no bloquea la creación del sugerido). Registramos el
      // resultado en emailLogs y lo devolvemos al frontend para que avise.
      const TAG_EMAIL = '[orders/suggested:email]';
      let emailDelivered = false;
      let emailError: string | null = null;
      // baseUrl: PUBLIC_APP_URL > APP_URL > Origin del request (fallback para que el link del email no quede roto)
      const originHeader = (req.headers?.origin as string | undefined) || '';
      const refererHeader = (req.headers?.referer as string | undefined) || '';
      const refererOrigin = (() => { try { return refererHeader ? new URL(refererHeader).origin : ''; } catch { return ''; } })();
      const baseUrl = (
        process.env.PUBLIC_APP_URL || process.env.APP_URL || originHeader || refererOrigin || ''
      ).replace(/\/+$/, '');
      const orderUrl = `${baseUrl || ''}/mis-pedidos`;

      if (shouldSendEmail) {
        let logId: string | undefined;
        const { buildSuggestedOrderEmail, buildSuggestedTeamCopyEmail } = await import('./email-templates');
        const { renderSuggestedOrderPdf } = await import('./utils/suggested-pdf');
        const { emailService } = await import('./services/email');

        const proto = (req.headers['x-forwarded-proto'] as string) || req.protocol || 'https';
        const host = req.headers['x-forwarded-host'] || req.headers.host || 'ai.pinturaspanoramica.cl';
        const logoUrl = `${proto}://${host}/panoramica-logo.png`;

        const emailItems = (resolved.items || []).map((it: any) => ({
          name: it.productName || it.name || it.sku || 'Producto',
          quantity: Number(it.quantity) || 1,
          price: Number(it.totalPriceAfterDiscount ?? it.totalPrice) || undefined,
        }));

        // PDF del sugerido — mismo documento que el tomador, rotulado "PEDIDO SUGERIDO".
        let pdfBuffer: Buffer | null = null;
        try {
          pdfBuffer = await renderSuggestedOrderPdf({
            orderNumber: order.id,
            clientName: order.clientName || 'Cliente',
            clientRut: clientRecord.rten || null,
            clientEmail: destEmail,
            clientPhone: clientRecord.cnen || null,
            clientAddress: clientRecord.dien || order.shippingAddress || null,
            notes: notes || null,
            createdAt: order.suggestedAt || order.createdAt || new Date(),
            items: resolved.items,
            logoUrl,
          });
        } catch (pdfErr: any) {
          console.warn(`${TAG_EMAIL} ⚠️ no se pudo generar PDF del sugerido:`, pdfErr?.message);
        }
        const attachments = pdfBuffer
          ? [{ filename: `Sugerido_${order.id.slice(0, 8)}.pdf`, content: pdfBuffer, contentType: 'application/pdf' }]
          : undefined;

        // 1) Correo al cliente (estética + PDF adjunto + botón aceptar/responder)
        const built = buildSuggestedOrderEmail({
          clientName: order.clientName || 'Cliente',
          orderNumber: order.id,
          total: Number(resolved.total) || 0,
          items: emailItems,
          suggestedByName,
          notes: notes || null,
          orderUrl,
        });
        try {
          const logEntry = await db.insert(emailLogs).values({
            recipient: destEmail,
            subject: built.subject,
            notificationType: 'ecommerce_suggested_order',
            status: 'pending',
          }).returning({ id: emailLogs.id });
          logId = logEntry[0]?.id;
        } catch (logErr: any) {
          console.warn(`${TAG_EMAIL} no se pudo insertar en emailLogs:`, logErr?.message);
        }
        try {
          console.log(`${TAG_EMAIL} 📤 enviando a cliente ${destEmail} (orderId=${order.id})`);
          await emailService.sendEmail({ to: destEmail, subject: built.subject, html: built.html, attachments });
          emailDelivered = true;
          if (logId) {
            await db.update(emailLogs).set({ status: 'sent', sentAt: new Date() }).where(eq(emailLogs.id, logId));
          }
        } catch (emailErr: any) {
          emailError = emailErr?.message || 'Error desconocido al enviar el correo';
          console.error(`${TAG_EMAIL} ❌ Error enviando sugerido al cliente:`, { message: emailErr?.message, code: emailErr?.code });
          if (logId) {
            try { await db.update(emailLogs).set({ status: 'failed', errorMessage: emailError }).where(eq(emailLogs.id, logId)); } catch (_) { /* noop */ }
          }
        }

        // 2) Copia interna al equipo (mismo formato que "nuevo pedido", con PDF).
        //    Por defecto va al correo del usuario que arma el sugerido.
        const teamTo = (teamRecipient && teamRecipient.trim()) || suggestedBy.email || '';
        if (teamTo) {
          try {
            const teamBuilt = buildSuggestedTeamCopyEmail({
              clientName: order.clientName || 'Cliente',
              clientEmail: destEmail,
              orderNumber: order.id,
              total: Number(resolved.total) || 0,
              items: emailItems,
              suggestedByName,
              notes: notes || null,
              teamMessage: teamMessage || null,
            });
            await emailService.sendEmail({
              to: teamTo,
              cc: (teamCc && teamCc.trim()) || undefined,
              subject: teamBuilt.subject,
              html: teamBuilt.html,
              attachments,
            });
          } catch (teamErr: any) {
            console.warn(`${TAG_EMAIL} ⚠️ no se pudo enviar copia al equipo:`, teamErr?.message);
          }
        }
      }

      res.status(201).json({ ...order, emailDelivered, emailError, emailTo: shouldSendEmail ? destEmail : null });
    } catch (error: any) {
      console.error('Error creating suggested order:', error);
      res.status(500).json({ message: 'Error al crear el sugerido', detail: error?.message || 'Unknown error' });
    }
  }));

  // Preview del PDF del sugerido SIN persistir — para que el admin lo revise antes de enviar.
  app.post('/api/ecommerce/orders/suggested/preview', requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const schema = z.object({
        clientUserId: z.string().optional().nullable(),
        clientCode: z.string().optional().nullable(),
        clientName: z.string().optional().nullable(),
        items: z.array(z.object({
          type: z.enum(['standard', 'custom']).optional(),
          productName: z.string(),
          sku: z.string().optional(),
          customSku: z.string().optional(),
          quantity: z.number().positive(),
          unitPrice: z.number().nonnegative().optional(),
          totalPrice: z.number().nonnegative().optional(),
          priceTier: z.enum(['lista', 'desc10', 'desc10_5', 'desc10_5_3', 'minimo', 'canalDigital', 'mix', 'oferta']).optional(),
          productUnit: z.string().optional(),
          productColor: z.string().optional(),
          selectedPackaging: z.string().optional(),
          costOfProduction: z.number().nonnegative().optional(),
          profitMargin: z.number().optional(),
          pricingMode: z.enum(['calculated', 'direct']).optional(),
        }).passthrough()).min(1, 'Debes agregar al menos un producto'),
        notes: z.string().optional().nullable(),
      });
      const parsed = schema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      }
      const { clientUserId, clientCode, clientName, items, notes } = parsed.data;

      const clientResolution = await resolveSuggestedClient({ clientUserId, clientCode, clientName });
      if (!clientResolution.ok) {
        return res.status(clientResolution.status).json({ message: clientResolution.message });
      }
      const { clientRecord, destEmail } = clientResolution;

      const resolved = await resolveItemsPricing(items, clientRecord);

      const { renderSuggestedOrderPdf } = await import('./utils/suggested-pdf');
      const proto = (req.headers['x-forwarded-proto'] as string) || req.protocol || 'https';
      const host = req.headers['x-forwarded-host'] || req.headers.host || 'ai.pinturaspanoramica.cl';
      const logoUrl = `${proto}://${host}/panoramica-logo.png`;

      const pdfBuffer = await renderSuggestedOrderPdf({
        orderNumber: 'BORRADOR',
        clientName: clientRecord.nokoen || clientRecord.gien || 'Cliente',
        clientRut: clientRecord.rten || null,
        clientEmail: destEmail,
        clientPhone: clientRecord.cnen || null,
        clientAddress: clientRecord.dien || null,
        notes: notes || null,
        createdAt: new Date(),
        items: resolved.items,
        logoUrl,
      });

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="Sugerido_preview.pdf"');
      return res.send(pdfBuffer);
    } catch (error: any) {
      console.error('Error generating suggested preview PDF:', error);
      res.status(500).json({ message: 'Error al generar la vista previa', detail: error?.message || 'Unknown error' });
    }
  }));

  // PDF de un sugerido ya creado (para reenvío / descarga desde el panel).
  app.get('/api/ecommerce/orders/:id/pdf', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      const orderId = req.params.id;
      const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, orderId)).limit(1);
      if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });

      const isAdmin = user.role === 'admin' || user.role === 'supervisor';
      if (!isAdmin && order.clientId !== user.id) {
        return res.status(403).json({ message: 'No autorizado' });
      }

      // Datos del cliente (RUT/dirección) desde la tabla clients vía userId.
      let clientRecord: any = null;
      try {
        const { clients: clientsTbl } = await import('@shared/schema');
        const [c] = await db.select().from(clientsTbl).where(eq(clientsTbl.userId, order.clientId)).limit(1);
        if (c) clientRecord = c;
      } catch (_) { /* noop */ }

      const { renderSuggestedOrderPdf } = await import('./utils/suggested-pdf');
      const proto = (req.headers['x-forwarded-proto'] as string) || req.protocol || 'https';
      const host = req.headers['x-forwarded-host'] || req.headers.host || 'ai.pinturaspanoramica.cl';
      const logoUrl = `${proto}://${host}/panoramica-logo.png`;

      const pdfBuffer = await renderSuggestedOrderPdf({
        orderNumber: order.id,
        clientName: order.clientName || clientRecord?.nokoen || 'Cliente',
        clientRut: clientRecord?.rten || null,
        clientEmail: order.clientEmail || null,
        clientPhone: clientRecord?.cnen || order.clientPhone || null,
        clientAddress: clientRecord?.dien || order.shippingAddress || null,
        notes: order.notes || null,
        createdAt: order.suggestedAt || order.createdAt || new Date(),
        items: Array.isArray(order.items) ? order.items : [],
        logoUrl,
      });

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Sugerido_${order.id.slice(0, 8)}.pdf"`);
      return res.send(pdfBuffer);
    } catch (error: any) {
      console.error('Error generating suggested order PDF:', error);
      res.status(500).json({ message: 'Error al generar el PDF', detail: error?.message || 'Unknown error' });
    }
  }));

  // ── Helpers para el "checkout" de un sugerido (aceptar/modificar) ──────────
  // Detecta si el cliente pertenece al segmento MCT (nombre del cliente, su giro
  // o el de la casa matriz contienen el token "MCT"). Para MCT la OC es obligatoria.
  const detectMCTClient = async (clientRecord: any): Promise<boolean> => {
    if (!clientRecord) return false;
    let names = `${clientRecord.nokoen || ''} ${clientRecord.gien || ''}`;
    if (clientRecord.parentClientId) {
      try {
        const { clients: clientsTbl } = await import('@shared/schema');
        const { eq: eqOp } = await import('drizzle-orm');
        const { db: dbLookup } = await import('./db');
        const [parent] = await dbLookup
          .select({ nokoen: clientsTbl.nokoen, gien: clientsTbl.gien })
          .from(clientsTbl)
          .where(eqOp(clientsTbl.id, clientRecord.parentClientId))
          .limit(1);
        if (parent) names += ` ${parent.nokoen || ''} ${parent.gien || ''}`;
      } catch (e) {
        console.warn('Warning: could not load parent client for MCT detection:', e);
      }
    }
    return /\bMCT\b/i.test(names);
  };

  // Consume cupo de crédito del cliente (por userId) al aprobar un pedido a crédito.
  // Mantiene la misma semántica que el checkout: crsd = usado/deuda, cren = disponible.
  const consumeClientCreditForUser = async (userId: string, orderTotal: number): Promise<void> => {
    try {
      const { clients: clientsTbl } = await import('@shared/schema');
      const { eq: eqOp } = await import('drizzle-orm');
      const { db: dbLookup } = await import('./db');
      const [rec] = await dbLookup.select().from(clientsTbl).where(eqOp(clientsTbl.userId, userId)).limit(1);
      if (!rec || !rec.crlt) return;
      const limit = parseFloat(rec.crlt as any) || 0;
      const used = parseFloat((rec.crsd as any) || '0') || 0;
      const newUsed = used + (Number(orderTotal) || 0);
      const newAvailable = Math.max(0, limit - newUsed);
      await dbLookup.update(clientsTbl)
        .set({ crsd: newUsed.toString(), cren: newAvailable.toString() })
        .where(eqOp(clientsTbl.id, rec.id));
    } catch (e) {
      console.error('Error consuming client credit (suggested order):', e);
    }
  };

  // Cliente acepta el sugerido → elige forma de pago (transferencia/crédito) y, si
  // corresponde, adjunta la OC. Igual que el checkout del ecommerce: a crédito se
  // aprueba y se consume cupo; por transferencia queda pendiente para subir el
  // comprobante en la pantalla de pedido confirmado.
  app.post('/api/ecommerce/orders/:id/suggested-accept', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      const orderId = req.params.id;
      const schema = z.object({
        paymentMethod: z.enum(['transfer', 'credit']).optional(),
        purchaseOrderPdfUrl: z.string().optional().nullable(),
      });
      const parsed = schema.safeParse(req.body || {});
      if (!parsed.success) return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      const paymentMethod = parsed.data.paymentMethod || 'transfer';
      const purchaseOrderPdfUrl = parsed.data.purchaseOrderPdfUrl || null;

      const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, orderId)).limit(1);
      if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });
      if (order.clientId !== user.id) return res.status(403).json({ message: 'No autorizado' });
      if (!order.isSuggested || order.status !== 'suggested_pending') {
        return res.status(400).json({ message: 'Este pedido no está en estado de sugerido pendiente.' });
      }

      // OC obligatoria para clientes MCT (igual que el checkout del ecommerce).
      const clientRecord = await storage.getClientByUserId(order.clientId).catch(() => null);
      const finalOcUrl = purchaseOrderPdfUrl || order.purchaseOrderPdfUrl || null;
      if (await detectMCTClient(clientRecord) && !finalOcUrl) {
        return res.status(400).json({ message: 'Los clientes MCT deben adjuntar la Orden de Compra (PDF) para confirmar el pedido.' });
      }

      const isCreditMethod = paymentMethod === 'credit';
      // OC adjunta + crédito → queda pendiente para la recepcionista
      const hasPurchaseOrder = !!finalOcUrl;
      const shouldAutoApprove = isCreditMethod && !hasPurchaseOrder;
      const now = new Date();
      const [updated] = await db.update(ecommerceOrders)
        .set({
          status: shouldAutoApprove ? 'approved' : 'pending',
          paymentCondition: isCreditMethod ? 'Crédito' : 'Transferencia',
          purchaseOrderPdfUrl: finalOcUrl,
          suggestedResponseAt: now,
          updatedAt: now,
          ...(shouldAutoApprove ? { approvedAt: now, approvedById: user.id } : {}),
        })
        .where(eq(ecommerceOrders.id, orderId))
        .returning();

      // A crédito: aprobación inmediata y consumo de cupo (igual que el checkout).
      // Si hay OC, el cupo se consume cuando la recepcionista apruebe.
      if (shouldAutoApprove) {
        await consumeClientCreditForUser(order.clientId, Number(order.total) || 0);
      }

      // Notificar al vendedor asignado / supervisor / admin
      try {
        const notifyTo = order.assignedSalespersonId || order.suggestedById || await storage.getAdminUserId();
        if (notifyTo) {
          await storage.createNotification({
            userId: notifyTo,
            type: 'ecommerce_order',
            title: 'Sugerido aceptado por cliente',
            message: `${order.clientName} aceptó el sugerido por $${Number(order.total).toFixed(0)} (${isCreditMethod ? 'Crédito' : 'Transferencia'})`,
            relatedOrderId: order.id,
            read: false,
          });
        }
      } catch (notifErr) {
        console.warn('Warning: notify on suggested-accept failed:', notifErr);
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error accepting suggested order:', error);
      res.status(500).json({ message: 'Error al aceptar el sugerido', detail: error?.message });
    }
  }));

  // Cliente rechaza el sugerido con motivo
  app.post('/api/ecommerce/orders/:id/suggested-reject', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      const orderId = req.params.id;
      const schema = z.object({ reason: z.string().min(3, 'Indicá un motivo breve') });
      const parsed = schema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });

      const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, orderId)).limit(1);
      if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });
      if (order.clientId !== user.id) return res.status(403).json({ message: 'No autorizado' });
      if (!order.isSuggested || order.status !== 'suggested_pending') {
        return res.status(400).json({ message: 'Este pedido no está en estado de sugerido pendiente.' });
      }

      const now = new Date();
      const [updated] = await db.update(ecommerceOrders)
        .set({
          status: 'rejected',
          rejectedAt: now,
          rejectedById: user.id,
          rejectedReason: parsed.data.reason,
          suggestedResponseAt: now,
          updatedAt: now,
        })
        .where(eq(ecommerceOrders.id, orderId))
        .returning();

      try {
        const notifyTo = order.assignedSalespersonId || order.suggestedById || await storage.getAdminUserId();
        if (notifyTo) {
          await storage.createNotification({
            userId: notifyTo,
            type: 'ecommerce_order',
            title: 'Sugerido rechazado por cliente',
            message: `${order.clientName} rechazó el sugerido: ${parsed.data.reason}`,
            relatedOrderId: order.id,
            read: false,
          });
        }
      } catch (notifErr) {
        console.warn('Warning: notify on suggested-reject failed:', notifErr);
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error rejecting suggested order:', error);
      res.status(500).json({ message: 'Error al rechazar el sugerido', detail: error?.message });
    }
  }));

  // Cliente modifica items del sugerido y confirma → pasa a pending normal con items nuevos
  app.patch('/api/ecommerce/orders/:id/suggested-modify', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      const orderId = req.params.id;
      const schema = z.object({
        items: z.array(z.object({
          type: z.enum(['standard', 'custom']).optional(),
          productId: z.string().optional(),
          productName: z.string(),
          sku: z.string().optional(),
          customSku: z.string().optional(),
          quantity: z.number().positive(),
          unitPrice: z.number().nonnegative().optional(),
          totalPrice: z.number().nonnegative().optional(),
          priceTier: z.enum(['lista', 'desc10', 'desc10_5', 'desc10_5_3', 'minimo', 'canalDigital', 'mix', 'oferta']).optional(),
          productUnit: z.string().optional(),
          productColor: z.string().optional(),
          costOfProduction: z.number().nonnegative().optional(),
          profitMargin: z.number().optional(),
          pricingMode: z.enum(['calculated', 'direct']).optional(),
        }).passthrough()).min(1),
        notes: z.string().optional().nullable(),
        paymentMethod: z.enum(['transfer', 'credit']).optional(),
        purchaseOrderPdfUrl: z.string().optional().nullable(),
      });
      const parsed = schema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      const paymentMethod = parsed.data.paymentMethod || 'transfer';
      const purchaseOrderPdfUrl = parsed.data.purchaseOrderPdfUrl || null;

      const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, orderId)).limit(1);
      if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });
      if (order.clientId !== user.id) return res.status(403).json({ message: 'No autorizado' });
      if (!order.isSuggested || order.status !== 'suggested_pending') {
        return res.status(400).json({ message: 'Este pedido no está en estado de sugerido pendiente.' });
      }

      // Recalcular precios usando la lista del cliente destino
      const { clients: clientsTbl } = await import('@shared/schema');
      const { eq: eqOp } = await import('drizzle-orm');
      const [clientRecord] = await db.select().from(clientsTbl).where(eqOp(clientsTbl.userId, user.id)).limit(1);

      // ── Candado de precios ────────────────────────────────────────────────
      // El cliente sólo puede ajustar cantidades, agregar/quitar SKUs y notas.
      // NO puede cambiar la lista de precio (priceTier) ni inyectar unitPrice:
      // cada línea conserva el tier que fijó el equipo comercial en el sugerido
      // original (match por SKU); las líneas nuevas caen a la lista de contrato
      // del cliente. Los productos personalizados (precio libre) sólo los crea
      // el equipo comercial, así que aquí no se aceptan nuevos.
      const originalItems: any[] = Array.isArray(order.items)
        ? (order.items as any[])
        : (typeof order.items === 'string' ? (() => { try { return JSON.parse(order.items as string); } catch { return []; } })() : []);
      const origStdByKey = new Map<string, any>();
      const origCustomByKey = new Map<string, any>();
      for (const oi of originalItems) {
        if (oi?.type === 'custom') {
          origCustomByKey.set(String(oi.customSku || oi.productName || '').trim().toUpperCase(), oi);
        } else {
          const k = String(oi?.sku || oi?.productCode || '').trim().toUpperCase();
          if (k) origStdByKey.set(k, oi);
        }
      }

      const lockedItems: any[] = [];
      for (const it of parsed.data.items) {
        if (it?.type === 'custom') {
          const key = String(it.customSku || it.productName || '').trim().toUpperCase();
          const orig = origCustomByKey.get(key);
          if (!orig) {
            return res.status(403).json({ message: 'No podés agregar productos personalizados ni modificar precios. Esa acción la realiza el equipo comercial.' });
          }
          lockedItems.push({
            ...it,
            unitPrice: Number(orig.unitPrice) || 0,
            totalPrice: undefined,
            costOfProduction: orig.costOfProduction,
            profitMargin: orig.profitMargin,
            pricingMode: orig.pricingMode,
          });
        } else {
          const key = String(it.sku || it.productCode || '').trim().toUpperCase();
          const orig = origStdByKey.get(key);
          const { unitPrice, totalPrice, priceTier, ...rest } = it as any;
          // tier del original (fijado por el equipo); si es SKU nuevo queda sin tier
          // → resolveItemsPricing usa la lista de contrato del cliente + convenio.
          lockedItems.push(orig?.priceTier ? { ...rest, priceTier: orig.priceTier } : rest);
        }
      }

      const resolved = await resolveItemsPricing(lockedItems, clientRecord || null);

      // OC obligatoria para clientes MCT (igual que el checkout del ecommerce).
      const finalOcUrl = purchaseOrderPdfUrl || order.purchaseOrderPdfUrl || null;
      if (await detectMCTClient(clientRecord) && !finalOcUrl) {
        return res.status(400).json({ message: 'Los clientes MCT deben adjuntar la Orden de Compra (PDF) para confirmar el pedido.' });
      }

      const isCreditMethod = paymentMethod === 'credit';
      // OC adjunta + crédito → queda pendiente para la recepcionista
      const hasPurchaseOrder = !!finalOcUrl;
      const shouldAutoApprove = isCreditMethod && !hasPurchaseOrder;
      const now = new Date();
      const [updated] = await db.update(ecommerceOrders)
        .set({
          items: resolved.items,
          subtotal: String(resolved.subtotal),
          tax: String(resolved.tax),
          total: String(resolved.total),
          branchDiscountPercent: String(resolved.branchDiscountPct || 0),
          priceListUsed: resolved.priceListUsed,
          notes: parsed.data.notes ?? order.notes,
          status: shouldAutoApprove ? 'approved' : 'pending',
          paymentCondition: isCreditMethod ? 'Crédito' : 'Transferencia',
          purchaseOrderPdfUrl: finalOcUrl,
          modifiedAt: now,
          modifiedById: user.id,
          suggestedResponseAt: now,
          updatedAt: now,
          ...(shouldAutoApprove ? { approvedAt: now, approvedById: user.id } : {}),
        })
        .where(eq(ecommerceOrders.id, orderId))
        .returning();

      // A crédito: aprobación inmediata y consumo de cupo (con el total recalculado).
      // Si hay OC, el cupo se consume cuando la recepcionista apruebe.
      if (shouldAutoApprove) {
        await consumeClientCreditForUser(order.clientId, Number(resolved.total) || 0);
      }

      try {
        const notifyTo = order.assignedSalespersonId || order.suggestedById || await storage.getAdminUserId();
        if (notifyTo) {
          await storage.createNotification({
            userId: notifyTo,
            type: 'ecommerce_order',
            title: 'Sugerido modificado por cliente',
            message: `${order.clientName} modificó el sugerido. Nuevo total: $${Number(resolved.total).toFixed(0)}`,
            relatedOrderId: order.id,
            read: false,
          });
        }
      } catch (notifErr) {
        console.warn('Warning: notify on suggested-modify failed:', notifErr);
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error modifying suggested order:', error);
      res.status(500).json({ message: 'Error al modificar el sugerido', detail: error?.message });
    }
  }));

  app.get('/api/ecommerce/client/orders', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      if (user.role !== 'client') {
        return res.status(403).json({ message: 'No autorizado. Solo clientes pueden consultar su propio historial.' });
      }

      const orders = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.clientId, user.id)).orderBy(desc(ecommerceOrders.createdAt));
      res.json(orders);
    } catch (error: any) {
      console.error('Error fetching client orders:', error);
      res.status(500).json({ message: 'Error al consultar pedidos', detail: error?.message || 'Unknown error' });
    }
  }));

  // Get ERP standard history data for a specific client linked via clientRut
  app.get('/api/ecommerce/client/erp-orders', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      if (user.role !== 'client') {
        return res.status(403).json({ message: 'No autorizado. Solo clientes pueden consultar su propio historial ERP.' });
      }

      // Resolvemos el scope del cliente desde su SESIÓN (ficha + todos los códigos de la
      // empresa: casa matriz + sucursales por RUT, por parentClientId y por asignación).
      // NO usamos user.clientRut: ese campo no viaja en la sesión (getUser no lo expone),
      // así que depender de él dejaba el historial SIEMPRE vacío para todos los clientes.
      const scope = await resolveClientScope(user.id);
      if (!scope || (scope.koens.length === 0 && !scope.cleanRut)) {
        return res.json({ nvv: [], gdv: [], transactions: [] });
      }

      const { nvvPendingSales, factGdv, salesTransactions } = await import('@shared/schema');
      const { sql, and, gte, desc } = await import('drizzle-orm');

      // En las tablas espejo del ERP `endo` = código de cliente (koen), NO el RUT
      // (mismo SELECT* que ventas.fact_ventas). Igualamos por koen — camino validado en
      // account-status — y, por robustez, también por RUT normalizado.
      const koens = scope.koens;
      const cleanRut = scope.cleanRut;
      const ownsBy = (col: any) => {
        const parts: any[] = [];
        if (koens.length > 0) {
          parts.push(sql`TRIM(${col}) IN (${sql.join(koens.map((k) => sql`${k}`), sql`, `)})`);
        }
        if (cleanRut) {
          parts.push(sql`REPLACE(REPLACE(REPLACE(UPPER(${col}), '.', ''), '-', ''), ' ', '') = ${cleanRut}`);
        }
        return parts.length > 1 ? sql`(${sql.join(parts, sql` OR `)})` : parts[0];
      };

      // Ventana de historial (meses). Por defecto 12 (perf), ampliable vía ?months=
      // para vistas que necesitan más historial (p.ej. el listado de pedidos). Acotado a 60.
      const months = Math.min(Math.max(Number(req.query.months) || 12, 1), 60);
      const now = new Date();
      const startDate = new Date(now.getFullYear(), now.getMonth() - (months - 1), 1).toISOString().split("T")[0];

      // Fetch NVV (Pending orders, generally small list)
      const nvvData = await db.select().from(nvvPendingSales)
        .where(ownsBy(nvvPendingSales.ENDO));

      // Fetch GDV
      const gdvData = await db.select().from(factGdv)
        .where(
          and(
            ownsBy(factGdv.endo),
            gte(factGdv.feemdo, startDate as any)
          )
        );

      const txData = await db.select()
        .from(salesTransactions)
        .where(
          and(
            ownsBy(salesTransactions.endo),
            gte(salesTransactions.feemdo, startDate as any)
          )
        )
        .orderBy(desc(salesTransactions.feemdo));

      res.json({
        nvv: nvvData,
        gdv: gdvData,
        transactions: txData
      });
    } catch (error: any) {
      console.error('Error fetching client ERP history:', error);
      res.status(500).json({ message: 'Error al consultar historial ERP', detail: error?.message || 'Unknown error' });
    }
  }));


  // Resuelve el "scope" del cliente logueado para acotar cartera/facturas/historial a lo
  // que él puede ver, SIN confiar en parámetros del request. Devuelve su ficha + todos los
  // códigos de cliente (koen) de la empresa, reunidos por 3 vías: (1) mismo RUT, (2) jerarquía
  // de sucursales (parentClientId, caso MCT aunque cada plaza tenga RUT distinto) y (3) tabla
  // de unión user_branch_assignments. La cartera vive en ventas.fact_ventas donde endo = koen
  // (NO el RUT), por eso necesitamos los koen y no alcanza con user.clientRut.
  const resolveClientScope = async (userId: string) => {
    const client = await storage.getClientByUserId(userId);
    if (!client) return null;
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    const normalizeRut = (v?: string | null) => (v || '').replace(/[.\-\s]/g, '').trim().toUpperCase();
    const cleanRut = normalizeRut(client.rten);
    const koens = new Set<string>();
    const clientIds = new Set<string>();
    if (client.koen) koens.add(String(client.koen).trim());
    if (client.id) clientIds.add(String(client.id));

    const absorb = (r: any) => {
      const rows = Array.isArray(r) ? r : (r as any).rows || [];
      for (const row of rows) {
        if (row.koen) koens.add(String(row.koen).trim());
        if (row.id) clientIds.add(String(row.id));
      }
    };

    // 1) Sucursales que comparten el mismo RUT (empresa con varias fichas bajo un RUT).
    if (cleanRut) {
      try {
        absorb(await db.execute(sql`
          SELECT id, koen FROM clients
          WHERE REPLACE(REPLACE(REPLACE(UPPER(rten), '.', ''), '-', ''), ' ', '') = ${cleanRut}
        `));
      } catch (e) {
        console.warn('[client-scope] sibling-by-RUT lookup failed:', e);
      }
    }

    // 2) Jerarquía de sucursales por parentClientId (casa matriz + sus hijas), aunque
    //    cada plaza tenga RUT distinto. Es el modelo usado por MCT y por la tienda
    //    (/api/store/my-branches). El "root" es la casa matriz.
    try {
      const rootId = (client as any).parentClientId || client.id;
      absorb(await db.execute(sql`
        SELECT id, koen FROM clients
        WHERE id = ${rootId} OR parent_client_id = ${rootId}
      `));
    } catch (e) {
      console.warn('[client-scope] parent-hierarchy lookup failed:', e);
    }

    // 3) Sucursales asignadas explícitamente al usuario (tabla de unión multi-sucursal).
    try {
      absorb(await db.execute(sql`
        SELECT c.id, c.koen
        FROM user_branch_assignments uba
        JOIN clients c ON c.id = uba.client_id
        WHERE uba.user_id = ${userId}
      `));
    } catch (e) {
      console.warn('[client-scope] branch-assignments lookup failed:', e);
    }

    return {
      client,
      koens: Array.from(koens).filter(Boolean),
      clientIds: Array.from(clientIds).filter(Boolean),
      cleanRut,
      clientName: (client.nokoen || '') as string,
      rut: (client.rten || '') as string,
    };
  };

  // Scope de datos para el rol encargado_area: códigos de cliente (koen = endo) cuyas
  // ventas debe ver. Se usa para acotar TODO el dashboard (KPIs, gráficos, metas, top-N).
  //   - Devuelve [] (sin restricción => ve todo) SOLO si el usuario NO es
  //     encargado_area, o si NO tiene NINGUNA sucursal asignada.
  //   - Devuelve la lista de koens resueltos si sus sucursales resuelven a ventas.
  //   - Devuelve [ENCARGADO_NO_SCOPE] si tiene asignaciones pero NINGUNA resuelve a
  //     un koen real => el dashboard queda en CERO (ve NADA), nunca "ve todo".
  // Resultado cacheado 60s por usuario para no repetir el query en cada tarjeta.
  //
  // Modelo de resolución (verificado contra datos reales de MCT/ELECTROCOM):
  //   (a) Sucursal = ficha ERP propia (tiene koen) → se usa su koen.
  //   (b) Sucursal = "plaza" creada a mano (caso MCT): koen NULL, pero sus ventas viven
  //       en ventas.fact_ventas bajo un VENDEDOR (nokofu) cuyo nombre coincide con el
  //       branch_label ("MCT CASTRO", "MCT LOS ANGELES", ...). Mapeamos branch_label→koen
  //       a través de ese nokofu (normalizando acentos con translate, sin extensión
  //       unaccent). NO se usa el koen de la matriz (parent_client_id): esa ficha no tiene
  //       ventas y, peor, agruparía todas las plazas del mismo RUT → mostraría de más.
  // Caveat de datos: si el branch_label no coincide con el nokofu (typo, p.ej.
  //   "VILLARRICA" vs "VILLARICA"), esa plaza no resuelve y cae al sentinel (ve nada),
  //   lo que evita fugas pero exige alinear el nombre con el vendedor del ERP.
  //
  // Sentinel: koens=[] significa "sin restricción" para getClientScopeConditions, así
  // que un encargado con sucursales asignadas que no resuelven NO debe devolver [] —
  // eso filtraría como "ve TODA la empresa" (fuga de datos). Devolvemos un valor que
  // jamás matchea un endo real, así "endo IN (...)" no trae filas (ve NADA).
  const ENCARGADO_NO_SCOPE = '__no_scope__';
  const encargadoScopeCache = new Map<string, { koens: string[]; ts: number }>();
  const getEncargadoScopeKoens = async (user: any): Promise<string[]> => {
    if (!user || user.role !== 'encargado_area' || !user.id) return [];
    const cached = encargadoScopeCache.get(user.id);
    if (cached && Date.now() - cached.ts < 60_000) return cached.koens;
    let koens: string[] = [];
    try {
      const { db } = await import('./db');
      const { sql } = await import('drizzle-orm');
      // ¿Tiene asignaciones? (distingue "sin scope = ve todo" de "scope vacío = ve nada").
      const cntR = await db.execute(sql`
        SELECT COUNT(*)::int AS n FROM user_branch_assignments WHERE user_id = ${user.id}
      `);
      const cntRows = Array.isArray(cntR) ? cntR : (cntR as any).rows || [];
      const assignmentCount = Number(cntRows[0]?.n) || 0;

      // (a) koen propio de fichas ERP asignadas  UNION  (b) koens de las plazas (MCT)
      // cuyo vendedor (nokofu) coincide con el branch_label (acentos normalizados).
      const r = await db.execute(sql`
        WITH assigned AS (
          SELECT c.koen, c.branch_label
          FROM user_branch_assignments uba
          JOIN clients c ON c.id = uba.client_id
          WHERE uba.user_id = ${user.id}
        ),
        labels AS (
          SELECT DISTINCT translate(upper(btrim(branch_label)), 'ÁÉÍÓÚÜÑ', 'AEIOUUN') AS lbl
          FROM assigned
          WHERE koen IS NULL AND branch_label IS NOT NULL AND btrim(branch_label) <> ''
        )
        SELECT koen FROM assigned WHERE koen IS NOT NULL
        UNION
        SELECT DISTINCT fv.endo AS koen
        FROM ventas.fact_ventas fv
        JOIN labels ON translate(upper(btrim(fv.nokofu)), 'ÁÉÍÓÚÜÑ', 'AEIOUUN') = labels.lbl
        WHERE fv.endo IS NOT NULL
      `);
      const rows = Array.isArray(r) ? r : (r as any).rows || [];
      koens = Array.from(new Set(
        rows.map((row: any) => (row.koen != null ? String(row.koen).trim() : '')).filter(Boolean)
      ));
      // Tiene ≥1 asignación pero ninguna resolvió a un koen real => ve NADA (no "ve todo").
      if (assignmentCount > 0 && koens.length === 0) koens = [ENCARGADO_NO_SCOPE];
    } catch (e) {
      console.warn('[encargado-scope] lookup failed:', e);
      koens = [];
    }
    encargadoScopeCache.set(user.id, { koens, ts: Date.now() });
    return koens;
  };

  // ── Asignación de sucursales a usuarios (scope de datos del encargado de área) ──
  // Nota: la lista de clientes/sucursales para el selector (/api/clients/branches-tree)
  // se registra ANTES de /api/clients/:koen para que no la capture esa ruta param.

  // Sucursales asignadas a un usuario (devuelve los clientId asignados).
  app.get('/api/users/salespeople/:id/branch-assignments', requireRoles(['admin', 'supervisor']), asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    const r = await db.execute(sql`
      SELECT uba.client_id AS "clientId", c.koen, c.nokoen, c.rten, c.branch_label AS "branchLabel"
      FROM user_branch_assignments uba
      LEFT JOIN clients c ON c.id = uba.client_id
      WHERE uba.user_id = ${id}
    `);
    const rows = Array.isArray(r) ? r : (r as any).rows || [];
    res.json(rows);
  }));

  // Reemplaza el set de sucursales asignadas a un usuario. Body: { clientIds: string[] }.
  app.put('/api/users/salespeople/:id/branch-assignments', requireRoles(['admin', 'supervisor']), asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const clientIds: unknown = req.body?.clientIds;
    if (!Array.isArray(clientIds) || clientIds.some((c) => typeof c !== 'string')) {
      return res.status(400).json({ message: 'clientIds debe ser un arreglo de strings.' });
    }
    const ids = Array.from(new Set((clientIds as string[]).map((c) => c.trim()).filter(Boolean)));
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    // Reemplazo total: borrar lo previo e insertar el nuevo set.
    await db.execute(sql`DELETE FROM user_branch_assignments WHERE user_id = ${id}`);
    if (ids.length > 0) {
      const values = sql.join(ids.map((cid) => sql`(${id}, ${cid})`), sql`, `);
      await db.execute(sql`
        INSERT INTO user_branch_assignments (user_id, client_id)
        VALUES ${values}
        ON CONFLICT (user_id, client_id) DO NOTHING
      `);
    }
    // Invalida el cache de scope para que el cambio se vea de inmediato.
    encargadoScopeCache.delete(id);
    res.json({ ok: true, count: ids.length });
  }));

  // Scope del usuario logueado: a qué sucursales está acotado su dashboard. Sirve para
  // mostrarle al encargado de área (en su propio Dashboard) qué comercios está viendo,
  // así la limitación es explícita y "se traduce" visualmente. Otros roles => no scopeado.
  app.get('/api/me/scope', requireAuth, asyncHandler(async (req: any, res: any) => {
    const user = req.user;
    if (!user || user.role !== 'encargado_area') {
      return res.json({ role: user?.role || null, scoped: false, branches: [] });
    }
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    const r = await db.execute(sql`
      SELECT c.id, c.koen, c.nokoen, c.rten, c.branch_label AS "branchLabel"
      FROM user_branch_assignments uba
      JOIN clients c ON c.id = uba.client_id
      WHERE uba.user_id = ${user.id}
      ORDER BY c.nokoen
    `);
    const rows = Array.isArray(r) ? r : (r as any).rows || [];
    res.json({ role: 'encargado_area', scoped: rows.length > 0, branches: rows });
  }));

  // Conteo de sucursales asignadas por usuario (para mostrar en la tabla de Gestión
  // de Usuarios cuántas sucursales tiene acotado cada encargado de un vistazo).
  app.get('/api/users/branch-assignment-counts', requireRoles(['admin', 'supervisor']), asyncHandler(async (req: any, res: any) => {
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    const r = await db.execute(sql`
      SELECT user_id AS "userId", COUNT(*)::int AS count
      FROM user_branch_assignments
      GROUP BY user_id
    `);
    const rows = Array.isArray(r) ? r : (r as any).rows || [];
    const counts: Record<string, number> = {};
    for (const row of rows) counts[String(row.userId)] = Number(row.count) || 0;
    res.json(counts);
  }));

  // Estado de cuenta del cliente logueado: línea de crédito + cartera REAL (cuentas por
  // cobrar) calculada desde ventas.fact_ventas — el mismo cálculo validado de
  // /api/clients/account-status, pero acotado a la empresa del cliente por su sesión
  // (no por parámetros). Saldo doc = vabrdo - vaabdo; vencido = fe01vedo < hoy; solo
  // pendientes (espgdo='P'); dedup por idmaeedo. NO usa clients.crsd (vacío/no fidedigno).
  app.get('/api/ecommerce/client/account-status', requireAuth, asyncHandler(async (req: any, res: any) => {
    const user = req.user;
    if (user.role !== 'client') {
      return res.status(403).json({ message: 'No autorizado.' });
    }
    const emptyPayload = {
      hasFicha: false, clientName: null, rut: null, paymentCondition: null,
      creditLimit: null, creditUsed: null, creditOverdue: null, creditUpcoming: null,
      creditAvailable: null, nextDueDate: null, overdueSince: null,
      hasCredit: false, hasDebt: false, hasOverdue: false,
    };
    const scope = await resolveClientScope(user.id);
    if (!scope) return res.json(emptyPayload);

    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    const { client, koens } = scope;

    let usado = 0, vencido = 0, porVencer = 0;
    let proxVenc: string | null = null, vencidoDesde: string | null = null;
    if (koens.length > 0) {
      try {
        const r = await db.execute(sql`
          WITH docs AS (
            SELECT idmaeedo,
                   MAX(COALESCE(vabrdo, 0)) - MAX(COALESCE(vaabdo, 0)) AS saldo,
                   MAX(fe01vedo) AS venc
            FROM ventas.fact_ventas
            WHERE endo IN (${sql.join(koens.map((k) => sql`${k}`), sql`, `)})
              AND tido IN ('FCV', 'FDV')
              AND espgdo = 'P'
            GROUP BY idmaeedo
          )
          SELECT
            COALESCE(SUM(saldo) FILTER (WHERE saldo > 0), 0) AS usado,
            COALESCE(SUM(saldo) FILTER (WHERE saldo > 0 AND venc < CURRENT_DATE), 0) AS vencido,
            COALESCE(SUM(saldo) FILTER (WHERE saldo > 0 AND (venc >= CURRENT_DATE OR venc IS NULL)), 0) AS por_vencer,
            MIN(venc) FILTER (WHERE saldo > 0 AND venc >= CURRENT_DATE) AS proximo_venc,
            MIN(venc) FILTER (WHERE saldo > 0 AND venc < CURRENT_DATE) AS vencido_desde
          FROM docs
        `);
        const row = (Array.isArray(r) ? r : (r as any).rows || [])[0];
        if (row) {
          const fmt = (v: any) => v == null ? null : (v instanceof Date ? v.toISOString().slice(0, 10) : String(v).slice(0, 10));
          usado = Number(row.usado) || 0;
          vencido = Number(row.vencido) || 0;
          porVencer = Number(row.por_vencer) || 0;
          proxVenc = fmt(row.proximo_venc);
          vencidoDesde = fmt(row.vencido_desde);
        }
      } catch (e) {
        console.error('[client account-status] cartera lookup failed:', e);
      }
    }

    const creditLimit = client.crlt != null ? Number(client.crlt) : null;
    const cpen = (client.cpen || '') as string;
    const hasCredit = /CR[EÉ]DITO/i.test(cpen) || (creditLimit != null && creditLimit > 0);

    res.json({
      hasFicha: true,
      clientName: scope.clientName || null,
      rut: scope.rut || null,
      paymentCondition: cpen || null,
      creditLimit,
      creditUsed: usado,
      creditOverdue: vencido,
      creditUpcoming: porVencer,
      creditAvailable: creditLimit != null ? creditLimit - usado : null,
      nextDueDate: proxVenc,
      overdueSince: vencidoDesde,
      hasCredit,
      hasDebt: usado > 0,
      hasOverdue: vencido > 0,
    });
  }));

  // Detalle de la cartera (cuentas por cobrar) del cliente logueado: una fila por documento
  // pendiente (idmaeedo), con saldo, vencimiento, total e idmaeedo para descargar la factura.
  app.get('/api/ecommerce/client/cartera', requireAuth, asyncHandler(async (req: any, res: any) => {
    const user = req.user;
    if (user.role !== 'client') {
      return res.status(403).json({ message: 'No autorizado.' });
    }
    const scope = await resolveClientScope(user.id);
    if (!scope || scope.koens.length === 0) return res.json({ docs: [] });

    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    try {
      const r = await db.execute(sql`
        SELECT idmaeedo,
               MAX(nudo) AS nudo,
               MAX(tido) AS tido,
               MAX(feemdo) AS emision,
               MAX(fe01vedo) AS vencimiento,
               MAX(COALESCE(vabrdo, 0)) - MAX(COALESCE(vaabdo, 0)) AS saldo,
               MAX(COALESCE(vabrdo, 0)) AS total,
               (MAX(fe01vedo) < CURRENT_DATE) AS vencida
        FROM ventas.fact_ventas
        WHERE endo IN (${sql.join(scope.koens.map((k) => sql`${k}`), sql`, `)})
          AND tido IN ('FCV', 'FDV')
          AND espgdo = 'P'
        GROUP BY idmaeedo
        HAVING (MAX(COALESCE(vabrdo, 0)) - MAX(COALESCE(vaabdo, 0))) > 0
        ORDER BY MAX(fe01vedo) ASC NULLS LAST
      `);
      const rows = Array.isArray(r) ? r : (r as any).rows || [];
      const fmt = (v: any) => v == null ? null : (v instanceof Date ? v.toISOString().slice(0, 10) : String(v).slice(0, 10));
      res.json({
        docs: rows.map((d: any) => ({
          idmaeedo: d.idmaeedo != null ? String(d.idmaeedo).replace(/\.0+$/, '') : null,
          nudo: d.nudo != null ? String(d.nudo) : null,
          tido: d.tido ? String(d.tido).trim() : null,
          emision: fmt(d.emision),
          vencimiento: fmt(d.vencimiento),
          saldo: Number(d.saldo) || 0,
          total: Number(d.total) || 0,
          vencida: d.vencida === true || d.vencida === 't',
        })),
      });
    } catch (e) {
      console.error('[client cartera] error:', e);
      res.json({ docs: [] });
    }
  }));

  // Factura oficial (DTE timbrado SII) de una FCV del cliente logueado. Reusa el MISMO
  // pipeline que la ficha admin (/api/erp/facturas/:idmaeedo/pdf) pero verifica que el
  // idmaeedo pertenezca al cliente ANTES de servir el PDF (evita enumeración de facturas
  // ajenas). Ownership: el documento debe estar en ventas.fact_ventas con endo en sus koen
  // o, como respaldo, en sales_transactions con endo = su RUT.
  app.get('/api/ecommerce/client/facturas/:idmaeedo/pdf', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      if (user.role !== 'client') {
        return res.status(403).json({ message: 'No autorizado.' });
      }
      const idmaeedo = parseInt(String(req.params.idmaeedo), 10);
      if (!Number.isFinite(idmaeedo) || idmaeedo <= 0) {
        return res.status(400).json({ message: 'idmaeedo inválido' });
      }
      const scope = await resolveClientScope(user.id);
      if (!scope) return res.status(403).json({ message: 'No autorizado para descargar esta factura' });

      const { db } = await import('./db');
      const { sql } = await import('drizzle-orm');

      let owned = false;
      if (scope.koens.length > 0) {
        try {
          const r = await db.execute(sql`
            SELECT 1 FROM ventas.fact_ventas
            WHERE idmaeedo = ${idmaeedo}
              AND endo IN (${sql.join(scope.koens.map((k) => sql`${k}`), sql`, `)})
              AND tido IN ('FCV', 'FDV')
            LIMIT 1
          `);
          owned = (Array.isArray(r) ? r : (r as any).rows || []).length > 0;
        } catch (e) {
          console.warn('[client factura pdf] fact_ventas ownership check failed:', e);
        }
      }
      if (!owned && scope.cleanRut) {
        try {
          const r = await db.execute(sql`
            SELECT 1 FROM sales_transactions
            WHERE idmaeedo = ${idmaeedo}
              AND REPLACE(REPLACE(REPLACE(UPPER(endo), '.', ''), '-', ''), ' ', '') = ${scope.cleanRut}
            LIMIT 1
          `);
          owned = (Array.isArray(r) ? r : (r as any).rows || []).length > 0;
        } catch (e) {
          console.warn('[client factura pdf] sales_transactions ownership check failed:', e);
        }
      }
      if (!owned) {
        return res.status(403).json({ message: 'No autorizado para descargar esta factura' });
      }

      const { getDteByIdmaeedo } = await import('./utils/erp-dte');
      const { parseDte } = await import('./utils/dte-parse');
      const { renderFacturaHtml } = await import('./services/factura-dte-template');
      const { renderHtmlToPdf } = await import('./utils/quote-pdf-renderer');

      const dteRow = await getDteByIdmaeedo(idmaeedo);
      if (!dteRow || !dteRow.xml) {
        return res.status(404).json({ message: 'No se encontró el DTE de esta factura en el ERP' });
      }
      const parsed = parseDte(dteRow.xml);
      const html = renderFacturaHtml(parsed, { timbreBase64: dteRow.pdf417, logoUrl: null });
      const pdf = await renderHtmlToPdf(html, { waitUntil: 'load' });
      const folio = parsed.folio || dteRow.nudo || String(idmaeedo);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Factura_${folio}.pdf"`);
      res.send(pdf);
    } catch (error: any) {
      console.error('[GET /api/ecommerce/client/facturas/:idmaeedo/pdf] error:', error);
      res.status(500).json({ message: 'Error al generar el PDF de la factura', detail: error?.message || 'Unknown error' });
    }
  });

  // Get ecommerce orders for salesperson/admin (order taker view)
  app.get('/api/ecommerce/orders', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;

      // If ?id= is provided, return single order
      if (req.query.id) {
        const result = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, req.query.id));
        const order = result[0];
        if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });
        // Allow owner or admin/supervisor
        if (order.clientId !== user.id && !['admin', 'supervisor', 'encargado_area', 'salesperson', 'reception'].includes(user.role)) {
          return res.status(403).json({ message: 'No autorizado' });
        }
        return res.json(order);
      }
      // Build filters based on user role
      const filters: any = {};

      if (user.role === 'salesperson') {
        // Salesperson sees only their assigned orders
        filters.salespersonId = user.id;
      } else if (user.role === 'admin' || (user.role === 'supervisor' || user.role === 'encargado_area') || user.role === 'reception') {
        // Admin/supervisor see all orders.
        // Optionally scope to a single ecommerce client user (?userId=) — used by the
        // unified client ficha to show that client's orders/KPIs.
        if (req.query.userId) {
          filters.clientId = req.query.userId as string;
        }
        // Optionally filter by status if provided
        if (req.query.status && req.query.status !== 'all') {
          filters.status = req.query.status;
        }
      } else {
        // Other roles can't access this endpoint
        return res.status(403).json({ message: 'No autorizado' });
      }

      const orders = await storage.getEcommerceOrders(filters);
      res.json(orders);
    } catch (error) {
      console.error('Error fetching ecommerce orders:', error);
      res.status(500).json({ message: 'Error al obtener pedidos' });
    }
  }));

  // ==========================================================================
  // GET /api/logistica/envios → lista los pedidos del Market como "envíos",
  // agrupados por estado de entrega: pendiente | transito | entregado.
  // Si el TMS está configurado, enriquece los pedidos despachados (status 'sent')
  // con el estado real de entrega (transportista/patente/ruta). Si no, degrada al
  // estado interno del pedido sin romperse.
  // ==========================================================================
  app.get('/api/logistica/envios', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;

      const filters: any = {};
      if (user.role === 'salesperson') {
        filters.salespersonId = user.id;
      } else if (!['admin', 'supervisor', 'encargado_area', 'reception'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }

      // Ventana temporal (días). 0 = sin límite. Por defecto 90 días para acotar
      // el set y la cantidad de consultas al TMS.
      const days = Number.parseInt(String(req.query.days ?? '90'), 10);
      const since = Number.isFinite(days) && days > 0
        ? new Date(Date.now() - days * 24 * 60 * 60 * 1000)
        : null;

      const allOrders = await storage.getEcommerceOrders(filters);

      // El flujo logístico arranca en el INGRESO AL ERP: solo entran a Logística los
      // pedidos ya ingresados (ingresado → en preparación → en curso → entregado).
      // Los previos (pending/approved/modified) todavía no son responsabilidad de
      // logística. Excluimos además rechazados/archivados y aplicamos la ventana.
      const logisticStatuses = new Set(['ingresado', 'preparacion', 'sent', 'transito', 'entregado']);
      const relevant = allOrders.filter((o: any) => {
        const st = String(o.status || '').toLowerCase();
        if (st === 'rejected' || st === 'archived') return false;
        if (!o.ingresadoAt && !logisticStatuses.has(st)) return false; // aún no ingresado al ERP
        if (since && o.createdAt && new Date(o.createdAt) < since) return false;
        return true;
      });

      // Sincronización con el ERP: completamos el puente erpIdmaeedo de los pedidos
      // que aún no lo tienen, emparejándolos con su NVV (RUT + fecha + monto). Una vez
      // persistido, no se vuelve a calcular para ese pedido. Es lo que habilita al TMS
      // a consultar el estado real de entrega por idmaeedo.
      const sinIdmaeedo = relevant.filter((o: any) => o.erpIdmaeedo == null);
      if (sinIdmaeedo.length > 0) {
        try {
          const matches = await matchEcommerceOrdersToErp(
            sinIdmaeedo.map((o: any) => ({
              id: o.id,
              clientId: o.clientId,
              subtotal: o.subtotal,
              total: o.total,
              createdAt: o.createdAt,
              ingresadoAt: o.ingresadoAt,
            })),
          );
          if (matches.size > 0) {
            const { ecommerceOrders } = await import('@shared/schema');
            const { eq } = await import('drizzle-orm');
            await Promise.all(
              Array.from(matches.entries()).map(async ([orderId, idmaeedo]) => {
                try {
                  await db.update(ecommerceOrders)
                    .set({ erpIdmaeedo: idmaeedo })
                    .where(eq(ecommerceOrders.id, orderId));
                } catch (e) {
                  console.error('[logistica] no se pudo persistir idmaeedo de', orderId, e);
                }
              }),
            );
            for (const o of relevant) {
              const idmaeedo = matches.get(o.id);
              if (idmaeedo) o.erpIdmaeedo = idmaeedo;
            }
          }
        } catch (err) {
          console.error('[logistica] sync ERP (erpIdmaeedo) falló:', err);
        }
      }

      const tmsEnabled = isTmsConfigured();

      // Enriquecemos con el TMS los pedidos despachados o posteriores con puente al
      // ERP, con concurrencia acotada (el cliente TMS ya cachea por idmaeedo).
      const enrichTargets = tmsEnabled
        ? relevant.filter((o: any) =>
            ['sent', 'transito', 'entregado'].includes(String(o.status || '').toLowerCase()) &&
            o.erpIdmaeedo != null,
          )
        : [];

      const tmsById = new Map<string, any>();
      const CONCURRENCY = 6;
      for (let i = 0; i < enrichTargets.length; i += CONCURRENCY) {
        const slice = enrichTargets.slice(i, i + CONCURRENCY);
        const results = await Promise.all(
          slice.map(async (o: any) => {
            const estado = await fetchTmsShipping(o.erpIdmaeedo as any);
            return [String(o.id), estado] as const;
          }),
        );
        for (const [id, estado] of results) tmsById.set(id, estado);
      }

      const internalLabels: Record<string, string> = {
        ingresado: 'Ingresado al ERP',
        preparacion: 'En preparación',
        sent: 'En curso',
        transito: 'En curso',
        entregado: 'Entregado',
      };

      const envios = relevant.map((o: any) => {
        const st = String(o.status || '').toLowerCase();
        const tms = tmsById.get(String(o.id)) || null;
        const envio = tms?.envio || null;

        // Categoría base según el estado INTERNO dentro del flujo logístico:
        //   entregado        → entregado
        //   sent | transito  → curso (en camino al cliente)
        //   preparacion      → preparacion (armándose en bodega)
        //   resto (ingresado)→ ingresado (recién ingresado al ERP)
        const internal: 'ingresado' | 'preparacion' | 'curso' | 'entregado' =
          st === 'entregado' ? 'entregado'
          : (st === 'sent' || st === 'transito') ? 'curso'
          : st === 'preparacion' ? 'preparacion'
          : 'ingresado';

        let estado: 'ingresado' | 'preparacion' | 'curso' | 'entregado' = internal;
        let estadoLabel = internalLabels[st]
          || (internal === 'entregado' ? 'Entregado'
            : internal === 'curso' ? 'En curso'
            : internal === 'preparacion' ? 'En preparación'
            : 'Ingresado al ERP');
        let subEstado: string | null = null;

        // El TMS, cuando responde con un estado concluyente, tiene prioridad sobre el
        // estado interno. Si no es concluyente, NO degradamos una entrega marcada a mano.
        if (tms) {
          const entrega = envio?.estadoEntrega || null;
          if (entrega === 'Entregado') {
            estado = 'entregado';
            estadoLabel = 'Entregado';
          } else if (entrega === 'No Entregado') {
            estado = 'curso';
            estadoLabel = 'Entrega fallida';
            subEstado = 'fallido';
          } else if (tms.retiroEnBodega) {
            estado = 'curso';
            estadoLabel = 'Listo para retiro en bodega';
            subEstado = 'retiro';
          } else if (internal === 'curso') {
            // En ruta sin confirmación de entrega: mostramos el estado de ruta del TMS.
            estadoLabel = envio?.rutaEstado || entrega || estadoLabel;
          }
        }

        const items = Array.isArray(o.items) ? o.items : [];

        return {
          id: o.id,
          trackingCode: o.trackingCode || null,
          clientName: o.clientName || null,
          clientEmail: o.clientEmail || null,
          clientPhone: o.clientPhone || null,
          salespersonName: o.assignedSalespersonName || null,
          status: o.status,
          estado,
          estadoLabel,
          subEstado,
          fecha: o.createdAt,
          ingresadoAt: o.ingresadoAt || null,
          total: o.total,
          itemsCount: items.length,
          erpIdmaeedo: o.erpIdmaeedo != null ? String(o.erpIdmaeedo) : null,
          envio: envio
            ? {
                estadoEntrega: envio.estadoEntrega ?? null,
                horaEntrega: envio.horaEntrega ?? null,
                operario: envio.operario ?? null,
                patente: envio.patente ?? null,
                rutaEstado: envio.rutaEstado ?? null,
                motivoRechazo: envio.motivoRechazo ?? null,
              }
            : null,
        };
      });

      const resumen = {
        ingresados: envios.filter((e) => e.estado === 'ingresado').length,
        preparacion: envios.filter((e) => e.estado === 'preparacion').length,
        curso: envios.filter((e) => e.estado === 'curso').length,
        entregados: envios.filter((e) => e.estado === 'entregado').length,
        total: envios.length,
      };

      res.json({ tmsEnabled, days: since ? days : 0, resumen, envios });
    } catch (error) {
      console.error('Error fetching logistica envios:', error);
      res.status(500).json({ message: 'Error al obtener los envíos' });
    }
  }));

  // ==========================================================================
  // POST /api/logistica/sync-erp → fuerza el emparejamiento de pedidos ingresados
  // sin erpIdmaeedo con su NVV del ERP (RUT + fecha + monto) y persiste el puente.
  // Devuelve cuántos quedaron vinculados. Útil para "Sincronizar con ERP" a mano.
  // ==========================================================================
  app.post('/api/logistica/sync-erp', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      const filters: any = {};
      if (user.role === 'salesperson') {
        filters.salespersonId = user.id;
      } else if (!['admin', 'supervisor', 'encargado_area', 'reception'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }

      const allOrders = await storage.getEcommerceOrders(filters);
      const logisticStatuses = new Set(['ingresado', 'preparacion', 'sent', 'transito', 'entregado']);
      const candidatos = allOrders.filter((o: any) => {
        if (o.erpIdmaeedo != null) return false;
        const st = String(o.status || '').toLowerCase();
        if (st === 'rejected' || st === 'archived') return false;
        return !!o.ingresadoAt || logisticStatuses.has(st);
      });

      let vinculados = 0;
      if (candidatos.length > 0) {
        const matches = await matchEcommerceOrdersToErp(
          candidatos.map((o: any) => ({
            id: o.id,
            clientId: o.clientId,
            subtotal: o.subtotal,
            total: o.total,
            createdAt: o.createdAt,
            ingresadoAt: o.ingresadoAt,
          })),
        );
        if (matches.size > 0) {
          const { ecommerceOrders } = await import('@shared/schema');
          const { eq } = await import('drizzle-orm');
          await Promise.all(
            Array.from(matches.entries()).map(async ([orderId, idmaeedo]) => {
              try {
                await db.update(ecommerceOrders)
                  .set({ erpIdmaeedo: idmaeedo })
                  .where(eq(ecommerceOrders.id, orderId));
                vinculados++;
              } catch (e) {
                console.error('[logistica/sync-erp] no se pudo persistir idmaeedo de', orderId, e);
              }
            }),
          );
        }
      }

      res.json({ evaluados: candidatos.length, vinculados, tmsEnabled: isTmsConfigured() });
    } catch (error) {
      console.error('Error en sync-erp:', error);
      res.status(500).json({ message: 'Error al sincronizar con el ERP' });
    }
  }));

  // ==========================================================================
  // Seguimiento de pedidos del CLIENTE (portal cliente). El cliente ve SUS
  // órdenes del TMS, resueltas por su propio RUT (clients.rten). El RUT NUNCA
  // llega desde el request: se deriva del usuario autenticado. Solo lectura.
  // ==========================================================================
  const normalizeRutCmp = (rut?: string | null): string =>
    (rut || '').replace(/[^0-9kK]/g, '').toUpperCase();

  // Dígito verificador (módulo 11) a partir del cuerpo del RUT (solo dígitos).
  const computeRutDv = (body: string): string => {
    let sum = 0, mul = 2;
    for (let i = body.length - 1; i >= 0; i--) {
      sum += parseInt(body[i], 10) * mul;
      mul = mul === 7 ? 2 : mul + 1;
    }
    const r = 11 - (sum % 11);
    return r === 11 ? '0' : r === 10 ? 'K' : String(r);
  };

  // Candidatos de RUT para consultar al TMS (el maestro guarda formatos dispares).
  // Algunas fichas guardan `rten` SIN dígito verificador (p.ej. "96596450" cuando el
  // RUT real es "96596450-9"). Para resolverlo SIN adivinar a ciegas usamos el DV como
  // desambiguador: solo emitimos formas de RUT cuyo dígito verificador sea VÁLIDO.
  //   1) Si el último carácter de `rten` ya es el DV correcto → es el RUT tal cual.
  //   2) Si no, interpretamos `rten` como el cuerpo y calculamos su DV (módulo 11).
  // Los clientes con `rten` correcto matchean exactamente igual que antes (interp. 1
  // primero), y los truncados se completan con su único DV válido (sin falsos positivos).
  const rutQueryCandidates = (rten?: string | null): string[] => {
    const compact = normalizeRutCmp(rten);
    if (compact.length < 2) return [];
    const cands: string[] = [];
    const body1 = compact.slice(0, -1);
    const dv1 = compact.slice(-1);
    if (/^[0-9]+$/.test(body1) && computeRutDv(body1) === dv1) {
      // Interpretación 1: `rten` ya incluye un DV válido → es el RUT tal cual.
      cands.push(`${body1}-${dv1}`, compact);
    } else if (/^[0-9]+$/.test(compact)) {
      // Interpretación 2: `rten` es el cuerpo sin DV → calculamos el DV (módulo 11).
      const dv2 = computeRutDv(compact);
      cands.push(`${compact}-${dv2}`, `${compact}${dv2}`);
    }
    // Resguardo: ante un formato inesperado, probamos las formas crudas (como antes).
    if (cands.length === 0) cands.push(`${body1}-${dv1}`, compact);
    return Array.from(new Set(cands));
  };

  const resolveClientRut = async (req: any): Promise<string | null> => {
    try {
      const client = await storage.getClientByUserId(req.user.id);
      const rten = (client as any)?.rten;
      return rten ? String(rten) : null;
    } catch {
      return null;
    }
  };

  const tmsEtapaIndex = (estado: string | null): number =>
    (TMS_ETAPAS as readonly string[]).indexOf(String(estado ?? ''));

  // GET /api/client/orders → lista de órdenes del cliente logueado (por su RUT).
  app.get('/api/client/orders', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (req.user.role !== 'client') {
        return res.status(403).json({ message: 'No autorizado' });
      }
      const rten = await resolveClientRut(req);
      const tmsEnabled = isTmsConfigured();
      if (!rten) {
        return res.json({ tmsEnabled, rut: null, orders: [], message: 'No encontramos tu RUT asociado a una cuenta de cliente.' });
      }
      if (!tmsEnabled) {
        return res.json({ tmsEnabled: false, rut: rten, orders: [] });
      }

      let rows: any[] = [];
      for (const cand of rutQueryCandidates(rten)) {
        rows = await fetchTmsOrdersByClient(cand);
        if (rows.length > 0) break;
      }

      const orders = rows
        .map((o: any) => ({
          idErp: o.idErp,
          numeroDocumento: o.numeroDocumento,
          tipoDocumento: o.tipoDocumento,
          estado: o.estado,
          etapaIndex: tmsEtapaIndex(o.estado),
          esNoEntregado: o.estado === 'No Entregado',
          esRetiroCliente: !!o.esRetiroCliente,
          esDespachoParcial: !!o.esDespachoParcial,
          esBackorder: !!o.esBackorder,
          fechaEmision: o.fechaEmision,
          fechaCompromiso: o.fechaCompromiso,
          fechaConfirmacionDespacho: o.fechaConfirmacionDespacho,
          fechaActualizacion: o.fechaActualizacion,
        }))
        .sort((a: any, b: any) => new Date(b.fechaEmision || 0).getTime() - new Date(a.fechaEmision || 0).getTime());

      res.json({ tmsEnabled: true, rut: rten, etapas: TMS_ETAPAS, orders });
    } catch (error) {
      console.error('Error en /api/client/orders:', error);
      res.status(500).json({ message: 'Error al obtener tus pedidos' });
    }
  }));

  // GET /api/client/orders/:idErp → detalle de UNA orden del cliente (timeline).
  app.get('/api/client/orders/:idErp', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (req.user.role !== 'client') {
        return res.status(403).json({ message: 'No autorizado' });
      }
      if (!isTmsConfigured()) {
        return res.status(503).json({ message: 'El seguimiento no está disponible en este momento.' });
      }
      const rten = await resolveClientRut(req);
      if (!rten) {
        return res.status(403).json({ message: 'No encontramos tu RUT asociado a una cuenta de cliente.' });
      }

      const idErp = String(req.params.idErp || '').trim();
      const orden = await fetchTmsOrderDetail(idErp);
      if (!orden) {
        return res.status(404).json({ message: 'Pedido no encontrado.' });
      }

      // Candado de seguridad: la orden debe pertenecer al RUT del cliente logueado.
      if (normalizeRutCmp(orden.clienteIdErp) !== normalizeRutCmp(rten)) {
        return res.status(403).json({ message: 'No autorizado' });
      }

      const entregas = Array.isArray(orden.entregas) ? orden.entregas : [];
      res.json({
        idErp: orden.idErp,
        numeroDocumento: orden.numeroDocumento,
        tipoDocumento: orden.tipoDocumento,
        estado: orden.estado,
        etapas: TMS_ETAPAS,
        etapaIndex: tmsEtapaIndex(orden.estado),
        esNoEntregado: orden.estado === 'No Entregado',
        esRetiroCliente: !!orden.esRetiroCliente,
        esDespachoParcial: !!orden.esDespachoParcial,
        esBackorder: !!orden.esBackorder,
        fechaEmision: orden.fechaEmision,
        fechaCompromiso: orden.fechaCompromiso,
        fechaConfirmacionDespacho: orden.fechaConfirmacionDespacho,
        fechaActualizacion: orden.fechaActualizacion,
        resumen: orden.resumen ?? null,
        items: Array.isArray(orden.items) ? orden.items : [],
        entregas: entregas.map((e: any) => ({
          estadoEntrega: e.estadoEntrega ?? null,
          horaEntrega: e.horaEntrega ?? null,
          operarioNombre: e.operarioNombre ?? null,
          rutaPatente: e.rutaPatente ?? null,
          rutaEstado: e.rutaEstado ?? null,
          direccionEntrega: e.direccionEntrega ?? null,
          motivoRechazo: e.motivoRechazo ?? null,
          fotoEvidenciaUrl: e.fotoEvidenciaUrl ?? null,
          fotoFirmaUrl: e.fotoFirmaUrl ?? null,
          creadoEn: e.creadoEn ?? null,
        })),
      });
    } catch (error) {
      console.error('Error en /api/client/orders/:idErp:', error);
      res.status(500).json({ message: 'Error al obtener el detalle del pedido' });
    }
  }));

  // ==========================================================================
  // Espejo del TMS (lado admin). Refleja el estado real de las órdenes del TMS
  // (todas las del ERP, no solo las del Market). Sirve global o acotado a un
  // cliente por su RUT (clienteIdErp). KPIs por estado + lista paginada.
  // ==========================================================================
  const TMS_ROLES_INTERNOS = ['admin', 'supervisor', 'encargado_area', 'reception', 'logistica_bodega', 'salesperson'];

  // Resuelve el formato de RUT que el TMS reconoce (prueba con guión y compacto).
  const resolveTmsRut = async (raw: string): Promise<string | null> => {
    for (const cand of rutQueryCandidates(raw)) {
      const r = await fetchTmsOrders({ clienteIdErp: cand, limit: 1, offset: 0 });
      if (r.total > 0) return cand;
    }
    return null;
  };

  const ventanaFechas = (daysRaw: any): { fechaDesde?: string; fechaHasta?: string; days: number } => {
    const d = Number.parseInt(String(daysRaw ?? '0'), 10);
    if (!Number.isFinite(d) || d <= 0) return { days: 0 };
    const fechaHasta = new Date().toISOString().slice(0, 10);
    const fechaDesde = new Date(Date.now() - d * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
    return { fechaDesde, fechaHasta, days: d };
  };

  // GET /api/logistica/tms → KPIs + página de órdenes del TMS (global o por RUT).
  app.get('/api/logistica/tms', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (!TMS_ROLES_INTERNOS.includes(req.user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }

      const tmsEnabled = isTmsConfigured();
      const { fechaDesde, fechaHasta, days } = ventanaFechas(req.query.days);
      const estado = typeof req.query.estado === 'string' && req.query.estado ? String(req.query.estado) : undefined;
      const limit = Math.min(Math.max(Number.parseInt(String(req.query.limit ?? '50'), 10) || 50, 1), 200);
      const offset = Math.max(Number.parseInt(String(req.query.offset ?? '0'), 10) || 0, 0);
      const rutRaw = typeof req.query.clienteIdErp === 'string' ? req.query.clienteIdErp.trim() : '';

      const baseEmpty = {
        tmsEnabled,
        days,
        clienteIdErp: rutRaw || null,
        estados: TMS_ESTADOS_ALL,
        kpis: { total: 0, completadas: 0, fallidas: 0, pendientes: 0, porEstado: {} as Record<string, number> },
        page: { orders: [] as any[], total: 0, limit, offset },
      };

      if (!tmsEnabled) return res.json(baseEmpty);

      // Si se pide por cliente, resolvemos el RUT al formato que el TMS reconoce.
      let clienteIdErp: string | undefined;
      if (rutRaw) {
        const resolved = await resolveTmsRut(rutRaw);
        if (!resolved) return res.json({ ...baseEmpty, clienteIdErp: rutRaw });
        clienteIdErp = resolved;
      }

      // ?fresh=<algo> saltea el cache en memoria del TMS (botón "Actualizar" del panel).
      const fresh = req.query.fresh != null && String(req.query.fresh) !== '' && String(req.query.fresh) !== '0';

      const base = { clienteIdErp, fechaDesde, fechaHasta };
      const [counts, page] = await Promise.all([
        fetchTmsEstadoCounts(base, fresh),
        fetchTmsOrders({ ...base, estado, limit, offset }, fresh),
      ]);

      const completadas = counts.porEstado['Entregado'] || 0;
      const fallidas = counts.porEstado['No Entregado'] || 0;
      const pendientes = Math.max(counts.total - completadas - fallidas, 0);

      const orders = page.data.map((o: any) => ({
        idErp: o.idErp,
        numeroDocumento: o.numeroDocumento,
        tipoDocumento: o.tipoDocumento,
        estado: o.estado,
        etapaIndex: tmsEtapaIndex(o.estado),
        esNoEntregado: o.estado === 'No Entregado',
        esRetiroCliente: !!o.esRetiroCliente,
        esDespachoParcial: !!o.esDespachoParcial,
        esBackorder: !!o.esBackorder,
        clienteIdErp: o.clienteIdErp,
        clienteNombre: o.clienteNombre,
        clienteComuna: o.clienteComuna,
        fechaEmision: o.fechaEmision,
        fechaCompromiso: o.fechaCompromiso,
        fechaConfirmacionDespacho: o.fechaConfirmacionDespacho,
        fechaActualizacion: o.fechaActualizacion,
      }));

      res.json({
        tmsEnabled: true,
        days,
        clienteIdErp: clienteIdErp || null,
        estados: TMS_ESTADOS_ALL,
        kpis: { total: counts.total, completadas, fallidas, pendientes, porEstado: counts.porEstado },
        page: { orders, total: page.total, limit, offset },
      });
    } catch (error) {
      console.error('Error en /api/logistica/tms:', error);
      res.status(500).json({ message: 'Error al obtener las órdenes del TMS' });
    }
  }));

  // GET /api/logistica/tms/:idErp → detalle de una orden del TMS (admin, sin candado de RUT).
  app.get('/api/logistica/tms/:idErp', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (!TMS_ROLES_INTERNOS.includes(req.user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }
      if (!isTmsConfigured()) {
        return res.status(503).json({ message: 'El TMS no está conectado en este entorno.' });
      }
      const orden = await fetchTmsOrderDetail(String(req.params.idErp || '').trim());
      if (!orden) return res.status(404).json({ message: 'Orden no encontrada.' });

      const entregas = Array.isArray(orden.entregas) ? orden.entregas : [];
      res.json({
        idErp: orden.idErp,
        numeroDocumento: orden.numeroDocumento,
        tipoDocumento: orden.tipoDocumento,
        estado: orden.estado,
        etapas: TMS_ETAPAS,
        etapaIndex: tmsEtapaIndex(orden.estado),
        esNoEntregado: orden.estado === 'No Entregado',
        esRetiroCliente: !!orden.esRetiroCliente,
        esDespachoParcial: !!orden.esDespachoParcial,
        esBackorder: !!orden.esBackorder,
        clienteIdErp: orden.clienteIdErp,
        clienteNombre: orden.clienteNombre,
        clienteComuna: orden.clienteComuna,
        fechaEmision: orden.fechaEmision,
        fechaCompromiso: orden.fechaCompromiso,
        fechaConfirmacionDespacho: orden.fechaConfirmacionDespacho,
        fechaActualizacion: orden.fechaActualizacion,
        resumen: orden.resumen ?? null,
        items: Array.isArray(orden.items) ? orden.items : [],
        entregas: entregas.map((e: any) => ({
          estadoEntrega: e.estadoEntrega ?? null,
          horaEntrega: e.horaEntrega ?? null,
          operarioNombre: e.operarioNombre ?? null,
          rutaPatente: e.rutaPatente ?? null,
          rutaEstado: e.rutaEstado ?? null,
          direccionEntrega: e.direccionEntrega ?? null,
          motivoRechazo: e.motivoRechazo ?? null,
          fotoEvidenciaUrl: e.fotoEvidenciaUrl ?? null,
          fotoFirmaUrl: e.fotoFirmaUrl ?? null,
          creadoEn: e.creadoEn ?? null,
        })),
      });
    } catch (error) {
      console.error('Error en /api/logistica/tms/:idErp:', error);
      res.status(500).json({ message: 'Error al obtener el detalle de la orden' });
    }
  }));

  // ==========================================================================
  // GET /api/logistica/rutas → espejo de "Gestión de Rutas" del TMS. Lista de
  // rutas con filtro por estado (Pendiente/Cargando/En Ruta/Completada) y
  // paginación. Devuelve los objetos CRUDOS del TMS para no perder campos.
  // ==========================================================================
  app.get('/api/logistica/rutas', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (!TMS_ROLES_INTERNOS.includes(req.user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }
      const tmsEnabled = isTmsConfigured();
      const estado = typeof req.query.estado === 'string' && req.query.estado ? String(req.query.estado) : undefined;
      const limit = Math.min(Math.max(Number.parseInt(String(req.query.limit ?? '10'), 10) || 10, 1), 100);
      const offset = Math.max(Number.parseInt(String(req.query.offset ?? '0'), 10) || 0, 0);
      const fresh = req.query.fresh != null && String(req.query.fresh) !== '' && String(req.query.fresh) !== '0';

      if (!tmsEnabled) {
        return res.json({ tmsEnabled: false, estados: TMS_RUTA_ESTADOS, data: [], total: 0, limit, offset });
      }

      const result = await fetchTmsRutas({ estado, limit, offset }, fresh);
      res.json({ tmsEnabled: true, estados: TMS_RUTA_ESTADOS, ...result });
    } catch (error) {
      console.error('Error en /api/logistica/rutas:', error);
      res.status(500).json({ message: 'Error al obtener las rutas del TMS' });
    }
  }));

  // GET /api/logistica/rutas/:id → detalle de una ruta (con entregas[]).
  app.get('/api/logistica/rutas/:id', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      if (!TMS_ROLES_INTERNOS.includes(req.user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }
      if (!isTmsConfigured()) {
        return res.status(503).json({ message: 'El TMS no está conectado en este entorno.' });
      }
      const fresh = req.query.fresh != null && String(req.query.fresh) !== '' && String(req.query.fresh) !== '0';
      const ruta = await fetchTmsRutaDetail(String(req.params.id || '').trim(), fresh);
      if (!ruta) return res.status(404).json({ message: 'Ruta no encontrada.' });
      res.json(ruta);
    } catch (error) {
      console.error('Error en /api/logistica/rutas/:id:', error);
      res.status(500).json({ message: 'Error al obtener el detalle de la ruta' });
    }
  }));

  // Get pending orders count
  app.get('/api/ecommerce/orders/pending-count', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;

      // Recepción ve TODOS los pedidos que aún no han sido ingresados al ERP
      // (pending, approved, modified, sent). De esa forma siempre ve la bandeja
      // completa y puede marcarlos como "ingresado" cuando corresponda. Los estados
      // logísticos posteriores (preparacion/transito/entregado) ya pasaron esa etapa
      // y no deben inflar el badge de pendientes de ingreso.
      if (user.role === 'reception') {
        const { ecommerceOrders } = await import('@shared/schema');
        const { sql, notInArray } = await import('drizzle-orm');
        const rows = await db
          .select({ id: ecommerceOrders.id })
          .from(ecommerceOrders)
          .where(notInArray(ecommerceOrders.status, ['ingresado', 'rejected', 'archived', 'suggested_pending', 'preparacion', 'transito', 'entregado']));
        return res.json({ count: rows.length });
      }

      const filters: any = { status: 'pending' };
      if (user.role === 'salesperson') {
        filters.salespersonId = user.id;
      } else if (user.role === 'admin' || (user.role === 'supervisor' || user.role === 'encargado_area')) {
        // Admin/supervisor ven todos los pendientes
      } else {
        return res.json({ count: 0 }); // Other roles don't see this badge
      }

      const orders = await storage.getEcommerceOrders(filters);
      res.json({ count: orders.length });
    } catch (error) {
      console.error('Error fetching pending orders count:', error);
      res.status(500).json({ message: 'Error al obtener cuenta de pedidos' });
    }
  }));

  // Update order status
  app.patch('/api/ecommerce/orders/:id/status', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const { status } = req.body;
    const user = req.user;

    if (!['admin', 'supervisor', 'encargado_area', 'salesperson', 'reception'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    // Incluye los estados logísticos internos (preparacion/transito/entregado) que
    // se marcan a mano desde el detalle del pedido para alimentar la vista de Logística.
    const validStatuses = ['pending', 'approved', 'modified', 'rejected', 'sent', 'archived', 'ingresado', 'preparacion', 'transito', 'entregado'];

    // Reception puede marcar como ingresado o descartar pedidos (con motivo)
    if (user.role === 'reception' && !['ingresado', 'rejected'].includes(status)) {
      return res.status(403).json({ message: 'Recepción solo puede marcar pedidos como ingresados o descartados' });
    }
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ message: 'Estado inválido' });
    }

    // Validar motivo cuando se descarta el pedido
    if (status === 'rejected') {
      const reason = String(req.body?.rejectedReason || '').trim();
      if (!reason) {
        return res.status(400).json({ message: 'Debes indicar el motivo del descarte' });
      }
    }

    const { ecommerceOrders } = await import('@shared/schema');
    const { eq } = await import('drizzle-orm');
    const { db } = await import('./db');

    const [previous] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);

    // Bloqueamos transiciones manuales sobre sugeridos aún pendientes de respuesta del
    // cliente: el cliente es quien debe aceptarlo/modificarlo/rechazarlo desde su portal.
    if (previous && previous.status === 'suggested_pending') {
      return res.status(409).json({
        message: 'Este pedido es un sugerido pendiente de respuesta del cliente. El cliente debe aceptarlo, modificarlo o rechazarlo desde su portal antes de cambiar su estado.',
      });
    }

    const [updated] = await db.update(ecommerceOrders)
      .set({
        status,
        ...(status === 'approved' ? { approvedAt: new Date(), approvedById: user.id } : {}),
        ...(status === 'modified' ? { modifiedAt: new Date(), modifiedById: user.id } : {}),
        ...(status === 'ingresado' ? {
          ingresadoAt: new Date(),
          ingresadoById: user.id,
          ...(req.body?.ingresadoNotes ? { ingresadoNotes: String(req.body.ingresadoNotes).slice(0, 2000) } : {}),
        } : {}),
        ...(status === 'rejected' ? {
          rejectedAt: new Date(),
          rejectedById: user.id,
          rejectedReason: String(req.body?.rejectedReason || '').slice(0, 2000),
        } : {}),
        updatedAt: new Date(),
      })
      .where(eq(ecommerceOrders.id, id))
      .returning();

    if (!updated) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    // Notify client when the order transitions to "modified" (only on actual transition).
    if (status === 'modified' && previous?.status !== 'modified') {
      NotifyHelper.notifyOrderModified({
        orderId: updated.id,
        orderNumber: updated.id,
        clientEmail: updated.clientEmail,
        clientName: updated.clientName,
        newTotal: Number(updated.total) || 0,
        previousTotal: previous ? Number(previous.total) || 0 : undefined,
        paymentCondition: updated.paymentCondition,
      }).catch(err => console.warn('[order-modified-email]', err?.message));
    }

    // Process credit updates if the order is approved
    if (status === 'approved') {
      try {
        const { salespeopleUsers, users, clients } = await import('@shared/schema');
        const { or, desc } = await import('drizzle-orm');
        
        let clientRecordMatch = null;
        if (updated.clientId) {
          // Find user to map to client
          const sUser = await db.select().from(salespeopleUsers).where(eq(salespeopleUsers.id, updated.clientId)).limit(1);
          const legacyUser = sUser.length === 0 ? await db.select().from(users).where(eq(users.id, updated.clientId)).limit(1) : null;
          
          const userName = sUser[0]?.salespersonName || legacyUser[0]?.firstName || null;
          
          if (userName) {
            const possibleClients = await db.select().from(clients)
              .where(or(
                eq(clients.userId, updated.clientId),
                eq(clients.nokoen, userName.toUpperCase())
              ))
              .orderBy(desc(clients.updatedAt))
              .limit(1);
              
            if (possibleClients.length > 0) {
              clientRecordMatch = possibleClients[0];
            }
          }
        }
        
        if (clientRecordMatch && clientRecordMatch.crlt) {
          const limit = parseFloat(clientRecordMatch.crlt) || 0;
          const used = parseFloat(clientRecordMatch.crsd || '0') || 0;
          const orderTotal = parseFloat(updated.total as string || '0') || 0;
          
          const newUsed = used + orderTotal;
          const newAvailable = Math.max(0, limit - newUsed);
          
          await db.update(clients).set({
            crsd: newUsed.toString(),
            cren: newAvailable.toString()
          }).where(eq(clients.id, clientRecordMatch.id));
        }
      } catch (e) {
        console.error('Error updating client credit on order approval:', e);
      }
    }

    res.json(updated);
  }));

  // Reenvía manualmente al cliente el correo de "pedido modificado / listo para pago",
  // con link directo a su pedido en el portal. Es un envío explícito: ignora el toggle
  // global de notificaciones (force=true) para que el botón siempre dispare el correo.
  app.post('/api/ecommerce/orders/:id/notify-modified', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const user = req.user;
    if (!['admin', 'supervisor', 'encargado_area', 'salesperson', 'reception'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { ecommerceOrders } = await import('@shared/schema');
    const { eq } = await import('drizzle-orm');
    const { db } = await import('./db');

    const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);
    if (!order) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }
    if (!order.clientEmail) {
      return res.status(400).json({ message: 'El pedido no tiene un email de cliente para notificar.' });
    }

    const sent = await NotifyHelper.notifyOrderModified({
      orderId: order.id,
      orderNumber: order.id,
      clientEmail: order.clientEmail,
      clientName: order.clientName,
      newTotal: Number(order.total) || 0,
      paymentCondition: order.paymentCondition,
    }, true);

    if (!sent) {
      return res.status(502).json({ message: 'No se pudo enviar el correo. Revisá la configuración de correo.' });
    }
    res.json({ ok: true, to: order.clientEmail });
  }));

  // Update order payment condition (admin/supervisor/reception).
  // If order is pending:
  //   - "Transferencia": auto-approve, NO consume credit
  //   - "Crédito": auto-approve AND consume client credit (same side-effect as status=approved)
  app.patch('/api/ecommerce/orders/:id/payment-condition', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const user = req.user;

    if (!['admin', 'supervisor', 'encargado_area', 'reception'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const raw = typeof req.body?.paymentCondition === 'string' ? req.body.paymentCondition.trim() : '';
    if (!raw) {
      return res.status(400).json({ message: 'Condición de pago requerida' });
    }
    const paymentCondition = raw.slice(0, 120);

    const { ecommerceOrders } = await import('@shared/schema');
    const { eq } = await import('drizzle-orm');
    const { db } = await import('./db');

    const [existing] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);
    if (!existing) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    const isTransferencia = /transferencia/i.test(paymentCondition);
    const isCredito = /cr[eé]dito/i.test(paymentCondition);
    const shouldAutoApprove = (isTransferencia || isCredito) && existing.status === 'pending';

    const [updated] = await db.update(ecommerceOrders)
      .set({
        paymentCondition,
        ...(shouldAutoApprove ? { status: 'approved', approvedAt: new Date(), approvedById: user.id } : {}),
        updatedAt: new Date(),
      })
      .where(eq(ecommerceOrders.id, id))
      .returning();

    // Consume client credit if approved via "Crédito" (mirrors /status approval logic)
    if (shouldAutoApprove && isCredito) {
      try {
        const { salespeopleUsers, users, clients } = await import('@shared/schema');
        const { or, desc } = await import('drizzle-orm');

        let clientRecordMatch = null;
        if (updated.clientId) {
          const sUser = await db.select().from(salespeopleUsers).where(eq(salespeopleUsers.id, updated.clientId)).limit(1);
          const legacyUser = sUser.length === 0 ? await db.select().from(users).where(eq(users.id, updated.clientId)).limit(1) : null;

          const userName = sUser[0]?.salespersonName || legacyUser?.[0]?.firstName || null;

          if (userName) {
            const possibleClients = await db.select().from(clients)
              .where(or(
                eq(clients.userId, updated.clientId),
                eq(clients.nokoen, userName.toUpperCase())
              ))
              .orderBy(desc(clients.updatedAt))
              .limit(1);

            if (possibleClients.length > 0) {
              clientRecordMatch = possibleClients[0];
            }
          }
        }

        if (clientRecordMatch && clientRecordMatch.crlt) {
          const limit = parseFloat(clientRecordMatch.crlt) || 0;
          const used = parseFloat(clientRecordMatch.crsd || '0') || 0;
          const orderTotal = parseFloat(updated.total as string || '0') || 0;

          const newUsed = used + orderTotal;
          const newAvailable = Math.max(0, limit - newUsed);

          await db.update(clients).set({
            crsd: newUsed.toString(),
            cren: newAvailable.toString()
          }).where(eq(clients.id, clientRecordMatch.id));
        }
      } catch (e) {
        console.error('Error updating client credit on payment-condition credit approval:', e);
      }
    }

    res.json(updated);
  }));

  // Manually edit order item prices (admin/supervisor/salesperson only).
  // Accepts a full replacement items array; recomputes totals; marks order as modified.
  app.patch('/api/ecommerce/orders/:id/items', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const user = req.user;

    if (!['admin', 'supervisor', 'encargado_area', 'salesperson'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const itemsSchema = z.object({
      items: z.array(z.object({
        productId: z.string().optional().nullable(),
        productName: z.string(),
        productCode: z.string().optional().nullable(),
        sku: z.string().optional().nullable(),
        quantity: z.number().nonnegative(),
        unitPrice: z.number().nonnegative(),
        imageUrl: z.string().optional().nullable(),
        selectedColor: z.string().optional().nullable(),
        selectedPackaging: z.string().optional().nullable(),
      }).passthrough()),
    });

    const parsed = itemsSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ message: 'Error de validación', errors: parsed.error.errors });
    }

    const { ecommerceOrders } = await import('@shared/schema');
    const [existing] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);
    if (!existing) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    // Bloqueamos edición admin sobre sugeridos aún pendientes: es el cliente quien debe
    // modificarlos desde su portal usando el endpoint /suggested-modify.
    if (existing.status === 'suggested_pending') {
      return res.status(409).json({
        message: 'No se puede editar un sugerido pendiente desde acá. El cliente debe responderlo primero desde su portal.',
      });
    }

    const normalizedItems = parsed.data.items.map((it: any) => {
      const unitPrice = Math.round(Number(it.unitPrice) || 0);
      const qty = Number(it.quantity) || 0;
      const totalPrice = Math.round(unitPrice * qty);
      return {
        ...it,
        unitPrice,
        totalPrice,
        discountAmount: 0,
        unitPriceAfterDiscount: unitPrice,
        totalPriceAfterDiscount: totalPrice,
        priceSource: 'manual',
      };
    });

    const subtotal = normalizedItems.reduce((s, it) => s + (Number(it.totalPrice) || 0), 0);
    const tax = Math.round(subtotal * 0.19);
    const total = subtotal + tax;

    const previousTotal = Number(existing.total) || 0;

    const [updated] = await db.update(ecommerceOrders)
      .set({
        items: normalizedItems,
        subtotal: String(subtotal),
        tax: String(tax),
        total: String(total),
        status: 'modified',
        modifiedAt: new Date(),
        modifiedById: user.id,
        updatedAt: new Date(),
      })
      .where(eq(ecommerceOrders.id, id))
      .returning();

    NotifyHelper.notifyOrderModified({
      orderId: updated.id,
      orderNumber: updated.id,
      clientEmail: updated.clientEmail,
      clientName: updated.clientName,
      newTotal: Number(updated.total) || 0,
      previousTotal,
      paymentCondition: updated.paymentCondition,
    }).catch(err => console.warn('[order-modified-email]', err?.message));

    res.json(updated);
  }));

  // Recalculate order item prices from the customer's currently assigned price list (admin/supervisor/salesperson).
  // Looks up the client's lcen + branch discount and overwrites unitPrice for each item.
  app.post('/api/ecommerce/orders/:id/recalculate-prices', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const user = req.user;

    if (!['admin', 'supervisor', 'encargado_area', 'salesperson'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { ecommerceOrders } = await import('@shared/schema');
    const [existing] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);
    if (!existing) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    // branchId opcional: si el admin/recepcionista sabe qué sucursal se usó en ese pedido,
    // lo pasa y recalculamos con SU lcen + branchDiscountPercent. Sin branchId caemos al
    // registro-cliente por defecto (comportamiento previo).
    const branchIdParam: string | null = (req.body?.branchId || req.query?.branchId || null) as any;
    let client: any = null;
    try {
      if (branchIdParam) {
        const { clients: clientsTbl } = await import('@shared/schema');
        const [branchRecord] = await db
          .select()
          .from(clientsTbl)
          .where(eq(clientsTbl.id, branchIdParam))
          .limit(1);
        if (branchRecord) client = branchRecord;
      }
      if (!client) {
        client = existing.clientId ? await storage.getClientByUserId(existing.clientId) : null;
      }
    } catch (e) {
      console.warn('[recalculate-prices] could not fetch client:', e);
    }
    if (!client) {
      return res.status(400).json({ message: 'No se pudo resolver el cliente asociado al pedido para obtener su lista de precios.' });
    }

    const existingItems = Array.isArray(existing.items)
      ? existing.items as any[]
      : (typeof existing.items === 'string' ? JSON.parse(existing.items) : []);

    const resolved = await resolveItemsPricing(existingItems, client);

    const previousTotal = Number(existing.total) || 0;

    const [updated] = await db.update(ecommerceOrders)
      .set({
        items: resolved.items,
        subtotal: String(resolved.subtotal),
        tax: String(resolved.tax),
        total: String(resolved.total),
        branchDiscountPercent: String(resolved.branchDiscountPct || 0),
        priceListUsed: resolved.priceListUsed,
        status: 'modified',
        modifiedAt: new Date(),
        modifiedById: user.id,
        updatedAt: new Date(),
      })
      .where(eq(ecommerceOrders.id, id))
      .returning();

    NotifyHelper.notifyOrderModified({
      orderId: updated.id,
      orderNumber: updated.id,
      clientEmail: updated.clientEmail,
      clientName: updated.clientName,
      newTotal: Number(updated.total) || 0,
      previousTotal,
      paymentCondition: updated.paymentCondition,
    }).catch(err => console.warn('[order-modified-email]', err?.message));

    res.json({
      order: updated,
      priceListUsed: resolved.priceListUsed,
      branchDiscountPct: resolved.branchDiscountPct,
      warnings: resolved.warnings,
    });
  }));

  // Auto-generate quote from ecommerce order, linked to the main branch (sucursal principal)
  // matched by the ordering user's RUT. Returns the created quote + items for PDF generation.
  app.post('/api/ecommerce/orders/:id/generate-quote', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const user = req.user;

    if (!['admin', 'supervisor', 'encargado_area', 'salesperson', 'reception'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado para generar cotizaciones' });
    }

    const [order] = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id)).limit(1);
    if (!order) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    // Resolve the main-branch client record: use the ordering user's RUT and prefer the
    // parent (parentClientId IS NULL = casa matriz/sucursal principal). Fallback to any match.
    let mainBranchClient: any = null;
    let resolvedRut: string | null = null;
    try {
      const { clients } = await import('../shared/schema');

      // 1) Try to get RUT directly from salespeopleUsers.clientRut
      const [userRecord] = await db.select().from(salespeopleUsers)
        .where(eq(salespeopleUsers.id, order.clientId))
        .limit(1);

      if (userRecord?.clientRut) {
        resolvedRut = userRecord.clientRut;
        const matches = await storage.getClientsByRut(userRecord.clientRut);
        // getClientsByRut orders by parentClientId NULLS FIRST, so prefer parent.
        mainBranchClient = matches.find((c: any) => !c.parentClientId) || matches[0] || null;
      }

      // 2) If no RUT on user, fall back to resolving any client for that user, then
      //    walk up the parentClientId chain to the casa matriz, and use its RUT to
      //    re-query for all sibling branches (and pick the parent).
      if (!mainBranchClient) {
        const anyClient = await storage.getClientByUserId(order.clientId);
        if (anyClient) {
          let current: any = anyClient;
          for (let i = 0; i < 5 && current?.parentClientId; i++) {
            const [parent] = await db.select().from(clients)
              .where(eq(clients.id, current.parentClientId))
              .limit(1);
            if (!parent) break;
            current = parent;
          }
          mainBranchClient = current;
          resolvedRut = resolvedRut || current?.rten || null;

          // If we now have a RUT but multiple records exist, re-resolve to guarantee parent preference
          if (resolvedRut) {
            const matches = await storage.getClientsByRut(resolvedRut);
            mainBranchClient = matches.find((c: any) => !c.parentClientId) || mainBranchClient;
          }
        }
      }
    } catch (e) {
      console.warn('[generate-quote] client lookup failed:', e);
    }

    // Normalize items and compute totals
    const rawOrderItems: any[] = Array.isArray(order.items)
      ? (order.items as any[])
      : (typeof order.items === 'string' ? JSON.parse(order.items) : []);

    // Split product lines from legacy "Flete / Despacho a Domicilio" (FLETE-001) lines.
    // Old orders stored one single flete line; we rebuild per-unit despacho lines from
    // the product items' packaging using current shipping-rates config, so downstream
    // views (tomador/tienda) split Subtotal Productos / Subtotal Flete correctly.
    const productOrderItems = rawOrderItems.filter((i: any) => {
      const pid = String(i.productId || '').toUpperCase();
      const sku = String(i.sku || i.productCode || '').toUpperCase();
      const name = String(i.productName || '');
      return pid !== 'FLETE-001' && sku !== 'FLETE-001' && !/^Flete\s*\//i.test(name);
    });

    // Load shipping rates + discount config
    let shippingRates: Record<string, number> = {};
    let shippingSkus: Record<string, string> = {};
    let shippingDiscountPercent = 0;
    try {
      const { sql } = await import('drizzle-orm');
      const ratesRes: any = await db.execute(sql`SELECT value FROM app_config WHERE key = 'ecommerce_shipping_rates'`);
      const ratesRow = ratesRes.rows?.[0]?.value || {};
      for (const [k, v] of Object.entries(ratesRow)) {
        if (typeof v === 'object' && v !== null) {
          shippingRates[k] = Number((v as any).price) || 0;
          shippingSkus[k] = String((v as any).sku || '');
        } else {
          shippingRates[k] = Number(v) || 0;
        }
      }
      const { storeConfig: storeConfigTable } = await import('../shared/schema');
      const [cfg] = await db.select().from(storeConfigTable).limit(1);
      shippingDiscountPercent = Number((cfg as any)?.checkoutSettings?.shippingDiscountPercentage) || 0;
    } catch (e) {
      console.warn('[generate-quote] failed to load shipping config:', e);
    }

    const { getShippingKey } = await import('../shared/format-utils.js');
    const SHIPPING_LABELS: Record<string, string> = {
      '1_4_galon': 'Despacho 1/4 Galón',
      'galon': 'Despacho Galón',
      'bd_4gl': 'Despacho Balde 4GL',
      'bd_5gl': 'Despacho Balde 5GL',
    };

    const shippingFactor = Math.max(0, 1 - shippingDiscountPercent / 100);
    const discountSuffix = shippingDiscountPercent > 0 ? ` (-${shippingDiscountPercent}%)` : '';

    // Aggregate qty per shipping rate key from product lines.
    const shippingAgg = new Map<string, { qty: number; unit: string }>();
    for (const item of productOrderItems) {
      const unit = item.selectedPackaging || item.productUnit || item.unit || '';
      if (!unit) continue;
      const key = getShippingKey(unit);
      if (!key || !shippingRates[key]) continue;
      const qty = Number(item.quantity || 0);
      if (qty <= 0) continue;
      const existing = shippingAgg.get(key);
      if (existing) existing.qty += qty;
      else shippingAgg.set(key, { qty, unit });
    }

    const shippingLines: Array<{ productName: string; productCode: string; productUnit: string; unitPrice: number; quantity: number }> = [];
    shippingAgg.forEach((b, key) => {
      const unitPrice = Math.round(shippingRates[key] * shippingFactor);
      if (unitPrice <= 0 || b.qty <= 0) return;
      const sku = shippingSkus[key] || key.toUpperCase();
      const label = `${SHIPPING_LABELS[key] || `Despacho ${b.unit || key}`}${discountSuffix}`;
      shippingLines.push({
        productName: label,
        productCode: sku,
        productUnit: 'UN',
        unitPrice,
        quantity: b.qty,
      });
    });

    // Compute totals from rebuilt lines (products with their own prices + new despacho lines).
    const productsSubtotal = productOrderItems.reduce((s: number, i: any) => {
      const lineTotal = Number(i.subtotal ?? i.totalPrice ?? ((Number(i.unitPrice || i.price || 0)) * Number(i.quantity || 0)));
      return s + (isFinite(lineTotal) ? lineTotal : 0);
    }, 0);
    const shippingSubtotal = shippingLines.reduce((s, l) => s + l.unitPrice * l.quantity, 0);
    const subtotal = productsSubtotal + shippingSubtotal;
    const tax = Math.round(subtotal * 0.19);
    const total = subtotal + tax;

    // Build quote payload — prefer main-branch client data when available
    const validUntil = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    const quotePayload: any = {
      clientName: mainBranchClient?.nokoen || order.clientName,
      clientId: mainBranchClient?.id || null,
      clientRut: mainBranchClient?.rten || resolvedRut || '',
      clientEmail: mainBranchClient?.email || order.clientEmail || '',
      clientPhone: mainBranchClient?.foen || order.clientPhone || '',
      clientAddress: mainBranchClient?.dien || order.shippingAddress || '',
      createdBy: user.id,
      status: 'draft',
      validUntil,
      subtotal: subtotal.toString(),
      taxAmount: tax.toString(),
      total: total.toString(),
      paymentCondition: order.paymentCondition || mainBranchClient?.cpen || 'transferencia',
      notes: order.notes
        ? `[Pedido eCommerce #${order.id}] ${order.notes}`
        : `[Pedido eCommerce #${order.id}]`,
    };

    const quote = await storage.createQuote(quotePayload);

    // Create items — products first (with real packaging as productUnit), then
    // per-unit despacho lines derived from shipping-rates config.
    const createdItems: any[] = [];
    for (const item of productOrderItems) {
      const unitPrice = Number(item.unitPrice ?? item.price ?? 0);
      const quantity = Number(item.quantity ?? 0);
      if (!item.productName || quantity <= 0) continue;
      const productUnit = String(item.selectedPackaging || item.productUnit || item.unit || 'UN');
      const created = await storage.createQuoteItem({
        quoteId: quote.id,
        type: 'standard',
        productName: item.productName,
        productCode: item.productCode || item.sku || '',
        productUnit,
        unitPrice: unitPrice.toString(),
        quantity: quantity.toString(),
      } as any);
      createdItems.push(created);
    }
    for (const line of shippingLines) {
      const created = await storage.createQuoteItem({
        quoteId: quote.id,
        type: 'standard',
        productName: line.productName,
        productCode: line.productCode,
        productUnit: line.productUnit,
        unitPrice: line.unitPrice.toString(),
        quantity: line.quantity.toString(),
      } as any);
      createdItems.push(created);
    }

    // Link quote to order so the UI can reflect "ya cotizado"
    try {
      await db.update(ecommerceOrders)
        .set({ quoteId: quote.id, updatedAt: new Date() })
        .where(eq(ecommerceOrders.id, id));
    } catch (e) {
      console.warn('[generate-quote] failed to link quoteId on order:', e);
    }

    res.json({
      quote,
      items: createdItems,
      matchedClient: mainBranchClient ? {
        id: mainBranchClient.id,
        koen: mainBranchClient.koen,
        nokoen: mainBranchClient.nokoen,
        rten: mainBranchClient.rten,
        branchLabel: mainBranchClient.branchLabel,
        isParent: !mainBranchClient.parentClientId,
      } : null,
    });
  }));

  // Update order receipt
  app.patch('/api/ecommerce/orders/:id/receipt', requireAuth, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const { paymentReceiptUrl } = req.body;
    const user = req.user;

    const { ecommerceOrders } = await import('@shared/schema');
    const { eq, and } = await import('drizzle-orm');
    const { db } = await import('./db');

    // Make sure order exists and user either owns it or is admin/supervisor
    const result = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, id));
    const order = result[0];

    if (!order) {
      return res.status(404).json({ message: 'Pedido no encontrado' });
    }

    if (order.clientId !== user.id && !['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
      return res.status(403).json({ message: 'No autorizado para modificar este pedido' });
    }

    const [updated] = await db.update(ecommerceOrders)
      .set({
        paymentReceiptUrl,
        updatedAt: new Date(),
      })
      .where(eq(ecommerceOrders.id, id))
      .returning();

    res.json(updated);
  }));

