  app.delete('/api/ecommerce/categories-config/:id', requireAuth, asyncHandler(async (req: any, res: any) => {
    if (!['admin', 'supervisor', 'encargado_area'].includes(req.user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { id } = req.params;
    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    
    const result = await db.execute(sql`
      SELECT value FROM app_config WHERE key = 'ecommerce_categories'
    `);
    const row = (result as any).rows?.[0];
    let categories: any[] = row?.value || [];
    
    const deleted = categories.find((c: any) => c.id === id);
    categories = categories.filter((c: any) => c.id !== id);
    
    await db.execute(sql`
      INSERT INTO app_config (key, value, updated_at)
      VALUES ('ecommerce_categories', ${JSON.stringify(categories)}::jsonb, NOW())
      ON CONFLICT (key) DO UPDATE SET value = ${JSON.stringify(categories)}::jsonb, updated_at = NOW()
    `);
    
    // Unset categoria for products that were in this category
    if (deleted) {
      await db.execute(sql`
        UPDATE ecommerce_products SET categoria = NULL 
        WHERE categoria = ${deleted.name}
      `);
    }
    
    res.json({ success: true });
  }));

  // Rename a custom category
  app.patch('/api/ecommerce/categories-config/:id', requireAuth, asyncHandler(async (req: any, res: any) => {
    if (!['admin', 'supervisor', 'encargado_area'].includes(req.user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { id } = req.params;
    const { name, description, color } = req.body;
    
    if (name !== undefined && (!name || !name.trim())) {
      return res.status(400).json({ message: 'El nombre de la categoría es requerido' });
    }

    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    
    const result = await db.execute(sql`
      SELECT value FROM app_config WHERE key = 'ecommerce_categories'
    `);
    const row = (result as any).rows?.[0];
    let categories: any[] = row?.value || [];
    
    const catIndex = categories.findIndex((c: any) => c.id === id);
    if (catIndex === -1) {
      return res.status(404).json({ message: 'Categoría no encontrada' });
    }

    const oldName = categories[catIndex].name;
    const newName = name?.trim() || oldName;
    
    // Check for duplicate names (excluding this category)
    if (name && categories.some((c: any, i: number) => i !== catIndex && c.name.toLowerCase() === newName.toLowerCase())) {
      return res.status(400).json({ message: 'Ya existe una categoría con ese nombre' });
    }

    // Update the category
    if (name) categories[catIndex].name = newName;
    if (description !== undefined) categories[catIndex].description = description.trim();
    if (color) categories[catIndex].color = color;
    
    await db.execute(sql`
      INSERT INTO app_config (key, value, updated_at)
      VALUES ('ecommerce_categories', ${JSON.stringify(categories)}::jsonb, NOW())
      ON CONFLICT (key) DO UPDATE SET value = ${JSON.stringify(categories)}::jsonb, updated_at = NOW()
    `);
    
    // If name changed, update all products referencing the old name
    if (name && oldName !== newName) {
      await db.execute(sql`
        UPDATE ecommerce_products SET categoria = ${newName}
        WHERE categoria = ${oldName}
      `);
    }
    
    res.json(categories[catIndex]);
  }));

  // Reorder categories (swap two categories)
  app.put('/api/ecommerce/categories-config/reorder', requireAuth, asyncHandler(async (req: any, res: any) => {
    if (!['admin', 'supervisor', 'encargado_area'].includes(req.user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { id, direction } = req.body; // direction: 'up' or 'down'
    if (!id || !['up', 'down'].includes(direction)) {
      return res.status(400).json({ message: 'ID y dirección (up/down) requeridos' });
    }

    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    
    const result = await db.execute(sql`
      SELECT value FROM app_config WHERE key = 'ecommerce_categories'
    `);
    const row = (result as any).rows?.[0];
    let categories: any[] = row?.value || [];
    
    const currentIndex = categories.findIndex((c: any) => c.id === id);
    if (currentIndex === -1) {
      return res.status(404).json({ message: 'Categoría no encontrada' });
    }

    const swapIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
    if (swapIndex < 0 || swapIndex >= categories.length) {
      return res.status(400).json({ message: 'No se puede mover más' });
    }

    // Swap
    [categories[currentIndex], categories[swapIndex]] = [categories[swapIndex], categories[currentIndex]];
    
    await db.execute(sql`
      INSERT INTO app_config (key, value, updated_at)
      VALUES ('ecommerce_categories', ${JSON.stringify(categories)}::jsonb, NOW())
      ON CONFLICT (key) DO UPDATE SET value = ${JSON.stringify(categories)}::jsonb, updated_at = NOW()
    `);
    
    res.json(categories);
  }));

  // Assign a product family to a category (update group_name)
  app.patch('/api/ecommerce/product-category', requireAuth, asyncHandler(async (req: any, res: any) => {
    if (!['admin', 'supervisor', 'encargado_area'].includes(req.user.role)) {
      return res.status(403).json({ message: 'No autorizado' });
    }

    const { productFamily, categoryName, action } = req.body;
    // action: 'add' (default), 'remove', or 'set' (legacy single-category)
    if (!productFamily) {
      return res.status(400).json({ message: 'productFamily es requerido' });
    }

    const { db } = await import('./db');
    const { sql } = await import('drizzle-orm');
    
    // Get current multi-category assignments
    const result = await db.execute(sql`
      SELECT value FROM app_config WHERE key = 'product_category_assignments'
    `);
    const row = (result as any).rows?.[0];
    let assignments: Record<string, string[]> = {};
    try { assignments = row?.value || {}; } catch { assignments = {}; }
    
    const currentCats = assignments[productFamily] || [];
    
    if (action === 'remove') {
      // Remove from specific category
      assignments[productFamily] = currentCats.filter(c => c !== categoryName);
      if (assignments[productFamily].length === 0) delete assignments[productFamily];
    } else if (categoryName === null) {
      // Remove from all categories
      delete assignments[productFamily];
    } else {
      // Add to category (default)
      if (!currentCats.includes(categoryName)) {
        assignments[productFamily] = [...currentCats, categoryName];
      }
    }
    
    await db.execute(sql`
      INSERT INTO app_config (key, value, updated_at)
      VALUES ('product_category_assignments', ${JSON.stringify(assignments)}::jsonb, NOW())
      ON CONFLICT (key) DO UPDATE SET value = ${JSON.stringify(assignments)}::jsonb, updated_at = NOW()
    `);
    
    // Also update the legacy ecommerce_products.categoria field (first category or null)
    const newCats = assignments[productFamily] || [];
    const primaryCat = newCats.length > 0 ? newCats[0] : null;
    await db.execute(sql`
      UPDATE ecommerce_products 
      SET categoria = ${primaryCat}
      WHERE variant_generic_display_name = ${productFamily}
    `);
    
    invalidateStoreCache();
    res.json({ success: true, productFamily, categories: newCats });
  }));
