  app.post('/api/rutas', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      if (!canManageRutas(user.role)) return res.status(403).json({ message: "Solo supervisores/admin pueden crear rutas" });
      // El front manda vendedorIds[] (multi-asignación). El vendedorId principal (compat) es el primero.
      const vendedorIds: string[] = Array.isArray(req.body?.vendedorIds)
        ? req.body.vendedorIds.filter((v: any) => typeof v === 'string' && v.trim())
        : (req.body?.vendedorId ? [String(req.body.vendedorId)] : []);
      if (vendedorIds.length === 0) return res.status(400).json({ message: "Debe asignar al menos un vendedor" });
      const { insertRutaComercialSchema } = await import('@shared/schema');
      const parsed = insertRutaComercialSchema.safeParse({ ...req.body, vendedorId: vendedorIds[0] });
      if (!parsed.success) return res.status(400).json({ message: "Datos inválidos", errors: parsed.error.issues });
      const ruta = await storage.createRuta({ ...parsed.data, supervisorId: user.id });
      // Resuelve nombres para guardarlos junto a cada asignación (evita un join en cada lectura).
      const catalogo = user.role === 'admin'
        ? await storage.getAllActiveSalespeopleBasic()
        : await storage.getSalespeopleUnderSupervisor(user.id);
      const nombreDe = (id: string) => catalogo.find((v: any) => v.id === id)?.salespersonName ?? null;
      await storage.setRutaVendedores(ruta.id, vendedorIds.map((id) => ({ id, nombre: nombreDe(id) })));
      await logPanelChange(user, {
        section: 'rutas',
        action: 'created',
        entityType: 'ruta',
        entityId: ruta.id,
        title: `Ruta "${ruta.nombre}" creada`,
        segmento: normalizePanelSegmento((ruta as any).segmento),
      });
      res.status(201).json(ruta);
    } catch (e) { console.error("Error creating ruta:", e); res.status(500).json({ message: "Failed to create ruta" }); }
  });

  // Crear ruta "al vuelo" desde el formulario de actividades / pestaña Rutas del cliente.
  // A diferencia de POST /api/rutas (que exige elegir un vendedor y es solo supervisor/admin),
  // acá cualquier usuario comercial autenticado puede registrar una ruta propia: queda a su
  // nombre (vendedorId = supervisorId = user.id) para que la vea al recargar el desplegable,
  // sin importar su rol. Opcionalmente asigna el cliente a la ruta en el mismo paso.
  app.post('/api/rutas/quick', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      const { nombre, clienteId, clienteNombre, segmento } = req.body || {};
      if (!nombre || !String(nombre).trim()) {
        return res.status(400).json({ message: "El nombre de la ruta es requerido" });
      }
      const ruta = await storage.createRuta({
        nombre: String(nombre).trim(),
        vendedorId: user.id,
        supervisorId: user.id,
        segmento: segmento || null,
        estado: 'activa',
      } as any);
      if (clienteId) {
        try {
          await storage.addClienteToRuta(ruta.id, {
            clienteId: String(clienteId),
            clienteNombre: clienteNombre ? String(clienteNombre) : String(clienteId),
          } as any);
        } catch (err) { console.error("Error asignando cliente a ruta rápida:", err); }
      }
      await logPanelChange(user, {
        section: 'rutas',
        action: 'created',
        entityType: 'ruta',
        entityId: ruta.id,
        title: `Ruta "${ruta.nombre}" creada`,
        segmento: normalizePanelSegmento((ruta as any).segmento),
      });
      res.status(201).json(ruta);
    } catch (e) { console.error("Error creating quick ruta:", e); res.status(500).json({ message: "Failed to create ruta" }); }
  });

  app.patch('/api/rutas/:id', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      if (!canManageRutas(user.role)) return res.status(403).json({ message: "No autorizado" });
      const { vendedorIds, ...rest } = req.body || {};
      // Si vienen vendedorIds, reemplaza el set de vendedores y sincroniza el principal (compat).
      if (Array.isArray(vendedorIds)) {
        const ids: string[] = vendedorIds.filter((v: any) => typeof v === 'string' && v.trim());
        if (ids.length === 0) return res.status(400).json({ message: "Debe asignar al menos un vendedor" });
        const catalogo = user.role === 'admin'
          ? await storage.getAllActiveSalespeopleBasic()
          : await storage.getSalespeopleUnderSupervisor(user.id);
        const nombreDe = (id: string) => catalogo.find((v: any) => v.id === id)?.salespersonName ?? null;
        await storage.setRutaVendedores(req.params.id, ids.map((id) => ({ id, nombre: nombreDe(id) })));
        rest.vendedorId = ids[0];
      }
      if (rest.fecha !== undefined && rest.fecha) rest.fecha = new Date(rest.fecha);
      const rutaActualizada = await storage.updateRuta(req.params.id, rest);
      await logPanelChange(user, {
        section: 'rutas',
        action: 'updated',
        entityType: 'ruta',
        entityId: req.params.id,
        title: `Ruta "${(rutaActualizada as any)?.nombre ?? ''}" actualizada`,
        segmento: normalizePanelSegmento((rutaActualizada as any)?.segmento),
      });
      res.json(rutaActualizada);
    } catch (e) { console.error("Error updating ruta:", e); res.status(500).json({ message: "Failed to update ruta" }); }
  });

  // Elimina la ruta completa (clientes + histórico de visitas). Solo administradores:
  // supervisores/encargados y dueños de la ruta pueden gestionarla pero no borrarla.
  app.delete('/api/rutas/:id', requireAuth, async (req: any, res) => {
    try {
      const ruta = await storage.getRutaById(req.params.id);
      if (!ruta) return res.status(404).json({ message: "Ruta no encontrada" });
      if (req.user.role !== 'admin') return res.status(403).json({ message: "Solo los administradores pueden eliminar rutas" });
      await storage.deleteRuta(req.params.id);
      await logPanelChange(req.user, {
        section: 'rutas',
        action: 'deleted',
        entityType: 'ruta',
        entityId: req.params.id,
        title: `Ruta "${(ruta as any).nombre}" eliminada`,
        segmento: normalizePanelSegmento((ruta as any).segmento),
      });
      res.json({ message: "Ruta eliminada" });
    } catch (e) { console.error("Error deleting ruta:", e); res.status(500).json({ message: "Failed to delete ruta" }); }
  });

  // Asignar / quitar cliente de una ruta
  app.post('/api/rutas/:id/clientes', requireAuth, async (req: any, res) => {
    try {
      if (!canManageRutas(req.user.role)) return res.status(403).json({ message: "No autorizado" });
      const { insertRutaClienteSchema } = await import('@shared/schema');
      const parsed = insertRutaClienteSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Datos inválidos", errors: parsed.error.issues });
      const rutaCliente = await storage.addClienteToRuta(req.params.id, parsed.data);
      await logPanelChange(req.user, {
        section: 'rutas',
        action: 'updated',
        entityType: 'ruta',
        entityId: req.params.id,
        title: `Cliente ${parsed.data.clienteNombre ?? parsed.data.clienteId} agregado a una ruta`,
      });
      res.status(201).json(rutaCliente);
    } catch (e) { console.error("Error adding cliente to ruta:", e); res.status(500).json({ message: "Failed" }); }
  });

  // Además de supervisor/admin/encargado, el dueño de la ruta (quien la creó vía /quick)
  // puede quitar clientes de su propia ruta desde la pestaña "Rutas" del cliente.
  app.delete('/api/rutas/:id/clientes/:koen', requireAuth, async (req: any, res) => {
    try {
      const ruta = await storage.getRutaById(req.params.id);
      if (!ruta) return res.status(404).json({ message: "Ruta no encontrada" });
      const isOwner = ruta.vendedorId === req.user.id || ruta.supervisorId === req.user.id;
      if (!canManageRutas(req.user.role) && !isOwner) return res.status(403).json({ message: "No autorizado" });
      await storage.removeClienteFromRuta(req.params.id, req.params.koen);
      res.json({ message: "Cliente removido de la ruta" });
    } catch (e) { console.error("Error removing cliente from ruta:", e); res.status(500).json({ message: "Failed" }); }
  });

  // Marcar la ruta como realizada/pendiente para este cliente (checkbox de la pestaña
  // "Rutas" del cliente). Igual que quitar cliente: manager o dueño de la ruta.
  app.patch('/api/rutas/:id/clientes/:koen/visitado', requireAuth, async (req: any, res) => {
    try {
      const ruta = await storage.getRutaById(req.params.id);
      if (!ruta) return res.status(404).json({ message: "Ruta no encontrada" });
      const isOwner = ruta.vendedorId === req.user.id || ruta.supervisorId === req.user.id;
      if (!canManageRutas(req.user.role) && !isOwner) return res.status(403).json({ message: "No autorizado" });
      const visitado = req.body?.visitado === true || req.body?.visitado === 'true';
      // El cliente puede tener la visita como actividad suelta sin estar formalmente en
      // ruta_clientes; en ese caso no marcamos el estado pero igual guardamos la evidencia.
      let rc: any = null;
      try {
        rc = await storage.setRutaClienteVisitado(req.params.id, req.params.koen, visitado);
      } catch (err) {
        console.warn("Cliente no asignado a la ruta al marcar visitado, se continúa para registrar evidencia:", (err as any)?.message);
      }
      // Al marcar como realizada se puede adjuntar evidencia (foto + geolocalización) que
      // queda registrada en el histórico de visitas del cliente.
      if (visitado) {
        const { imagenUrl, lat, lng, nota, clienteNombre } = req.body || {};
        if (imagenUrl || lat != null || lng != null || (nota && String(nota).trim())) {
          try {
            await storage.addRutaVisita({
              rutaId: req.params.id,
              clienteId: req.params.koen,
              clienteNombre: clienteNombre || rc?.clienteNombre || null,
              fecha: new Date(),
              nota: nota ? String(nota).trim() : null,
              imagenUrl: imagenUrl || null,
              lat: lat != null && lat !== '' ? String(lat) : null,
              lng: lng != null && lng !== '' ? String(lng) : null,
              registradoPor: req.user.id,
              registradoPorNombre: req.user.name || `${req.user.firstName || ''} ${req.user.lastName || ''}`.trim() || req.user.email || null,
            });
          } catch (err) { console.error("Error registrando evidencia de visita:", err); }
        }
      }
      await logPanelChange(req.user, {
        section: 'rutas',
        action: visitado ? 'completed' : 'reopened',
        entityType: 'ruta',
        entityId: req.params.id,
        title: `Visita a ${rc?.clienteNombre ?? req.params.koen} ${visitado ? 'realizada' : 'marcada pendiente'} en ruta "${(ruta as any).nombre}"`,
        segmento: normalizePanelSegmento((ruta as any).segmento),
      });
      res.json(rc ?? { rutaId: req.params.id, clienteId: req.params.koen, visitado });
    } catch (e) { console.error("Error marcando visita de ruta:", e); res.status(500).json({ message: "Failed" }); }
  });

  // Histórico de visitas de un cliente (ruta 4 segmentos → no la captura /api/rutas/:id/...)
  app.get('/api/rutas/visitas/by-cliente/:koen', requireAuth, async (req: any, res) => {
    try { res.json(await storage.getRutaVisitasByCliente(req.params.koen)); }
    catch (e) { console.error("Error fetching visitas:", e); res.status(500).json({ message: "Failed" }); }
  });

  // Registrar una visita (queda en el histórico)
  app.post('/api/rutas/:id/visitas', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      const { clienteId, clienteNombre, fecha, nota } = req.body || {};
      if (!clienteId || !fecha) return res.status(400).json({ message: "clienteId y fecha son requeridos" });
      const visita = await storage.addRutaVisita({
        rutaId: req.params.id,
        clienteId,
        clienteNombre: clienteNombre || null,
        fecha: new Date(fecha),
        nota: nota || null,
        registradoPor: user.id,
        registradoPorNombre: user.name || `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null,
      });
      res.status(201).json(visita);
    } catch (e) { console.error("Error creating visita:", e); res.status(500).json({ message: "Failed" }); }
  });

  // ==================================================================================
  // ACTIVIDADES (subtareas tipadas de un seguimiento de cliente)
  // ==================================================================================
  app.get('/api/tasks/:id/actividades', requireAuth, async (req: any, res) => {
    try { res.json(await storage.getActividadesByTask(req.params.id)); }
    catch (e) { console.error("Error fetching actividades:", e); res.status(500).json({ message: "Failed" }); }
  });

  app.post('/api/tasks/:id/actividades', requireAuth, async (req: any, res) => {
    try {
      const user = req.user;
      const { tipo, descripcion, fecha, responsableId, responsableNombre, rutaId, rutaNombre } = req.body || {};
      if (!tipo) return res.status(400).json({ message: "tipo es requerido" });
      const act = await storage.createActividad({
        taskId: req.params.id,
        tipo,
        descripcion: descripcion || null,
        fecha: fecha ? new Date(fecha) : null,
        estado: 'pendiente',
        responsableId: responsableId || null,
        responsableNombre: responsableNombre || null,
        rutaId: rutaId || null,
        rutaNombre: rutaNombre || null,
        createdBy: user.id,
      });
      // Si la actividad está ligada a una ruta, registrar también la visita en el histórico de rutas.
      if (rutaId && fecha) {
        try {
          const task = await storage.getTask(req.params.id);
          const clienteId = (task as any)?.clienteId;
          if (clienteId) {
            await storage.addRutaVisita({
              rutaId,
              clienteId,
              clienteNombre: (task as any)?.clienteNombre || null,
              fecha: new Date(fecha),
              nota: descripcion || null,
              registradoPor: user.id,
              registradoPorNombre: user.name || `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null,
            });
          }
        } catch (err) { console.error("Error registrando visita de ruta desde actividad:", err); }
      }
      await logPanelChange(user, {
        section: 'seguimiento',
        action: 'created',
        entityType: 'actividad',
        entityId: req.params.id, // se destaca la tarjeta del seguimiento
        title: `Actividad "${tipo}" registrada${descripcion ? `: ${String(descripcion).slice(0, 80)}` : ''}`,
      });
      res.status(201).json(act);
    } catch (e) { console.error("Error creating actividad:", e); res.status(500).json({ message: "Failed" }); }
  });

  app.patch('/api/tasks/actividades/:actId', requireAuth, async (req: any, res) => {
    try {
      const { tipo, descripcion, fecha, estado, responsableId, responsableNombre } = req.body || {};
      const updates: any = {};
      if (tipo !== undefined) updates.tipo = tipo;
      if (descripcion !== undefined) updates.descripcion = descripcion;
      if (fecha !== undefined) updates.fecha = fecha ? new Date(fecha) : null;
      if (estado !== undefined) updates.estado = estado;
      if (responsableId !== undefined) updates.responsableId = responsableId;
      if (responsableNombre !== undefined) updates.responsableNombre = responsableNombre;
      const act = await storage.updateActividad(req.params.actId, updates);
      // Si la actividad es una visita ligada a una ruta, el estado de la tarea manda
      // sobre la ruta para este cliente: completar la tarea marca la ruta como realizada
      // (y volver a pendiente la desmarca).
      if (estado !== undefined && act.rutaId) {
        try {
          const task = await storage.getTask(act.taskId);
          const clienteId = (task as any)?.clienteId;
          if (clienteId) await storage.setRutaClienteVisitado(act.rutaId, clienteId, estado === 'completada');
        } catch (err) { console.error("Error sincronizando ruta desde actividad:", err); }
      }
      await logPanelChange(req.user, {
        section: 'seguimiento',
        action: estado === 'completada' ? 'completed' : 'updated',
        entityType: 'actividad',
        entityId: act.taskId,
        title: `Actividad "${act.tipo}" ${estado === 'completada' ? 'completada' : 'actualizada'}`,
      });
      res.json(act);
    } catch (e) { console.error("Error updating actividad:", e); res.status(500).json({ message: "Failed" }); }
  });

  app.delete('/api/tasks/actividades/:actId', requireAuth, async (req: any, res) => {
    try {
      await storage.deleteActividad(req.params.actId);
      await logPanelChange(req.user, {
        section: 'seguimiento',
        action: 'deleted',
        entityType: 'actividad',
        title: 'Actividad eliminada',
      });
      res.json({ message: "Actividad eliminada" });
    }
    catch (e) { console.error("Error deleting actividad:", e); res.status(500).json({ message: "Failed" }); }
  });

  // ==================================================================================
  // Users endpoint for CRM
  // ==================================================================================

  // Get all users (for dropdowns like salesperson assignment)
  app.get('/api/users', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;

      // Only admin, supervisor, and salesperson can view users list
      if (!['admin', 'supervisor', 'encargado_area', 'salesperson'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const users = await storage.getSalespeopleUsers();
      res.json(users);
    } catch (error) {
      console.error("Error fetching users:", error);
      res.status(500).json({ message: "Failed to fetch users" });
    }
  });

  // List all client users (for eCommerce users management)
  app.get('/api/users/clients', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { salespeopleUsers: spUsersTable, clients: clientsTable, users: usersTable } = await import('@shared/schema');
      const { eq, desc, sql } = await import('drizzle-orm');
      const { db } = await import('./db');
      // 1. Get client users from salespeople_users table (primary source)
      // Use raw SQL to be resilient to missing client_id column (migration may not have run yet)
      let spClientUsersRaw: any[] = [];
      try {
        const spResult = await db.execute(sql`
          SELECT * FROM salespeople_users WHERE role = 'client' ORDER BY created_at DESC
        `);
        spClientUsersRaw = Array.isArray(spResult) ? spResult : (spResult as any).rows || [];
      } catch (e1) {
        console.error('[GET /api/users/clients] Failed to query salespeople_users:', e1);
        spClientUsersRaw = [];
      }
      // Map snake_case columns from raw SQL to camelCase for consistency
      const spClientUsers = (spClientUsersRaw || []).map((r: any) => ({
        id: r.id,
        email: r.email,
        username: r.username,
        salespersonName: r.salesperson_name,
        clientRut: r.client_rut,
        clientId: r.client_id || null,
        publicEmail: r.public_email,
        publicPhone: r.public_phone,
        createdAt: r.created_at,
        role: r.role,
      }));
      
      // 2. Also get client users from users table (legacy/fallback)
      const legacyClientUsers = await db.select().from(usersTable)
        .where(eq(usersTable.role, 'client'))
        .orderBy(desc(usersTable.createdAt));
      
      // 3. Get all clients records to cross-reference — build multiple lookup maps
      // Use raw SQL to avoid crashes from schema columns that may not exist yet
      let allClients: any[] = [];
      try {
        const clientsResult = await db.execute(sql`SELECT * FROM clients`);
        allClients = Array.isArray(clientsResult) ? clientsResult : (clientsResult as any).rows || [];
      } catch (clientsError) {
        // Fallback: select only essential columns if SELECT * fails
        try {
          const clientsResult = await db.execute(sql`
            SELECT id, koen, nokoen, rten, foen, dien, cmen, cpen, crlt, cren, crsd, crto,
                   kofuen, email, user_id, lcen, diprve, fevecren, gien, sien, ruen,
                   pickup_warehouse_id, parent_client_id, branch_label, free_shipping
            FROM clients
          `);
          allClients = Array.isArray(clientsResult) ? clientsResult : (clientsResult as any).rows || [];
        } catch (e2) {
          console.error('[GET /api/users/clients] Failed to query clients table:', e2);
          allClients = [];
        }
      }
      const clientById = new Map(allClients.map((c: any) => [c.id, c]));
      const clientByName = new Map(allClients.filter((c: any) => c.nokoen).map((c: any) => [c.nokoen?.toUpperCase(), c]));
      // Support both snake_case (raw SQL) and camelCase (Drizzle) for user_id
      const clientByUserId = new Map(allClients.filter((c: any) => c.userId || c.user_id).map((c: any) => [c.userId || c.user_id, c]));
      // RUT lookup map (normalized)
      const clientByRut = new Map<string, any>();
      for (const c of allClients) {
        if (c.rten) {
          const normalizedRut = (c.rten as string).replace(/[.\-\s]/g, '').trim().toUpperCase();
          if (normalizedRut) clientByRut.set(normalizedRut, c);
        }
      }
      
      const results: any[] = [];
      const seenIds = new Set<string>();
      // Track users that got auto-reconciled for background update
      const toReconcile: Array<{ userId: string; clientId: string }> = [];
      
      // Process salespeople_users client records
      for (const u of spClientUsers) {
        seenIds.add(u.id);
        
        // Priority-based client matching:
        // 1. Direct FK (client_id) — most reliable
        // 2. Fallback by RUT — reliable
        // 3. Fallback by user_id in clients table
        // 4. Fallback by name match — least reliable
        let clientRecord = u.clientId ? clientById.get(u.clientId) : null;
        
        if (!clientRecord && u.clientRut) {
          const normalizedRut = u.clientRut.replace(/[.\-\s]/g, '').trim().toUpperCase();
          clientRecord = clientByRut.get(normalizedRut) || null;
          // Auto-reconcile: if we found by RUT but user has no client_id, queue for update
          if (clientRecord && !u.clientId) {
            toReconcile.push({ userId: u.id, clientId: clientRecord.id });
          }
        }
        
        if (!clientRecord) {
          clientRecord = clientByUserId.get(u.id) || null;
        }
        
        if (!clientRecord) {
          clientRecord = clientByName.get(u.salespersonName?.toUpperCase()) || null;
          // Also queue name-based matches for reconciliation
          if (clientRecord && !u.clientId) {
            toReconcile.push({ userId: u.id, clientId: clientRecord.id });
          }
        }
        
        results.push({
          id: u.id,
          email: u.email || u.publicEmail || null,
          firstName: u.salespersonName,
          lastName: null,
          role: 'client',
          createdAt: u.createdAt,
          hasCredentials: true,
          username: u.username,
          clientId: clientRecord?.id || null,
          clientCode: clientRecord?.koen || null,
          clientName: u.salespersonName || clientRecord?.nokoen || u.email || 'Sin nombre',
          rut: clientRecord?.rten || u.clientRut || null,
          phone: clientRecord?.foen || u.publicPhone || null,
          address: clientRecord?.dien || null,
          commune: clientRecord?.cmen || clientRecord?.comuna || null,
          assignedSalesperson: clientRecord?.assignedSalespersonUserId || null,
          salesRepCode: clientRecord?.kofuen || null,
          creditLimit: clientRecord?.crlt ? parseFloat(clientRecord.crlt) : null,
          creditAvailable: clientRecord?.cren ? parseFloat(clientRecord.cren) : null,
          creditUsed: clientRecord?.crsd ? parseFloat(clientRecord.crsd) : null,
          paymentCondition: clientRecord?.cpen || null,
          pickupWarehouseId: clientRecord?.pickupWarehouseId || clientRecord?.pickup_warehouse_id || null,
          lcen: clientRecord?.lcen || null,
          parentClientId: clientRecord?.parentClientId || clientRecord?.parent_client_id || null,
          branchLabel: clientRecord?.branchLabel || clientRecord?.branch_label || null,
          freeShipping: !!(clientRecord?.freeShipping ?? clientRecord?.free_shipping),
        });
      }

      // Process legacy users table client records (if not already found)
      for (const u of legacyClientUsers) {
        if (seenIds.has(u.id)) continue;
        const clientRecord = clientByUserId.get(u.id);
        
        results.push({
          id: u.id,
          email: u.email,
          firstName: u.firstName,
          lastName: u.lastName,
          role: 'client',
          createdAt: u.createdAt,
          hasCredentials: true,
          username: u.email,
          clientId: clientRecord?.id || null,
          clientCode: clientRecord?.koen || null,
          clientName: clientRecord?.nokoen || (u.firstName ? `${u.firstName || ''} ${u.lastName || ''}`.trim() : u.email),
          rut: clientRecord?.rten || null,
          phone: clientRecord?.foen || null,
          address: clientRecord?.dien || null,
          commune: clientRecord?.cmen || clientRecord?.comuna || null,
          assignedSalesperson: clientRecord?.assignedSalespersonUserId || null,
          salesRepCode: clientRecord?.kofuen || null,
          creditLimit: clientRecord?.crlt ? parseFloat(clientRecord.crlt) : null,
          creditAvailable: clientRecord?.cren ? parseFloat(clientRecord.cren) : null,
          creditUsed: clientRecord?.crsd ? parseFloat(clientRecord.crsd) : null,
          paymentCondition: clientRecord?.cpen || null,
          pickupWarehouseId: clientRecord?.pickupWarehouseId || clientRecord?.pickup_warehouse_id || null,
          lcen: clientRecord?.lcen || null,
          parentClientId: clientRecord?.parentClientId || clientRecord?.parent_client_id || null,
          branchLabel: clientRecord?.branchLabel || clientRecord?.branch_label || null,
          freeShipping: !!(clientRecord?.freeShipping ?? clientRecord?.free_shipping),
        });
      }

      // Background auto-reconciliation: persist newly discovered links
      if (toReconcile.length > 0) {
        (async () => {
          try {
            for (const { userId, clientId } of toReconcile) {
              await db.update(spUsersTable)
                .set({ clientId: clientId, updatedAt: new Date() })
                .where(eq(spUsersTable.id, userId));
              await db.update(clientsTable)
                .set({ userId: userId })
                .where(eq(clientsTable.id, clientId));
            }
            console.log(`[AUTO-RECONCILE] Linked ${toReconcile.length} users with their client records`);
          } catch (reconcileError) {
            console.warn('[AUTO-RECONCILE] Failed:', reconcileError);
          }
        })();
      }
      // Enrich with real SAP sales metrics from ventas.fact_ventas
      // Wrapped in defensive try/catch — if this fails, we still return results without SAP data
      let finalResults = results;
      try {
        const linkedClientNames = results
          .filter((r: any) => r.clientId && r.clientName)
          .map((r: any) => {
            const cr = clientById.get(r.clientId);
            return cr?.nokoen || r.clientName;
          })
          .filter((n: any) => n && typeof n === 'string' && n.trim().length > 0);

        if (linkedClientNames.length > 0) {
          let salesMetricsMap = new Map<string, any>();
          try {
            const metricsResult = await db.execute(sql`
              WITH client_agg AS (
                SELECT 
                  nokoen,
                  COUNT(*)::int AS total_transactions,
                  COALESCE(SUM(monto), 0)::numeric AS total_sales,
                  MAX(feemdo)::text AS last_transaction_date
                FROM ventas.fact_ventas
                WHERE nokoen IN (${sql.join(linkedClientNames.map((n: string) => sql`${n}`), sql`, `)})
                GROUP BY nokoen
              ),
              latest_doc AS (
                SELECT DISTINCT ON (nokoen)
                  nokoen,
                  nokofu AS salesperson_name
                FROM ventas.fact_ventas
                WHERE nokoen IN (${sql.join(linkedClientNames.map((n: string) => sql`${n}`), sql`, `)})
                ORDER BY nokoen, feemdo DESC, idmaeedo DESC
              )
              SELECT 
                ca.nokoen,
                ca.total_transactions,
                ca.total_sales,
                ca.last_transaction_date,
                ld.salesperson_name
              FROM client_agg ca
              LEFT JOIN latest_doc ld ON ld.nokoen = ca.nokoen
            `);
            const metricsRows = Array.isArray(metricsResult) ? metricsResult : (metricsResult as any).rows || [];
            for (const row of metricsRows as any[]) {
              if (row.nokoen) salesMetricsMap.set(row.nokoen.toUpperCase(), row);
            }
          } catch (metricsError) {
            console.warn('[GET /api/users/clients] Sales metrics query failed:', metricsError);
          }

          // Merge SAP metrics into results
          finalResults = results.map((r: any) => {
            if (!r.clientId) return r;
            const cr = clientById.get(r.clientId);
            const clientName = cr?.nokoen || r.clientName;
            const metrics = clientName ? salesMetricsMap.get(clientName.toUpperCase()) : null;
            return {
              ...r,
              sapTotalSales: metrics ? Number(metrics.total_sales) : null,
              sapTotalTransactions: metrics ? Number(metrics.total_transactions) : null,
              sapLastTransactionDate: metrics?.last_transaction_date || null,
              sapSalespersonName: metrics?.salesperson_name || null,
              creditLimit: cr?.crlt ? parseFloat(cr.crlt) : r.creditLimit,
              creditAvailable: cr?.cren ? parseFloat(cr.cren) : r.creditAvailable,
              creditUsed: cr?.crsd ? parseFloat(cr.crsd) : r.creditUsed,
              paymentCondition: cr?.cpen || r.paymentCondition,
              salesRepCode: cr?.kofuen || r.salesRepCode,
            };
          });
        }
      } catch (enrichError) {
        console.warn('[GET /api/users/clients] SAP enrichment failed, returning base results:', enrichError);
        finalResults = results;
      }

      res.json(finalResults);
    } catch (error) {
      console.error("Error fetching client users:", error);
      res.status(500).json({ message: "Failed to fetch client users" });
    }
  });

  // Get ERP (SAP) order history for a specific linked client (admin/commercial view).
  // Unlike /api/ecommerce/client/erp-orders (session-based, client portal), this is
  // parametrized by the clients.id being viewed and returns real SAP documents:
  //   - FCV (facturas de venta) → already invoiced orders
  //   - NVV (notas de venta) still pending invoicing → eslido open + qty pendiente > 0
  // Matched by fuzzy client name OR client code (fact.endo = clients.koen), mirroring
  // buildClientSalesMatch so this list stays consistent with the SAP totals on the same page.
  app.get('/api/users/clients/:clientId/erp-orders', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { clientId } = req.params;
      const { sql } = await import('drizzle-orm');
      const { db } = await import('./db');

      // Resolve the SAP client record to get its canonical name + code (join keys for fact tables)
      const clientResult = await db.execute(sql`SELECT id, koen, nokoen FROM clients WHERE id = ${clientId} LIMIT 1`);
      const clientRow = (Array.isArray(clientResult) ? clientResult : (clientResult as any).rows || [])[0];
      if (!clientRow || (!clientRow.nokoen && !clientRow.koen)) {
        return res.json({ documents: [], fcvCount: 0, nvvPendingCount: 0 });
      }
      const clientName = (clientRow.nokoen || '') as string;
      const clientCode = clientRow.koen ? String(clientRow.koen).trim() : '';

      // Match SAP documents the same way the rest of the client page does (see
      // buildClientSalesMatch in storage.ts): fuzzy client name OR the reliable
      // client code (fact.endo = clients.koen). An exact nokoen match misses rows
      // whose stored name differs from the ficha (suffixes, encoding, whitespace,
      // case) — which is why the KPIs showed sales but this list came up empty.
      const nameForSearch = clientName.replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
      const nameCond = sql`(nokoen ILIKE ${nameForSearch} OR REPLACE(nokoen, '-', ' ') ILIKE ${nameForSearch} OR nokoen ILIKE ${'%' + nameForSearch + '%'})`;
      const codeCond = sql`TRIM(endo) = ${clientCode}`;
      const clientMatch = nameForSearch && clientCode
        ? sql`(${nameCond} OR ${codeCond})`
        : (nameForSearch ? nameCond : sql`(${codeCond})`);

      // FCV invoices (facturas), aggregated per document
      let invoices: any[] = [];
      try {
        const invResult = await db.execute(sql`
          SELECT
            idmaeedo::text AS doc_id,
            MAX(nudo)::text AS nudo,
            MAX(feemdo)::text AS fecha,
            COALESCE(SUM(monto), 0)::numeric AS total,
            COUNT(*)::int AS items,
            MAX(nokofu) AS vendedor
          FROM ventas.fact_ventas
          WHERE ${clientMatch} AND tido = 'FCV'
          GROUP BY idmaeedo
          ORDER BY MAX(feemdo) DESC
          LIMIT 300
        `);
        const rows = Array.isArray(invResult) ? invResult : (invResult as any).rows || [];
        invoices = rows.map((r: any) => ({
          source: 'sap',
          docType: 'FCV',
          id: `fcv-${r.doc_id}`,
          idmaeedo: Number(r.doc_id) || null,
          orderNumber: r.nudo,
          date: r.fecha,
          items: Number(r.items) || 0,
          total: Number(r.total) || 0,
          status: 'facturado',
          salesperson: r.vendedor || null,
          deliveryDate: null,
        }));
      } catch (e) {
        console.warn('[GET /api/users/clients/:clientId/erp-orders] FCV query failed:', e);
      }

      // NVV (notas de venta) still pending invoicing, aggregated per document
      let nvvPending: any[] = [];
      try {
        const nvvResult = await db.execute(sql`
          SELECT
            idmaeedo::text AS doc_id,
            MAX(nudo) AS nudo,
            MAX(feemdo)::text AS fecha,
            MAX(feer)::text AS fecha_entrega,
            COALESCE(SUM(monto), 0)::numeric AS total,
            COALESCE(SUM(monto_pendiente), 0)::numeric AS total_pendiente,
            COUNT(*)::int AS items,
            MAX(nombre_vendedor) AS vendedor
          FROM nvv.fact_nvv
          WHERE ${clientMatch}
            AND (eslido IS NULL OR TRIM(eslido) = '')
            AND COALESCE(cantidad_pendiente_ud2, 0) > 0
          GROUP BY idmaeedo
          ORDER BY MAX(feemdo) DESC
          LIMIT 300
        `);
        const rows = Array.isArray(nvvResult) ? nvvResult : (nvvResult as any).rows || [];
        nvvPending = rows.map((r: any) => ({
          source: 'sap',
          docType: 'NVV',
          id: `nvv-${r.doc_id}`,
          orderNumber: r.nudo,
          date: r.fecha,
          items: Number(r.items) || 0,
          total: Number(r.total) || 0,
          totalPending: Number(r.total_pendiente) || 0,
          status: 'pendiente_facturacion',
          salesperson: r.vendedor || null,
          deliveryDate: r.fecha_entrega || null,
        }));
      } catch (e) {
        console.warn('[GET /api/users/clients/:clientId/erp-orders] NVV query failed:', e);
      }

      res.json({
        documents: [...nvvPending, ...invoices],
        fcvCount: invoices.length,
        nvvPendingCount: nvvPending.length,
        clientName,
      });
    } catch (error: any) {
      console.error('Error fetching client ERP orders:', error);
      res.status(500).json({ message: 'Error al consultar pedidos ERP', detail: error?.message || 'Unknown error' });
    }
  });

  // Descarga del PDF oficial (representación impresa del DTE) de una factura FCV.
  // El DTE (XML legal + timbre PDF417 como imagen) vive en el SQL Server de Softland
  // (dbo.FMAEDTE). Se lee en vivo por IDMAEEDO y se arma el PDF con Chromium headless.
  app.get('/api/erp/facturas/:idmaeedo/pdf', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }
      const idmaeedo = parseInt(String(req.params.idmaeedo), 10);
      if (!Number.isFinite(idmaeedo) || idmaeedo <= 0) {
        return res.status(400).json({ message: 'idmaeedo inválido' });
      }

      const { getDteByIdmaeedo } = await import('./utils/erp-dte');
      const { parseDte } = await import('./utils/dte-parse');
      const { renderFacturaHtml } = await import('./services/factura-dte-template');
      const { renderHtmlToPdf } = await import('./utils/quote-pdf-renderer');

      const dteRow = await getDteByIdmaeedo(idmaeedo);
      if (!dteRow || !dteRow.xml) {
        return res.status(404).json({ message: 'No se encontró el DTE de esta factura en el ERP' });
      }

      const parsed = parseDte(dteRow.xml);
      const html = renderFacturaHtml(parsed, { timbreBase64: dteRow.pdf417, logoUrl: null });
      // El timbre va embebido (data: URI) → no hay recursos externos que esperar.
      const pdf = await renderHtmlToPdf(html, { waitUntil: 'load' });

      const folio = parsed.folio || dteRow.nudo || String(idmaeedo);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Factura_${folio}.pdf"`);
      res.send(pdf);
    } catch (error: any) {
      console.error('[GET /api/erp/facturas/:idmaeedo/pdf] error:', error);
      res.status(500).json({ message: 'Error al generar el PDF de la factura', detail: error?.message || 'Unknown error' });
    }
  });

  // Factura (FCV) asociada a un pedido del Market. Devuelve { factura: { idmaeedo, nudo, ... } }
  // o { factura: null } si no hay una coincidencia segura. El detalle del pedido usa el idmaeedo
  // para mostrar el botón "Descargar factura" contra /api/erp/facturas/:idmaeedo/pdf (mismo PDF
  // oficial que la ficha del cliente). El vínculo se infiere por RUT + monto + fecha (ver
  // findFcvForOrder) porque el espejo aún no trae el link exacto pedido→factura.
  app.get('/api/ecommerce/orders/:id/factura', requireCommercialAccess, asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;
      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado' });
      }
      const result = await db.select().from(ecommerceOrders).where(eq(ecommerceOrders.id, req.params.id));
      const order = result[0];
      if (!order) return res.status(404).json({ message: 'Pedido no encontrado' });

      const { findFcvForOrder } = await import('./utils/erp-match');
      const factura = await findFcvForOrder({
        id: order.id,
        clientId: order.clientId,
        subtotal: order.subtotal as any,
        total: order.total as any,
        createdAt: order.createdAt as any,
        ingresadoAt: order.ingresadoAt as any,
      });
      res.json({ factura });
    } catch (error: any) {
      console.error('[GET /api/ecommerce/orders/:id/factura] error:', error);
      // No es un error fatal para la UI: degradamos a "sin factura" para no romper el detalle.
      res.json({ factura: null });
    }
  }));

  // Global "Pedidos ERP" — unified NVV (pendientes de facturación) + FCV (facturadas) across ALL
  // clients, last 90 days. The ERP splits a document once it passes the 30-line cap, so a 35-item
  // order shows up as e.g. NVV 30 + NVV 5. We re-group those back into one logical pedido when they
  // share docType + client + date + salesperson AND at least one of them hit the cap (overflow
  // evidence) — that avoids fusing two genuinely separate same-day orders. Document shape mirrors
  // the per-client /api/users/clients/:clientId/erp-orders so the UI can reuse the same look.
  app.get('/api/ecommerce/erp-orders', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      const { sql } = await import('drizzle-orm');
      const { db } = await import('./db');

      const ITEM_CAP = 30; // ERP overflows a document into a new one once it exceeds 30 lines

      // Salespeople only see documents under their own ERP vendor name; commercial/admin roles see all.
      const salesName = (user.salespersonName || `${user.firstName || ''} ${user.lastName || ''}`.trim());
      const isSales = user.role === 'salesperson';
      const fcvVendorCond = isSales ? (salesName ? sql`AND nokofu ILIKE ${salesName}` : sql`AND 1=0`) : sql``;
      const nvvVendorCond = isSales ? (salesName ? sql`AND nombre_vendedor ILIKE ${salesName}` : sql`AND 1=0`) : sql``;
      const gdvVendorCond = isSales ? (salesName ? sql`AND nokofu ILIKE ${salesName}` : sql`AND 1=0`) : sql``;

      // FCV (facturas), one row per document
      let fcvDocs: any[] = [];
      try {
        const r = await db.execute(sql`
          SELECT
            idmaeedo::text AS doc_id,
            MAX(nudo)::text AS nudo,
            MAX(feemdo)::text AS fecha,
            MAX(nokoen) AS cliente,
            MAX(endo) AS cliente_codigo,
            COALESCE(SUM(monto), 0)::numeric AS total,
            COUNT(*)::int AS items,
            MAX(nokofu) AS vendedor
          FROM ventas.fact_ventas
          WHERE tido = 'FCV'
            AND feemdo >= (CURRENT_DATE - INTERVAL '90 days')
            ${fcvVendorCond}
          GROUP BY idmaeedo
          ORDER BY MAX(feemdo) DESC
          LIMIT 4000
        `);
        const rows = Array.isArray(r) ? r : (r as any).rows || [];
        fcvDocs = rows.map((x: any) => ({
          docType: 'FCV',
          docId: x.doc_id,
          orderNumber: x.nudo,
          date: x.fecha,
          deliveryDate: null,
          clientName: (x.cliente || 'Sin nombre').trim(),
          clientCode: x.cliente_codigo ? String(x.cliente_codigo).trim() : '',
          total: Number(x.total) || 0,
          totalPending: 0,
          items: Number(x.items) || 0,
          salesperson: x.vendedor || null,
        }));
      } catch (e) {
        console.warn('[GET /api/ecommerce/erp-orders] FCV query failed:', e);
      }

      // NVV (notas de venta) still pending invoicing, one row per document
      let nvvDocs: any[] = [];
      try {
        const r = await db.execute(sql`
          SELECT
            idmaeedo::text AS doc_id,
            MAX(nudo)::text AS nudo,
            MAX(feemdo)::text AS fecha,
            MAX(feer)::text AS fecha_entrega,
            MAX(nokoen) AS cliente,
            MAX(endo) AS cliente_codigo,
            COALESCE(SUM(monto), 0)::numeric AS total,
            COALESCE(SUM(monto_pendiente), 0)::numeric AS total_pendiente,
            COUNT(*)::int AS items,
            MAX(nombre_vendedor) AS vendedor
          FROM nvv.fact_nvv
          WHERE (eslido IS NULL OR TRIM(eslido) = '')
            AND COALESCE(cantidad_pendiente_ud2, 0) > 0
            AND feemdo >= (CURRENT_DATE - INTERVAL '90 days')
            ${nvvVendorCond}
          GROUP BY idmaeedo
          ORDER BY MAX(feemdo) DESC
          LIMIT 4000
        `);
        const rows = Array.isArray(r) ? r : (r as any).rows || [];
        nvvDocs = rows.map((x: any) => ({
          docType: 'NVV',
          docId: x.doc_id,
          orderNumber: x.nudo,
          date: x.fecha,
          deliveryDate: x.fecha_entrega || null,
          clientName: (x.cliente || 'Sin nombre').trim(),
          clientCode: x.cliente_codigo ? String(x.cliente_codigo).trim() : '',
          total: Number(x.total) || 0,
          totalPending: Number(x.total_pendiente) || 0,
          items: Number(x.items) || 0,
          salesperson: x.vendedor || null,
        }));
      } catch (e) {
        console.warn('[GET /api/ecommerce/erp-orders] NVV query failed:', e);
      }

      // GDV (guías de despacho) abiertas — ya despachadas, pendientes de facturación.
      // Cuando la GDV se factura, esdo='C' → la cuenta queda en FCV, así evitamos duplicar fila.
      let gdvDocs: any[] = [];
      try {
        const r = await db.execute(sql`
          SELECT
            idmaeedo::text AS doc_id,
            MAX(nudo)::text AS nudo,
            MAX(feemdo)::text AS fecha,
            MAX(nokoen) AS cliente,
            MAX(endo) AS cliente_codigo,
            COALESCE(SUM(monto), 0)::numeric AS total,
            COUNT(*)::int AS items,
            MAX(nokofu) AS vendedor
          FROM gdv.fact_gdv
          WHERE (esdo IS NULL OR TRIM(esdo) = '')
            AND feemdo >= (CURRENT_DATE - INTERVAL '90 days')
            ${gdvVendorCond}
          GROUP BY idmaeedo
          ORDER BY MAX(feemdo) DESC
          LIMIT 4000
        `);
        const rows = Array.isArray(r) ? r : (r as any).rows || [];
        gdvDocs = rows.map((x: any) => ({
          docType: 'GDV',
          docId: x.doc_id,
          orderNumber: x.nudo,
          date: x.fecha,
          deliveryDate: null,
          clientName: (x.cliente || 'Sin nombre').trim(),
          clientCode: x.cliente_codigo ? String(x.cliente_codigo).trim() : '',
          total: Number(x.total) || 0,
          totalPending: 0,
          items: Number(x.items) || 0,
          salesperson: x.vendedor || null,
        }));
      } catch (e) {
        console.warn('[GET /api/ecommerce/erp-orders] GDV query failed:', e);
      }

      // Pedidos originados en el Market (tienda) — el ingreso al ERP setea erp_idmaeedo,
      // así marcamos el documento ERP correspondiente como fromMarket para la UI.
      let marketIds = new Set<string>();
      try {
        const r = await db.execute(sql`
          SELECT DISTINCT erp_idmaeedo::text AS idmaeedo
          FROM ecommerce_orders
          WHERE erp_idmaeedo IS NOT NULL
        `);
        const rows = Array.isArray(r) ? r : (r as any).rows || [];
        marketIds = new Set(rows.map((x: any) => String(x.idmaeedo)).filter(Boolean));
      } catch (e) {
        console.warn('[GET /api/ecommerce/erp-orders] Market link query failed:', e);
      }

      const tagMarket = (d: any) => { d.fromMarket = marketIds.has(String(d.docId)); return d; };
      for (const d of nvvDocs) tagMarket(d);
      for (const d of gdvDocs) tagMarket(d);
      for (const d of fcvDocs) tagMarket(d);

      // Re-group split documents into one logical pedido.
      const norm = (s: string | null | undefined) => (s || '').trim().toUpperCase().replace(/\s+/g, ' ');
      const dayOf = (d: string | null) => (d || '').slice(0, 10);
      const buckets = new Map<string, any[]>();
      for (const d of [...nvvDocs, ...gdvDocs, ...fcvDocs]) {
        const key = `${d.docType}|${norm(d.clientCode) || norm(d.clientName)}|${dayOf(d.date)}|${norm(d.salesperson)}`;
        const arr = buckets.get(key);
        if (arr) arr.push(d); else buckets.set(key, [d]);
      }

      const makeOrder = (docs: any[]) => {
        const head = docs[0];
        return {
          id: `erp-${head.docType.toLowerCase()}-${docs.map((x) => x.docId).join('-')}`,
          source: 'sap',
          docType: head.docType,
          status: head.docType === 'FCV'
            ? 'facturado'
            : head.docType === 'GDV'
              ? 'despachada'
              : 'pendiente_facturacion',
          clientName: head.clientName,
          clientCode: head.clientCode,
          salesperson: head.salesperson,
          date: head.date,
          deliveryDate: head.deliveryDate || null,
          total: docs.reduce((s, x) => s + (x.total || 0), 0),
          totalPending: docs.reduce((s, x) => s + (x.totalPending || 0), 0),
          items: docs.reduce((s, x) => s + (x.items || 0), 0),
          isGrouped: docs.length > 1,
          fromMarket: docs.some((x) => x.fromMarket),
          orderNumbers: docs.map((x) => x.orderNumber).filter(Boolean),
          documents: docs.map((x) => ({
            docId: x.docId,
            orderNumber: x.orderNumber,
            items: x.items,
            total: x.total,
            totalPending: x.totalPending || 0,
            date: x.date,
            deliveryDate: x.deliveryDate || null,
          })),
        };
      };

      const orders: any[] = [];
      for (const docs of Array.from(buckets.values())) {
        if (docs.length === 1) {
          orders.push(makeOrder(docs));
        } else if (docs.some((d: any) => (d.items || 0) >= ITEM_CAP)) {
          // Overflow evidence → treat as one split pedido (ordered by document number for the breakdown)
          docs.sort((a: any, b: any) => (Number(a.orderNumber) || 0) - (Number(b.orderNumber) || 0));
          orders.push(makeOrder(docs));
        } else {
          // No cap evidence → keep them as separate same-day orders
          for (const d of docs) orders.push(makeOrder([d]));
        }
      }

      orders.sort((a, b) => dayOf(b.date).localeCompare(dayOf(a.date)));

      res.json({
        orders,
        count: orders.length,
        nvvCount: orders.filter((o) => o.docType === 'NVV').length,
        gdvCount: orders.filter((o) => o.docType === 'GDV').length,
        fcvCount: orders.filter((o) => o.docType === 'FCV').length,
      });
    } catch (error: any) {
      console.error('Error fetching global ERP orders:', error);
      res.status(500).json({ message: 'Error al consultar pedidos ERP', detail: error?.message || 'Unknown error' });
    }
  });

  // Detalle de un pedido ERP: líneas de producto (espejo del ERP) + estado de logística (TMS).
  // Query: docType=NVV|FCV & ids=idmaeedo[,idmaeedo...] (varios cuando el pedido viene splitteado).
  app.get('/api/ecommerce/erp-orders/detail', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      const { sql } = await import('drizzle-orm');
      const { db } = await import('./db');

      const rawDocType = String(req.query.docType || '').toUpperCase();
      const docType: 'FCV' | 'NVV' | 'GDV' =
        rawDocType === 'FCV' ? 'FCV' : rawDocType === 'GDV' ? 'GDV' : 'NVV';
      const ids = String(req.query.ids || '')
        .split(',')
        .map((s) => s.trim())
        .filter((s) => /^\d+$/.test(s))
        .slice(0, 50);

      if (ids.length === 0) {
        return res.json({ items: [], logistica: [], tmsConfigured: isTmsConfigured() });
      }

      // Vendedores solo ven sus propios documentos (mismo scoping que el listado).
      const salesName = (user.salespersonName || `${user.firstName || ''} ${user.lastName || ''}`.trim());
      const isSales = user.role === 'salesperson';
      const inClause = sql.join(ids.map((id) => sql`${id}`), sql`, `);

      let items: any[] = [];
      try {
        if (docType === 'FCV') {
          const vendorCond = isSales ? (salesName ? sql`AND nokofu ILIKE ${salesName}` : sql`AND 1=0`) : sql``;
          const r = await db.execute(sql`
            SELECT
              idmaeedo::text AS doc_id,
              nudo::text AS nudo,
              koprct AS codigo,
              nokoprct AS nombre,
              COALESCE(caprco2, 0)::numeric AS cantidad,
              ud02pr AS unidad,
              COALESCE(ppprne, 0)::numeric AS precio,
              COALESCE(monto, 0)::numeric AS total
            FROM ventas.fact_ventas
            WHERE idmaeedo::text IN (${inClause})
              ${vendorCond}
            ORDER BY idmaeedo, idmaeddo
          `);
          const rows = Array.isArray(r) ? r : (r as any).rows || [];
          items = rows.map((x: any) => ({
            docId: x.doc_id,
            orderNumber: x.nudo,
            code: x.codigo ? String(x.codigo).trim() : '',
            name: (x.nombre || '').trim() || (x.codigo ? String(x.codigo).trim() : 'Producto'),
            quantity: Number(x.cantidad) || 0,
            unit: x.unidad ? String(x.unidad).trim() : null,
            unitPrice: Number(x.precio) || 0,
            total: Number(x.total) || 0,
            pending: null,
          }));
        } else if (docType === 'NVV') {
          const vendorCond = isSales ? (salesName ? sql`AND nombre_vendedor ILIKE ${salesName}` : sql`AND 1=0`) : sql``;
          const r = await db.execute(sql`
            SELECT
              idmaeedo::text AS doc_id,
              nudo::text AS nudo,
              koprct AS codigo,
              nokopr AS nombre,
              COALESCE(caprco2, 0)::numeric AS cantidad,
              ud02pr AS unidad,
              COALESCE(ppprne, 0)::numeric AS precio,
              COALESCE(monto, 0)::numeric AS total,
              COALESCE(cantidad_pendiente_ud2, 0)::numeric AS pendiente
            FROM nvv.fact_nvv
            WHERE idmaeedo::text IN (${inClause})
              ${vendorCond}
            ORDER BY idmaeedo, idmaeddo
          `);
          const rows = Array.isArray(r) ? r : (r as any).rows || [];
          items = rows.map((x: any) => ({
            docId: x.doc_id,
            orderNumber: x.nudo,
            code: x.codigo ? String(x.codigo).trim() : '',
            name: (x.nombre || '').trim() || (x.codigo ? String(x.codigo).trim() : 'Producto'),
            quantity: Number(x.cantidad) || 0,
            unit: x.unidad ? String(x.unidad).trim() : null,
            unitPrice: Number(x.precio) || 0,
            total: Number(x.total) || 0,
            pending: Number(x.pendiente) || 0,
          }));
        } else {
          // GDV: guía de despacho. Ya despachada; no hay "pendiente" como en NVV.
          const vendorCond = isSales ? (salesName ? sql`AND nokofu ILIKE ${salesName}` : sql`AND 1=0`) : sql``;
          const r = await db.execute(sql`
            SELECT
              idmaeedo::text AS doc_id,
              nudo::text AS nudo,
              koprct AS codigo,
              nokoprct AS nombre,
              COALESCE(caprco2, 0)::numeric AS cantidad,
              ud02pr AS unidad,
              COALESCE(ppprne, 0)::numeric AS precio,
              COALESCE(monto, 0)::numeric AS total
            FROM gdv.fact_gdv
            WHERE idmaeedo::text IN (${inClause})
              ${vendorCond}
            ORDER BY idmaeedo, idmaeddo
          `);
          const rows = Array.isArray(r) ? r : (r as any).rows || [];
          items = rows.map((x: any) => ({
            docId: x.doc_id,
            orderNumber: x.nudo,
            code: x.codigo ? String(x.codigo).trim() : '',
            name: (x.nombre || '').trim() || (x.codigo ? String(x.codigo).trim() : 'Producto'),
            quantity: Number(x.cantidad) || 0,
            unit: x.unidad ? String(x.unidad).trim() : null,
            unitPrice: Number(x.precio) || 0,
            total: Number(x.total) || 0,
            pending: null,
          }));
        }
      } catch (e) {
        console.warn('[GET /api/ecommerce/erp-orders/detail] line items query failed:', e);
      }

      // Estado de logística por documento (TMS, consultado por idmaeedo). Degrada a null si el TMS no responde.
      const tmsConfigured = isTmsConfigured();
      let logistica: any[] = [];
      if (tmsConfigured) {
        logistica = await Promise.all(
          ids.map(async (id) => ({ docId: id, estado: await fetchTmsShipping(id) })),
        );
      }

      res.json({ items, logistica, tmsConfigured });
    } catch (error: any) {
      console.error('Error fetching ERP order detail:', error);
      res.status(500).json({ message: 'Error al consultar el detalle del pedido', detail: error?.message || 'Unknown error' });
    }
  });

  // Search clients (for CRM lead creation from existing clients)
  app.get('/api/users/clients/search', requireCommercialAccess, async (req: any, res) => {
    try {
      const user = req.user;
      const { q } = req.query;

      // Only admin, supervisor, and salesperson can view client list
      if (!['admin', 'supervisor', 'encargado_area', 'salesperson'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      // Require at least 2 characters for search
      if (!q || typeof q !== 'string' || q.trim().length < 2) {
        return res.json([]);
      }

      // Search clients directly from fact_ventas (data warehouse) to ensure we get real recurring clients
      const searchTerm = q.trim().toLowerCase();
      const clientsFromSales = await db
        .selectDistinct({
          id: factVentas.koen,
          nokoen: factVentas.nokoen,
          koen: factVentas.koen,
          rten: factVentas.gien,
          gien: factVentas.gien,
          dien: sql<string | null>`NULL`.as('dien'),
          foen: sql<string | null>`NULL`.as('foen'),
          email: sql<string | null>`NULL`.as('email'),
        })
        .from(factVentas)
        .where(
          or(
            sql`LOWER(${factVentas.nokoen}) LIKE ${`%${searchTerm}%`}`,
            sql`LOWER(${factVentas.koen}) LIKE ${`%${searchTerm}%`}`
          )
        )
        .orderBy(desc(factVentas.nokoen))
        .limit(100);

      res.json(clientsFromSales);
    } catch (error) {
      console.error("Error searching clients:", error);
      res.status(500).json({ message: "Failed to search clients" });
    }
  });

  // Update client commercial info
  app.patch('/api/users/clients/:id/commercial-info', requireCommercialAccess, async (req: any, res) => {
    try {
      const { id } = req.params;
      const { cpen, dccr, pickupWarehouseId, crlt, cren, crsd, kofuen, lcen: rawLcen, freeShipping } = req.body;
      // lcen handling: undefined = not sent (preserve existing), null = explicit reset,
      // empty string = treat as null, valid string ('LP01','LP02') = set
      const lcen = rawLcen === undefined ? undefined
        : (rawLcen && typeof rawLcen === 'string' && rawLcen.trim() !== '') ? rawLcen.trim()
        : null;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      // pg `numeric` columns expect strings via drizzle. Accept number|string|null
      // from the client and coerce to the wire format — no upper bound enforced
      // here; the column is numeric(15,2) which already accommodates any realistic
      // credit amount.
      const toNumericString = (v: unknown): string | null | undefined => {
        if (v === undefined) return undefined;
        if (v === null || v === '') return null;
        if (typeof v === 'number') {
          if (!Number.isFinite(v)) return null;
          return String(v);
        }
        if (typeof v === 'string') {
          const trimmed = v.trim();
          return trimmed === '' ? null : trimmed;
        }
        return null;
      };

      const { clients } = await import('@shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');

      const existingClient = await db.select().from(clients).where(eq(clients.id, id)).limit(1);
      if (existingClient.length === 0) {
        return res.status(404).json({ message: "Cliente no encontrado" });
      }

      const dccrNorm = toNumericString(dccr);
      const crltNorm = toNumericString(crlt);
      const crenNorm = toNumericString(cren);
      const crsdNorm = toNumericString(crsd);

      await db.update(clients)
        .set({
          cpen: cpen !== undefined ? cpen : existingClient[0].cpen,
          dccr: dccrNorm !== undefined ? dccrNorm : existingClient[0].dccr,
          pickupWarehouseId: pickupWarehouseId !== undefined ? pickupWarehouseId : existingClient[0].pickupWarehouseId,
          crlt: crltNorm !== undefined ? crltNorm : existingClient[0].crlt,
          cren: crenNorm !== undefined ? crenNorm : existingClient[0].cren,
          crsd: crsdNorm !== undefined ? crsdNorm : existingClient[0].crsd,
          kofuen: kofuen !== undefined ? kofuen : existingClient[0].kofuen,
          lcen: lcen !== undefined ? lcen : existingClient[0].lcen,
          freeShipping: freeShipping !== undefined ? !!freeShipping : existingClient[0].freeShipping,
          updatedAt: new Date(),
        })
        .where(eq(clients.id, id));

      res.json({ success: true, message: "Información comercial actualizada" });
    } catch (error: any) {
      console.error("Error updating commercial info:", error);
      res.status(500).json({
        message: "Error al actualizar información comercial",
        detail: error?.message || String(error),
      });
    }
  });

  // Update client contact info (email, phone, address). :id is the user account id
  // (salespeople_users.id or legacy users.id) — the same id the eCommerce users list
  // keys each row by. Email lives on the user account; phone/address live on the SAP
  // client record (clients.foen / clients.dien), with phone mirrored to public_phone.
  app.patch('/api/users/clients/:id/contact-info', requireCommercialAccess, async (req: any, res) => {
    try {
      const { id } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const rawEmail = typeof req.body?.email === 'string' ? req.body.email.trim() : '';
      if (!rawEmail) {
        return res.status(400).json({ message: "El correo es obligatorio" });
      }
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(rawEmail)) {
        return res.status(400).json({ message: "El correo no tiene un formato válido" });
      }

      // undefined = field not sent (leave as is); '' = explicit clear (null); else trimmed value
      const normStr = (v: unknown): string | null | undefined => {
        if (v === undefined) return undefined;
        if (typeof v !== 'string') return null;
        const t = v.trim();
        return t === '' ? null : t;
      };
      const phone = normStr(req.body?.phone);
      const address = normStr(req.body?.address);

      const { salespeopleUsers, users, clients } = await import('@shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');

      // The email shown in the eCommerce users list comes from salespeople_users.email
      // (with a fallback to users.email for legacy accounts), so update there first.
      // Phone is mirrored to public_phone so unlinked accounts keep a phone too.
      const spUpdated = await db.update(salespeopleUsers)
        .set({
          email: rawEmail,
          ...(phone !== undefined ? { publicPhone: phone } : {}),
          updatedAt: new Date(),
        })
        .where(eq(salespeopleUsers.id, id))
        .returning({ id: salespeopleUsers.id, clientId: salespeopleUsers.clientId });

      let matched = spUpdated.length > 0;
      let linkedClientId: string | null = spUpdated[0]?.clientId || null;

      if (!matched) {
        const uUpdated = await db.update(users)
          .set({ email: rawEmail, updatedAt: new Date() })
          .where(eq(users.id, id))
          .returning({ id: users.id });
        matched = uUpdated.length > 0;
      }

      if (!matched) {
        return res.status(404).json({ message: "Usuario no encontrado" });
      }

      // Resolve the linked SAP client record. Prefer the FK on salespeople_users;
      // fall back to the back-link clients.user_id (covers legacy accounts).
      if (!linkedClientId) {
        const [byUser] = await db.select({ id: clients.id }).from(clients)
          .where(eq(clients.userId, id)).limit(1);
        linkedClientId = byUser?.id || null;
      }

      // Address can only be stored on a client record. Guard against silent data loss
      // when the user is not linked (the frontend create-and-links before saving these).
      if (!linkedClientId && address) {
        return res.status(409).json({
          message: "Vincula o crea una ficha de cliente para guardar la dirección.",
        });
      }

      // Update the client record: email (kept in sync), phone (foen) and address (dien).
      if (linkedClientId) {
        await db.update(clients)
          .set({
            email: rawEmail,
            ...(phone !== undefined ? { foen: phone } : {}),
            ...(address !== undefined ? { dien: address } : {}),
            updatedAt: new Date(),
          })
          .where(eq(clients.id, linkedClientId));
      }

      res.json({ success: true, email: rawEmail, phone: phone ?? null, address: address ?? null, clientId: linkedClientId });
    } catch (error: any) {
      // Unique violation on salespeople_users.email / users.email
      if (error?.code === '23505' || /duplicate key|unique/i.test(error?.message || '')) {
        return res.status(409).json({ message: "Ese correo ya está en uso por otro usuario" });
      }
      console.error("Error updating contact info:", error);
      res.status(500).json({
        message: "Error al actualizar el correo",
        detail: error?.message || String(error),
      });
    }
  });

  // Link an eCommerce user to an existing SAP client record
  app.post('/api/users/clients/:userId/link-client', requireCommercialAccess, async (req: any, res) => {
    try {
      const { userId } = req.params;
      const { clientId } = req.body;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      if (!clientId) {
        return res.status(400).json({ message: "clientId es requerido" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable } = await import('@shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Verify user exists and is a client
      const [spUser] = await dbInstance.select().from(spTable).where(eq(spTable.id, userId)).limit(1);
      if (!spUser || spUser.role !== 'client') {
        return res.status(404).json({ message: "Usuario cliente no encontrado" });
      }

      // Verify client exists
      const [clientRecord] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, clientId)).limit(1);
      if (!clientRecord) {
        return res.status(404).json({ message: "Ficha de cliente no encontrada" });
      }

      // Update salespeople_users.client_id
      await dbInstance.update(spTable)
        .set({ clientId: clientId, updatedAt: new Date() })
        .where(eq(spTable.id, userId));

      // Backfill clients.user_id
      await dbInstance.update(clientsTable)
        .set({ userId: userId })
        .where(eq(clientsTable.id, clientId));

      console.log(`[LINK] User ${userId} linked to client ${clientId} by ${user.id}`);
      res.json({ success: true, message: "Usuario vinculado con ficha de cliente exitosamente" });
    } catch (error) {
      console.error("Error linking client:", error);
      res.status(500).json({ message: "Error al vincular cliente" });
    }
  });

  // Create a minimal client record and link to eCommerce user
  app.post('/api/users/clients/:userId/create-and-link', requireCommercialAccess, async (req: any, res) => {
    try {
      const { userId } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable } = await import('@shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Verify user exists and is a client
      const [spUser] = await dbInstance.select().from(spTable).where(eq(spTable.id, userId)).limit(1);
      if (!spUser || spUser.role !== 'client') {
        return res.status(404).json({ message: "Usuario cliente no encontrado" });
      }

      // Check if already linked
      if (spUser.clientId) {
        return res.status(400).json({ message: "Este usuario ya está vinculado con una ficha de cliente" });
      }

      // Create minimal client record
      const [newClient] = await dbInstance.insert(clientsTable).values({
        nokoen: spUser.salespersonName,
        rten: spUser.clientRut || null,
        email: spUser.email || spUser.publicEmail || null,
        foen: spUser.publicPhone || null,
        userId: userId,
      }).returning();

      // Link the user to the new client record
      await dbInstance.update(spTable)
        .set({ clientId: newClient.id, updatedAt: new Date() })
        .where(eq(spTable.id, userId));

      console.log(`[CREATE-LINK] Created client record ${newClient.id} and linked to user ${userId}`);
      res.json({ success: true, message: "Ficha de cliente creada y vinculada", client: newClient });
    } catch (error: any) {
      console.error("Error creating and linking client:", error);
      if (error.code === '23505') {
        return res.status(409).json({ message: "Ya existe un cliente con estos datos" });
      }
      res.status(500).json({ message: "Error al crear ficha de cliente" });
    }
  });

  // Activate Panorámica Market access for an existing client ficha (ficha-first).
  // Atomically creates the ecommerce user (role=client) and links it to the ficha.
  // Idempotent: if the ficha already has an ecommerce user (by id or RUT), just
  // ensures the link. Credentials follow the existing convention (username/password
  // derived from the RUT) unless an email/password is supplied in the body.
  app.post('/api/clients/:id/activate-market', requireCommercialAccess, async (req: any, res) => {
    try {
      const { id } = req.params;
      const user = req.user;
      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable } = await import('@shared/schema');
      const { eq, sql } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      const [ficha] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, id)).limit(1);
      if (!ficha) {
        return res.status(404).json({ message: "Ficha de cliente no encontrada" });
      }

      const normalizeRut = (v?: string | null) => (v || '').replace(/[.\-\s]/g, '').toUpperCase();
      const fichaRut = normalizeRut(ficha.rten);

      // Idempotent: reuse an existing ecommerce user for this ficha (by id or RUT).
      const existing = await dbInstance.select().from(spTable).where(sql`
        ${spTable.role} = 'client' AND (
          ${spTable.clientId} = ${id}
          ${fichaRut ? sql`OR REPLACE(REPLACE(REPLACE(UPPER(${spTable.clientRut}), '.', ''), '-', ''), ' ', '') = ${fichaRut}` : sql``}
        )
      `).limit(1);

      if (existing.length > 0) {
        const ex = existing[0];
        if (!ex.clientId) {
          await dbInstance.update(spTable).set({ clientId: id, updatedAt: new Date() }).where(eq(spTable.id, ex.id));
        }
        await dbInstance.update(clientsTable).set({ userId: ex.id }).where(eq(clientsTable.id, id));
        return res.json({ success: true, created: false, ecommerceUserId: ex.id, username: ex.username, loginEmail: ex.email, tempPassword: null, message: "El cliente ya tenía acceso a Panorámica Market; vínculo asegurado." });
      }

      // Credentials convention: username = RUT, password = RUT (fallback to código).
      const loginKey = (req.body?.username || ficha.rten || ficha.koen || `cli-${String(id).slice(0, 8)}`).toString().trim();
      const rawPassword = (req.body?.password || loginKey).toString();
      const email = req.body?.email || ficha.email || ficha.emailcomer || null;

      const bcryptjs: any = await import('bcryptjs');
      const hashedPassword = await bcryptjs.hash(rawPassword, 12);

      const baseValues = {
        username: loginKey,
        email,
        password: hashedPassword,
        role: 'client',
        clientId: id,
        clientRut: ficha.rten || null,
        publicPhone: ficha.foen || null,
        publicEmail: email,
        isActive: true,
      };

      let newUser: any;
      try {
        [newUser] = await dbInstance.insert(spTable).values({ ...baseValues, salespersonName: ficha.nokoen }).returning();
      } catch (insertError: any) {
        if (insertError.code === '23505' || String(insertError.message || '').includes('unique')) {
          [newUser] = await dbInstance.insert(spTable).values({
            ...baseValues,
            salespersonName: `${ficha.nokoen} (${ficha.rten || ficha.koen || id})`,
            username: `${loginKey}-${String(id).slice(0, 6)}`,
          }).returning();
        } else {
          throw insertError;
        }
      }

      await dbInstance.update(clientsTable).set({ userId: newUser.id }).where(eq(clientsTable.id, id));

      console.log(`[ACTIVATE-MARKET] Client ficha ${id} activated → user ${newUser.id} by ${user.id}`);
      res.json({ success: true, created: true, ecommerceUserId: newUser.id, username: newUser.username, loginEmail: newUser.email, tempPassword: rawPassword, message: "Acceso a Panorámica Market activado." });
    } catch (error: any) {
      console.error("Error activating market access:", error);
      if (error.code === '23505') {
        return res.status(409).json({ message: "Ya existe un usuario con estos datos" });
      }
      res.status(500).json({ message: "Error al activar acceso a Panorámica Market" });
    }
  });

  // Create a new branch (sucursal) for an existing parent client
  app.post('/api/users/clients/:userId/create-branch', requireCommercialAccess, async (req: any, res) => {
    try {
      const { userId } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { branchLabel, username, email, password, salesRepCode, pickupWarehouseId, creditLimit, paymentCondition, lcen, existingUserId, existingUserIds, address, discountPercent } = req.body;

      if (!branchLabel) {
        return res.status(400).json({ message: "branchLabel es requerido" });
      }

      const userIdsToLink = existingUserIds && Array.isArray(existingUserIds) && existingUserIds.length > 0
        ? existingUserIds
        : (existingUserId ? [existingUserId] : []);

      // Validate: either existing users OR (username + password) must be provided
      if (userIdsToLink.length === 0 && (!username || !password)) {
        return res.status(400).json({ message: "Debe proporcionar un usuario existente o crear uno nuevo (username y password requeridos)" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable } = await import('@shared/schema');
      const { eq, inArray } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      //... rest of the file setup...
      const [parentUser] = await dbInstance.select().from(spTable).where(eq(spTable.id, userId)).limit(1);
      if (!parentUser || parentUser.role !== 'client') {
        return res.status(404).json({ message: "Usuario cliente padre no encontrado" });
      }

      let parentClient: any = null;
      if (parentUser.clientId) {
        const [pc] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, parentUser.clientId)).limit(1);
        parentClient = pc || null;
      }

      if (!parentClient) {
        return res.status(400).json({ message: "El usuario padre debe tener una ficha de cliente vinculada para crear sucursales" });
      }

      const parentClientId = parentClient.parentClientId || parentClient.id;
      let branchUsers: any[] = [];
      const branchName = `${parentClient.nokoen || parentUser.salespersonName} - ${branchLabel}`;

      if (userIdsToLink.length > 0) {
        // Use existing users — verify they exist and are clients
        const existingUsers = await dbInstance.select().from(spTable).where(inArray(spTable.id, userIdsToLink));
        if (existingUsers.length !== userIdsToLink.length) {
          return res.status(404).json({ message: "Alguno de los usuarios seleccionados no fue encontrado" });
        }
        for (const eu of existingUsers) {
          if (eu.role !== 'client') {
            return res.status(400).json({ message: `El usuario ${eu.email || eu.salespersonName} debe ser de tipo cliente` });
          }
        }
        branchUsers = existingUsers;
        console.log(`[CREATE-BRANCH] Using existing users [${userIdsToLink.join(', ')}] for branch "${branchLabel}"`);
      } else {
        // Create a new user for the branch
        const bcrypt = await import('bcryptjs');
        const passwordHash = await bcrypt.hash(password, 10);

        const [newUser] = await dbInstance.insert(spTable).values({
          salespersonName: branchName,
          username,
          email: email || null,
          password: passwordHash,
          isActive: true,
          role: 'client',
          clientRut: parentClient.rten || parentUser.clientRut || null,
        }).returning();
        branchUsers = [newUser];
      }

      // Create the clients record for the branch
      // Take the first user's email as default
      const branchEmail = branchUsers.length > 0 ? (branchUsers[0].email || branchUsers[0].publicEmail || parentClient.email || null) : (email || parentClient.email || null);
      // Validate discount range
      const safeDiscount = Math.min(100, Math.max(0, parseFloat(discountPercent) || 0));

      const [branchClient] = await dbInstance.insert(clientsTable).values({
        nokoen: branchName,
        rten: parentClient.rten || null,
        email: branchEmail,
        foen: parentClient.foen || null,
        dien: address !== undefined ? (address || null) : (parentClient.dien || null),
        cmen: parentClient.cmen || null,
        comuna: parentClient.comuna || null,
        userId: branchUsers.length > 0 ? branchUsers[0].id : null,
        parentClientId: parentClientId,
        branchLabel,
        branchDiscountPercent: String(safeDiscount),
        kofuen: salesRepCode || parentClient.kofuen || null,
        pickupWarehouseId: pickupWarehouseId || null,
        crlt: creditLimit ? String(creditLimit) : parentClient.crlt || null,
        cren: creditLimit ? String(creditLimit) : parentClient.cren || null,
        crsd: '0',
        cpen: paymentCondition || parentClient.cpen || null,
        lcen: lcen || parentClient.lcen || null,
      }).returning();

      // Link users to the new branch client record via junction table (multi-branch support)
      const { userBranchAssignments } = await import('@shared/schema');
      for (const branchUser of branchUsers) {
        // Insert into junction table (ON CONFLICT DO NOTHING for idempotency)
        await dbInstance.insert(userBranchAssignments).values({
          userId: branchUser.id,
          clientId: branchClient.id,
        }).onConflictDoNothing();

        // Only set clientId if the user doesn't have one yet (first assignment / backwards compat)
        if (!branchUser.clientId) {
          await dbInstance.update(spTable)
            .set({ clientId: branchClient.id, updatedAt: new Date() })
            .where(eq(spTable.id, branchUser.id));
        }
      }

      console.log(`[CREATE-BRANCH] Created branch "${branchLabel}" (client ${branchClient.id}) under parent ${parentClientId}`);
      res.json({
        success: true,
        message: `Sucursal "${branchLabel}" creada exitosamente`,
        branchUsers,
        branchClient,
      });
    } catch (error: any) {
      console.error("Error creating branch:", error);
      if (error.code === '23505') {
        return res.status(409).json({ message: "Ya existe un usuario con ese nombre de usuario o email" });
      }
      res.status(500).json({ message: "Error al crear sucursal" });
    }
  });

  // Edit an existing branch (sucursal)
  app.put('/api/users/clients/branches/:branchId', requireCommercialAccess, async (req: any, res) => {
    try {
      const { branchId } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { branchLabel, username, email, password, salesRepCode, pickupWarehouseId, creditLimit, paymentCondition, lcen, existingUserId, existingUserIds, address, discountPercent } = req.body;

      if (!branchLabel) {
        return res.status(400).json({ message: "branchLabel es requerido" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable } = await import('@shared/schema');
      const { eq, inArray, and } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Verify branch exists
      const [branchClient] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, branchId)).limit(1);
      if (!branchClient) {
        return res.status(404).json({ message: "Sucursal no encontrada" });
      }

      const branchName = `${branchClient.nokoen?.split(' - ')[0] || branchClient.nokoen} - ${branchLabel}`;

      const userIdsToLink = existingUserIds && Array.isArray(existingUserIds) && existingUserIds.length > 0
        ? existingUserIds
        : (existingUserId ? [existingUserId] : []);

      // Handle user association if provided — use junction table for multi-branch support
      let branchUsers = [];
      const { userBranchAssignments } = await import('@shared/schema');
      console.log(`[EDIT-BRANCH] branchId=${branchId}, branchLabel=${branchLabel}, existingUserIds=${JSON.stringify(existingUserIds)}, existingUserId=${existingUserId}, userIdsToLink=${JSON.stringify(userIdsToLink)}`);
      if (userIdsToLink.length > 0) {
        // Sync junction table: remove deselected, add new ones
        // 1. Get current assignments for this branch
        const currentAssignments = await dbInstance.select()
          .from(userBranchAssignments)
          .where(eq(userBranchAssignments.clientId, branchClient.id));
        const currentUserIds = currentAssignments.map(a => a.userId);

        // 2. Remove users that were deselected from this branch (only from THIS branch)
        const toRemove = currentUserIds.filter(uid => !userIdsToLink.includes(uid));
        for (const uid of toRemove) {
          await dbInstance.delete(userBranchAssignments)
            .where(
              and(
                eq(userBranchAssignments.userId, uid),
                eq(userBranchAssignments.clientId, branchClient.id)
              )
            );
        }

        // 3. Add new users to this branch
        const existingUsers = await dbInstance.select().from(spTable).where(inArray(spTable.id, userIdsToLink));
        for (const eu of existingUsers) {
          if (eu.role === 'client') {
            // Insert junction entry (idempotent)
            await dbInstance.insert(userBranchAssignments).values({
              userId: eu.id,
              clientId: branchClient.id,
            }).onConflictDoNothing();

            // Set clientId only if user doesn't have one yet
            if (!eu.clientId) {
              await dbInstance.update(spTable)
                .set({ clientId: branchClient.id, updatedAt: new Date() })
                .where(eq(spTable.id, eu.id));
            }
            branchUsers.push(eu);
          }
        }
        console.log(`[EDIT-BRANCH] Synced users for branch "${branchLabel}": added ${userIdsToLink.length - currentUserIds.filter(uid => userIdsToLink.includes(uid)).length}, removed ${toRemove.length}`);
      } else if (username && password) {
        // Create new user linked to this branch
        const bcrypt = await import('bcryptjs');
        const passwordHash = await bcrypt.hash(password, 10);
        const [newUser] = await dbInstance.insert(spTable).values({
          salespersonName: branchName,
          username,
          email: email || null,
          password: passwordHash,
          isActive: true,
          role: 'client',
          clientRut: branchClient.rten || null,
          clientId: branchClient.id,
        }).returning();
        // Also create junction entry for the new user
        await dbInstance.insert(userBranchAssignments).values({
          userId: newUser.id,
          clientId: branchClient.id,
        }).onConflictDoNothing();
        branchUsers = [newUser];
        console.log(`[EDIT-BRANCH] Created new user ${newUser.id} for branch "${branchLabel}"`);
      }

      // Update the branch client record
      const updateData: Record<string, any> = {
        nokoen: branchName,
        branchLabel,
        kofuen: salesRepCode !== undefined ? (salesRepCode || null) : branchClient.kofuen,
        pickupWarehouseId: pickupWarehouseId !== undefined ? (pickupWarehouseId === 'none' ? null : pickupWarehouseId) : branchClient.pickupWarehouseId,
        crlt: creditLimit !== undefined ? (creditLimit ? String(creditLimit) : null) : branchClient.crlt,
        cren: creditLimit !== undefined ? (creditLimit ? String(creditLimit) : null) : branchClient.cren,
        cpen: paymentCondition !== undefined ? (paymentCondition || null) : branchClient.cpen,
        lcen: lcen !== undefined ? (lcen || null) : branchClient.lcen,
        updatedAt: new Date()
      };

      // Address update
      if (address !== undefined) {
        updateData.dien = address || null;
      }

      // Discount update (validate 0-100)
      if (discountPercent !== undefined) {
        const safeDiscount = Math.min(100, Math.max(0, parseFloat(discountPercent) || 0));
        updateData.branchDiscountPercent = String(safeDiscount);
      }

      await dbInstance.update(clientsTable).set(updateData).where(eq(clientsTable.id, branchId));

      res.json({
        success: true,
        message: `Sucursal "${branchLabel}" actualizada exitosamente`,
        branchUsers
      });
    } catch (error: any) {
      console.error("Error editing branch:", error);
      if (error.code === '23505') {
        return res.status(409).json({ message: "Ya existe un usuario con ese nombre de usuario o email" });
      }
      res.status(500).json({ message: "Error al actualizar sucursal" });
    }
  });

  // Get sibling branches for a client (all branches under same parent)
  app.get('/api/users/clients/:clientId/branches', requireCommercialAccess, async (req: any, res) => {
    try {
      const { clientId } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { clients: clientsTable } = await import('@shared/schema');
      const { eq, or } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Find the client record
      const [clientRecord] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, clientId)).limit(1);
      if (!clientRecord) {
        return res.status(404).json({ message: "Cliente no encontrado" });
      }

      // Determine the root parent ID
      const rootId = clientRecord.parentClientId || clientRecord.id;

      // Get all branches under this root (including the root itself)
      const allBranches = await dbInstance.select().from(clientsTable)
        .where(
          or(
            eq(clientsTable.id, rootId),
            eq(clientsTable.parentClientId, rootId)
          )
        );

      // Calculate group totals
      const groupCreditLimit = allBranches.reduce((sum, b) => sum + (parseFloat(b.crlt as string) || 0), 0);
      const groupCreditUsed = allBranches.reduce((sum, b) => sum + (parseFloat(b.crsd as string) || 0), 0);
      const groupCreditAvailable = allBranches.reduce((sum, b) => sum + (parseFloat(b.cren as string) || 0), 0);

      res.json({
        rootId,
        branches: allBranches.map(b => ({
          id: b.id,
          name: b.nokoen,
          branchLabel: b.branchLabel,
          isRoot: b.id === rootId,
          creditLimit: b.crlt ? parseFloat(b.crlt as string) : null,
          creditUsed: b.crsd ? parseFloat(b.crsd as string) : null,
          creditAvailable: b.cren ? parseFloat(b.cren as string) : null,
          salesRepCode: b.kofuen,
          pickupWarehouseId: b.pickupWarehouseId,
          paymentCondition: b.cpen,
          address: b.dien || null,
          discountPercent: b.branchDiscountPercent ? parseFloat(b.branchDiscountPercent as string) : 0,
        })),
        groupTotals: {
          creditLimit: groupCreditLimit,
          creditUsed: groupCreditUsed,
          creditAvailable: groupCreditAvailable,
          branchCount: allBranches.length,
        },
      });
    } catch (error) {
      console.error("Error fetching branches:", error);
      res.status(500).json({ message: "Error al obtener sucursales" });
    }
  });

  // Get all users linked to a client group (empresa) — uses junction table for multi-branch support
  app.get('/api/users/clients/:clientId/users', requireCommercialAccess, async (req: any, res) => {
    try {
      const { clientId } = req.params;
      const user = req.user;

      if (!['admin', 'supervisor', 'encargado_area'].includes(user.role)) {
        return res.status(403).json({ message: "No autorizado" });
      }

      const { salespeopleUsers: spTable, clients: clientsTable, userBranchAssignments } = await import('@shared/schema');
      const { eq, or, inArray, isNotNull } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Find the client record
      const [clientRecord] = await dbInstance.select().from(clientsTable).where(eq(clientsTable.id, clientId)).limit(1);
      if (!clientRecord) {
        return res.status(404).json({ message: "Cliente no encontrado" });
      }

      // Determine the root parent ID
      const rootId = clientRecord.parentClientId || clientRecord.id;

      // Get all client records under this root (including the root itself)
      const allGroupClients = await dbInstance.select().from(clientsTable)
        .where(
          or(
            eq(clientsTable.id, rootId),
            eq(clientsTable.parentClientId, rootId)
          )
        );

      const allClientIds = allGroupClients.map(c => c.id);

      // Get all junction assignments for branches in this group
      const allAssignments = allClientIds.length > 0
        ? await dbInstance.select().from(userBranchAssignments)
            .where(inArray(userBranchAssignments.clientId, allClientIds))
        : [];

      // Also get users linked via legacy clientId (for backward compatibility)
      const legacyLinkedUsers = allClientIds.length > 0
        ? await dbInstance.select().from(spTable)
            .where(inArray(spTable.clientId, allClientIds))
        : [];

      // Collect all unique user IDs (from junction + legacy)
      const allUserIds = Array.from(new Set([
        ...allAssignments.map(a => a.userId),
        ...legacyLinkedUsers.map(u => u.id),
      ]));

      // Fetch all user records
      const allUsers = allUserIds.length > 0
        ? await dbInstance.select().from(spTable).where(inArray(spTable.id, allUserIds))
        : [];

      // Build a map: userId → array of branch assignments
      const userBranchMap = new Map<string, Array<{ clientId: string; branchLabel: string | null; branchName: string | null }>>();
      for (const assignment of allAssignments) {
        const branch = allGroupClients.find(c => c.id === assignment.clientId);
        if (!userBranchMap.has(assignment.userId)) {
          userBranchMap.set(assignment.userId, []);
        }
        userBranchMap.get(assignment.userId)!.push({
          clientId: assignment.clientId,
          branchLabel: branch?.branchLabel || null,
          branchName: branch?.nokoen || null,
        });
      }

      // Enrich with branch info (use junction table data, fallback to legacy clientId)
      const enrichedUsers = allUsers.map(u => {
        const branches = userBranchMap.get(u.id) || [];
        // Fallback: if no junction entries, use legacy clientId
        if (branches.length === 0 && u.clientId) {
          const legacyClient = allGroupClients.find(c => c.id === u.clientId);
          if (legacyClient) {
            branches.push({
              clientId: legacyClient.id,
              branchLabel: legacyClient.branchLabel || null,
              branchName: legacyClient.nokoen || null,
            });
          }
        }
        const primaryBranch = branches[0] || null;
        return {
          id: u.id,
          salespersonName: u.salespersonName,
          username: u.username,
          email: u.email || u.publicEmail,
          phone: u.publicPhone,
          role: u.role,
          isActive: u.isActive,
          clientId: u.clientId,
          clientRut: u.clientRut,
          createdAt: u.createdAt,
          // Primary branch info (backward compat)
          branchLabel: primaryBranch?.branchLabel || null,
          branchName: primaryBranch?.branchName || null,
          isRoot: primaryBranch ? !allGroupClients.find(c => c.id === primaryBranch.clientId)?.parentClientId : false,
          // Multi-branch assignments
          branchAssignments: branches,
        };
      });

      res.json(enrichedUsers);
    } catch (error) {
      console.error("Error fetching group users:", error);
      res.status(500).json({ message: "Error al obtener usuarios del grupo" });
    }
  });

