  const NOTIFICATION_CREATOR_ROLES = ['admin', 'supervisor', 'encargado_area', 'logistica_bodega', 'logistica', 'laboratorio', 'area_produccion', 'area_logistica', 'area_aplicacion', 'produccion', 'planificacion'];

