  app.post('/api/price-list-offers', requireAuth, async (req: any, res) => {
    try {
      if (req.user.role !== 'admin' && (req.user.role !== 'supervisor' && req.user.role !== 'encargado_area')) {
        return res.status(403).json({ message: "Not authorized" });
      }
      const { priceListOffers, priceListOfferClients, insertPriceListOffersSchema } = await import('@shared/schema');
      const validatedData = insertPriceListOffersSchema.parse(req.body);
      const allClients = validatedData.allClients !== false;
      const clientIds: string[] = Array.isArray(req.body.clientIds)
        ? req.body.clientIds.filter((c: any) => typeof c === 'string' && c.trim())
        : [];
      if (!allClients && clientIds.length === 0) {
        return res.status(400).json({ message: "Selecciona al menos un cliente o marca 'Todos los clientes'" });
      }

      // Validación cruzada: campos requeridos por tipo de oferta
      const offerType = validatedData.offerType || 'regular';
      if (offerType === 'pallet') {
        if (!validatedData.unitsPerPallet || validatedData.unitsPerPallet < 1) {
          return res.status(400).json({ message: "Unidades por pallet es requerido y debe ser ≥ 1" });
        }
        const hasDiscount = validatedData.discountPct != null;
        const hasPalletPrice = validatedData.palletPrice != null;
        if (!hasDiscount && !hasPalletPrice) {
          return res.status(400).json({ message: "Debe especificar descuento % o precio fijo del pallet" });
        }
        if (hasDiscount && hasPalletPrice) {
          return res.status(400).json({ message: "Usa descuento % o precio fijo, no ambos" });
        }
        if (hasDiscount && (validatedData.discountPct! < 0 || validatedData.discountPct! > 100)) {
          return res.status(400).json({ message: "Descuento debe estar entre 0 y 100" });
        }
        if (hasPalletPrice && validatedData.palletPrice! <= 0) {
          return res.status(400).json({ message: "Precio del pallet debe ser > 0" });
        }
      } else if (offerType === 'regular') {
        if (validatedData.precio == null) {
          return res.status(400).json({ message: "Precio es requerido para ofertas regulares" });
        }
      }

      const valuesToInsert: any = { ...validatedData, allClients };
      // Drizzle numeric() requiere string
      if (validatedData.discountPct != null) {
        valuesToInsert.discountPct = String(validatedData.discountPct);
      }
      if (validatedData.palletPrice != null) {
        valuesToInsert.palletPrice = String(validatedData.palletPrice);
      }
      const [item] = await db.insert(priceListOffers).values(valuesToInsert).returning();
      if (!allClients && clientIds.length > 0) {
        await db.insert(priceListOfferClients).values(
          clientIds.map((cid) => ({ offerId: item.id, clientId: cid }))
        );
      }
      res.status(201).json(item);
    } catch (error) {
      console.error("Error creating price list offers item:", error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      res.status(500).json({ message: "Failed to create price list offers item" });
    }
  });

  app.patch('/api/price-list-offers/:id', requireAuth, async (req: any, res) => {
    try {
      if (req.user.role !== 'admin' && (req.user.role !== 'supervisor' && req.user.role !== 'encargado_area')) {
        return res.status(403).json({ message: "Not authorized" });
      }
      const { priceListOffers, priceListOfferClients } = await import('@shared/schema');

      // Whitelist de columnas actualizables (clientIds se maneja aparte en la tabla junction)
      const updateData: any = { updatedAt: new Date() };
      if (req.body.precio !== undefined) updateData.precio = req.body.precio;
      if (req.body.paused !== undefined) updateData.paused = req.body.paused;
      if (req.body.allClients !== undefined) updateData.allClients = req.body.allClients === true;
      // Campos de oferta pallet
      if (req.body.unitsPerPallet !== undefined) {
        const n = Number(req.body.unitsPerPallet);
        if (req.body.unitsPerPallet !== null && (!Number.isInteger(n) || n < 1)) {
          return res.status(400).json({ message: "unitsPerPallet debe ser entero ≥ 1" });
        }
        updateData.unitsPerPallet = req.body.unitsPerPallet === null ? null : n;
      }
      if (req.body.discountPct !== undefined) {
        if (req.body.discountPct !== null) {
          const pct = Number(req.body.discountPct);
          if (!Number.isFinite(pct) || pct < 0 || pct > 100) {
            return res.status(400).json({ message: "discountPct debe estar entre 0 y 100" });
          }
          updateData.discountPct = String(pct);
        } else {
          updateData.discountPct = null;
        }
      }
      if (req.body.palletPrice !== undefined) {
        if (req.body.palletPrice !== null) {
          const pp = Number(req.body.palletPrice);
          if (!Number.isFinite(pp) || pp <= 0) {
            return res.status(400).json({ message: "palletPrice debe ser > 0" });
          }
          updateData.palletPrice = String(pp);
        } else {
          updateData.palletPrice = null;
        }
      }
      // Pallet: enforce que discountPct y palletPrice sean mutuamente excluyentes
      // (sólo cuando ambos campos vienen en el body explícitamente).
      if (
        req.body.discountPct !== undefined &&
        req.body.palletPrice !== undefined &&
        updateData.discountPct != null &&
        updateData.palletPrice != null
      ) {
        return res.status(400).json({ message: "Usa descuento % o precio fijo del pallet, no ambos" });
      }
      // offer_type es inmutable en updates (cambiar de regular↔pallet borraría datos del otro tipo)

      const clientIdsProvided = Array.isArray(req.body.clientIds);
      const clientIds: string[] = clientIdsProvided
        ? req.body.clientIds.filter((c: any) => typeof c === 'string' && c.trim())
        : [];

      // Solo validamos/sincronizamos audiencia si vino allClients o clientIds en el body
      // (un toggle de "pausa" no debe tocar la lista de clientes existente).
      const touchingAudience = req.body.allClients !== undefined || clientIdsProvided;
      if (touchingAudience && updateData.allClients === false && clientIds.length === 0) {
        return res.status(400).json({ message: "Selecciona al menos un cliente o marca 'Todos los clientes'" });
      }

      const [item] = await db.update(priceListOffers)
        .set(updateData)
        .where(eq(priceListOffers.id, req.params.id))
        .returning();
      if (!item) return res.status(404).json({ message: "Not found" });

      if (touchingAudience) {
        await db.delete(priceListOfferClients).where(eq(priceListOfferClients.offerId, item.id));
        if (item.allClients === false && clientIds.length > 0) {
          await db.insert(priceListOfferClients).values(
            clientIds.map((cid) => ({ offerId: item.id, clientId: cid }))
          );
        }
      }

      res.json(item);
    } catch (error) {
      console.error("Error updating price list offers item:", error);
      res.status(500).json({ message: "Failed to update price list offers item" });
    }
  });

