  app.put('/api/product-questions/:id/resolve', requireAuth, async (req: any, res) => {
    try {
      const { id } = req.params;
      const updated = await storage.resolveProductQuestion(id, req.user.username);
      res.json(updated);
    } catch (error) {
      res.status(500).json({ message: "Failed to resolve product question" });
    }
  });

  // Store API endpoints (public access)

  // ──── Lightweight in-memory cache for public store endpoints ────
  // These rarely change and are hit on every /tienda page load.
  // Cache avoids ~300ms Supabase round-trip per query (×5 endpoints = 1.5s saved).
  const _storeEndpointCache: Record<string, { data: any; ts: number }> = {};
  const STORE_EP_TTL = 120_000; // 2 minutes
  const getStoreCache = (key: string) => {
    const entry = _storeEndpointCache[key];
    if (entry && Date.now() - entry.ts < STORE_EP_TTL) return entry.data;
    return null;
  };
  const setStoreCache = (key: string, data: any) => {
    _storeEndpointCache[key] = { data, ts: Date.now() };
  };
  // Invalidate all public caches when admin updates config/banners/categories
  const invalidateAllStoreCache = () => {
    Object.keys(_storeEndpointCache).forEach(k => delete _storeEndpointCache[k]);
    invalidateStoreCache(); // Also invalidate the product catalog cache
  };

  // Get store configuration
  app.get('/api/store/config', async (req: any, res) => {
    try {
      const cached = getStoreCache('config');
      if (cached) { res.set('X-Cache', 'HIT'); return res.json(cached); }
      const config = await storage.getStoreConfig();
      const result = config || {
        siteName: "Pinturas Panorámica",
        logoUrl: "/panoramica-logo.png",
        primaryColor: "#FF6B35"
      };
      setStoreCache('config', result);
      res.json(result);
    } catch (error) {
      console.error("Error fetching store config:", error);
      res.status(500).json({ message: "Failed to fetch store configuration" });
    }
  });

  // Get active store banners
  app.get('/api/store/banners', async (req: any, res) => {
    try {
      const cached = getStoreCache('banners');
      if (cached) { res.set('X-Cache', 'HIT'); return res.json(cached); }
      const banners = await storage.getStoreBanners();
      setStoreCache('banners', banners);
      res.json(banners);
    } catch (error) {
      console.error("Error fetching store banners:", error);
      res.status(500).json({ message: "Failed to fetch store banners" });
    }
  });

  // ==========================================
  // ADMIN BANNER CRUD ENDPOINTS
  // ==========================================

  // Get all banners (admin - includes inactive)
  app.get('/api/ecommerce/admin/banners', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const { type } = req.query;
      let query = db.select().from(storeBanners);
      
      if (type) {
        query = query.where(eq(storeBanners.tipoVisualizacion, type)) as any;
      }
      
      const allBanners = await query.orderBy(storeBanners.orden);
      res.json(allBanners);
    } catch (error: any) {
      res.status(500).json({ message: 'Error fetching banners', error: error.message });
    }
  }));

  // Toggle banner active state
  app.patch('/api/ecommerce/admin/banners/:id/toggle', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const { id } = req.params;
      const [banner] = await db.select().from(storeBanners).where(eq(storeBanners.id, id)).limit(1);
      if (!banner) return res.status(404).json({ message: 'Banner no encontrado' });

      const [updated] = await db.update(storeBanners)
        .set({ activo: !banner.activo, updatedAt: new Date() })
        .where(eq(storeBanners.id, id))
        .returning();

      res.json(updated);
    } catch (error: any) {
      res.status(500).json({ message: 'Error toggling banner', error: error.message });
    }
  }));

  // Reorder banner
  app.patch('/api/ecommerce/admin/banners/:id/reorder', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const { id } = req.params;
      const { orden } = req.body;
      if (typeof orden !== 'number') return res.status(400).json({ message: 'Invalid orden' });

      const [updated] = await db.update(storeBanners)
        .set({ orden, updatedAt: new Date() })
        .where(eq(storeBanners.id, id))
        .returning();

      res.json(updated);
    } catch (error: any) {
      res.status(500).json({ message: 'Error reordering banner', error: error.message });
    }
  }));

  // Delete banner
  app.delete('/api/ecommerce/admin/banners/:id', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const { id } = req.params;
      await db.delete(storeBanners).where(eq(storeBanners.id, id));
      delete _storeEndpointCache?.['banners'];
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ message: 'Error deleting banner', error: error.message });
    }
  }));

  // Get ecommerce products with images and prices (excluding grouped products)
  app.get('/api/store/products', async (req: any, res) => {
    try {
      const { search, categoria } = req.query;

      const filters = {
        search: search || undefined,
        categoria: categoria || undefined,
        activo: true, // Only show active products
        groupId: null // Only fetch products WITHOUT a group (ungrouped products)
      };

      const ungroupedProducts = await storage.getEcommerceAdminProducts(filters);

      res.json(ungroupedProducts);
    } catch (error) {
      console.error("Error fetching store products:", error);
      res.status(500).json({ message: "Failed to fetch store products" });
    }
  });

  // Get store categories — from admin-created categories OR from actual product data
  app.get('/api/store/categories', async (req: any, res) => {
    try {
      const cached = getStoreCache('categories');
      if (cached) { res.set('X-Cache', 'HIT'); return res.json(cached); }
      // Priority 1: Custom categories from app_config (Productos > Categorías y Etiquetas)
      try {
        const configResult = await db.execute(sql`
          SELECT value FROM app_config WHERE key = 'ecommerce_categories'
        `);
        const configRow = (configResult as any).rows?.[0];
        const customCategories: any[] = configRow?.value || [];
        if (customCategories.length > 0) {
          const catNames = customCategories.map((c: any) => c.name);
          setStoreCache('categories', catNames);
          return res.json(catNames);
        }
      } catch (e) {
        console.log('[store/categories] app_config lookup skipped:', e);
      }

      // Priority 2: Admin-created categories from ecommerce_categories table
      const adminCategories = await storage.getEcommerceAdminCategories();
      const adminCategoryNames = adminCategories
        .filter(c => c.activa)
        .map(c => c.nombre);

      if (adminCategoryNames.length > 0) {
        const sorted = adminCategoryNames.sort();
        setStoreCache('categories', sorted);
        return res.json(sorted);
      }

      // Fallback: get distinct categories directly from active ecommerce_products
      const { ecommerceProducts } = await import('@shared/schema');
      const result = await db
        .selectDistinct({ categoria: ecommerceProducts.categoria })
        .from(ecommerceProducts)
        .where(and(
          eq(ecommerceProducts.activo, true),
          sql`${ecommerceProducts.categoria} IS NOT NULL AND ${ecommerceProducts.categoria} != ''`
        ))
        .orderBy(ecommerceProducts.categoria);

      const categoryNames = result
        .map(r => r.categoria)
        .filter((cat): cat is string => !!cat);
      setStoreCache('categories', categoryNames);
      res.json(categoryNames);
    } catch (error) {
      console.error("Error fetching store categories:", error);
      res.status(500).json({ message: "Failed to fetch store categories" });
    }
  });

  // Get product groups with variants for store
  app.get('/api/store/groups', async (req: any, res) => {
    try {
      const groups = await storage.getProductGroups({ activo: true });

      // For each group, fetch its variant products
      const groupsWithProducts = await Promise.all(
        groups.map(async (group) => {
          const products = await storage.getEcommerceAdminProducts({
            groupId: group.id,
            activo: true
          });

          return {
            ...group,
            productos: products
          };
        })
      );

      // Only return groups that have products
      const activeGroups = groupsWithProducts.filter(g => g.productos.length > 0);
      res.json(activeGroups);
    } catch (error) {
      console.error("Error fetching store product groups:", error);
      res.status(500).json({ message: "Failed to fetch product groups" });
    }
  });

  // Get grouped products for the store (same grouping as salesperson catalog, but with prices)
  // ──────── Store Catalog Cache ────────
  // In-memory cache for the full grouped catalog to avoid 3 DB queries per request
  let _storeCatalogCache: { catalog: any[]; totalProducts: number; builtAt: number } | null = null;
  const STORE_CACHE_TTL = 60_000; // 60 seconds

  // Normaliza texto para búsqueda: minúsculas y sin tildes/acentos.
  // Así "latex" encuentra "látex", "construccion" → "construcción", etc.
  // Rango U+0300–U+036F = marcas diacríticas combinantes (vía String.fromCharCode para evitar escapes Unicode en el fuente).
  const DIACRITICS_RE = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
  const normalizeSearch = (str: string) => str.normalize('NFD').replace(DIACRITICS_RE, '').toLowerCase();

  // Invalidate store cache (call this when products/order/images change)
  const invalidateStoreCache = () => { _storeCatalogCache = null; };

  // Build the full catalog
  const buildStoreCatalog = async (priceList?: string): Promise<{ catalog: any[]; totalProducts: number }> => {
   // Check cache only if no custom price list
    const useCache = !priceList || priceList === 'LP01';
    if (useCache && _storeCatalogCache && Date.now() - _storeCatalogCache.builtAt < STORE_CACHE_TTL) {
      return _storeCatalogCache;
    }

    // Any list other than LP01 is a custom list that uses custom_price_list_items
    const useCustomList = priceList && priceList !== 'LP01';

    const result = await db.execute(sql`
      SELECT
        ep.id as ecom_id,
        ep.categoria as group_name,
        ep.descripcion as description,
        ep.variant_generic_display_name,
        ep.color,
        ep.format_unit,
        ep.min_unit,
        ep.step_size,
        ep.price_list_id,
        ep.tags,
        ep.imagen_url,
        ep.slug,
        ${useCustomList 
          ? sql`COALESCE(cpli.precio, pl.lista, ep.precio_ecommerce) as precio`
          : sql`COALESCE(ep.precio_ecommerce, pl.lista) as precio`},
        ${useCustomList
          ? sql`CASE WHEN cpli.precio IS NOT NULL THEN ${priceList} ELSE 'LP01' END as price_source`
          : sql`'LP01' as price_source`},
        pl.codigo as sku,
        pl.producto as product_name,
        pl.unidad as unit,
        COALESCE(offers.precio, pl.offer_price) as offer_price,
        pallet_offer.units_per_pallet as pallet_units,
        pallet_offer.discount_pct as pallet_discount_pct,
        pallet_offer.pallet_price as pallet_price,
        (pallet_offer.id IS NOT NULL) as pallet_enabled,
        COALESCE(stk.total_stock, 0) as total_stock,
        pc.breve_resena,
        pc.descripcion,
        pc.usos,
        pc.presentacion,
        pc.imagen_destacada
      FROM ecommerce_products ep
      LEFT JOIN price_list pl ON ep.price_list_id = pl.id
      ${useCustomList
        ? sql`LEFT JOIN custom_price_list_items cpli ON UPPER(cpli.codigo) = UPPER(pl.codigo) AND cpli.list_code = ${priceList}`
        : sql``}
      -- Catálogo compartido/cacheado: solo ofertas globales (all_clients). Las ofertas
      -- dirigidas a clientes específicos se aplican al precio en el carrito/checkout
      -- (resolveItemsPricing), que es la fuente autoritativa de precio.
      LEFT JOIN price_list_offers offers ON UPPER(offers.codigo) = UPPER(pl.codigo) AND (offers.paused IS NULL OR offers.paused = false) AND offers.all_clients = true AND offers.offer_type = 'regular'
      LEFT JOIN price_list_offers pallet_offer ON UPPER(pallet_offer.codigo) = UPPER(pl.codigo) AND (pallet_offer.paused IS NULL OR pallet_offer.paused = false) AND pallet_offer.offer_type = 'pallet'
      LEFT JOIN (
        SELECT kopr, SUM(COALESCE(physical_stock2, 0)) as total_stock
        FROM product_stock
        GROUP BY kopr
      ) stk ON stk.kopr = pl.codigo
      LEFT JOIN product_content pc ON pc.codigo = pl.codigo
      WHERE ep.activo = true
      ORDER BY ep.variant_generic_display_name, ep.color, ep.format_unit
    `);
    const rows = Array.isArray(result) ? result : (result as any).rows || [];

    // Load multi-category assignments from app_config
    let multiCatAssignments: Record<string, string[]> = {};
    try {
      const mcResult = await db.execute(sql`
        SELECT value FROM app_config WHERE key = 'product_category_assignments'
      `);
      const mcRow = (mcResult as any).rows?.[0];
      multiCatAssignments = mcRow?.value || {};
    } catch {}

    const productsMap = new Map<string, {
      genericName: string;
      groupName: string | null;
      categories: string[];
      tags: string[];
      breveResena: string | null;
      descripcion: string | null;
      usos: string | null;
      presentacion: string | null;
      imageUrl: string | null;
      imageUrlPriority: number;
      colors: Map<string, any[]>;
    }>();

    for (const row of rows as any[]) {
      const groupName = row.group_name || null;
      const genericName = (row.variant_generic_display_name || row.product_name || 'Sin Nombre').trim();
      const color = (row.color || 'Sin Color').trim();
      const formatUnit = row.format_unit || row.unit || 'Sin formato';
      const sku = row.sku || row.price_list_id || '';
      let rowTags: string[] = [];
      try { rowTags = JSON.parse(row.tags || '[]'); } catch { rowTags = []; }

      // Use multi-category assignments if available, otherwise fallback to groupName
      const assignedCategories = multiCatAssignments[genericName] || (groupName ? [groupName] : []);

      if (!productsMap.has(genericName)) {
        productsMap.set(genericName, { 
          genericName, groupName: assignedCategories[0] || groupName, 
          categories: assignedCategories,
          tags: rowTags, 
          breveResena: (row as any).breve_resena || null, 
          descripcion: (row as any).descripcion || null,
          usos: (row as any).usos || null,
          presentacion: (row as any).presentacion || null,
          imageUrl: null, imageUrlPriority: 0, colors: new Map() 
        });
      }
      const product = productsMap.get(genericName)!;
      if (rowTags.length > 0 && product.tags.length === 0) product.tags = rowTags;
      if (!product.breveResena && (row as any).breve_resena) product.breveResena = (row as any).breve_resena;
      if (!product.descripcion && (row as any).descripcion) product.descripcion = (row as any).descripcion;
      if (!product.usos && (row as any).usos) product.usos = (row as any).usos;
      if (!product.presentacion && (row as any).presentacion) product.presentacion = (row as any).presentacion;

      // Image priority: STRONGLY prefer GALON format + BLANCO color
      const rowImageUrl = (row as any).imagen_url || (row as any).imagen_destacada || null;
      if (rowImageUrl) {
        let priority = 1;
        const colorUpper = color.toUpperCase();
        const formatUpper = formatUnit.toUpperCase();
        if (colorUpper.includes('BLANCO') || colorUpper === 'BLANCO') priority += 10;
        const is14 = formatUpper.includes('1/4') || formatUpper.includes('CUARTO');
        const isGalon = !is14 && (formatUpper.includes('GALON') || formatUpper.includes('GALÓN') || /\bGL\b/.test(formatUpper));
        const isBalde = formatUpper.includes('BALDE') || formatUpper.includes('BLD') || formatUpper.includes('BD4') || formatUpper.includes('BD5');
        if (isGalon) priority += 20;
        else if (isBalde) priority += 10;
        else if (is14) priority -= 5;
        if (priority > product.imageUrlPriority) {
          product.imageUrl = rowImageUrl;
          product.imageUrlPriority = priority;
        }
      }
      if (!product.colors.has(color)) {
        product.colors.set(color, []);
      }

      product.colors.get(color)!.push({
        ecomId: row.ecom_id,
        sku,
        slug: row.slug || null,
        name: row.product_name || genericName,
        color,
        format: formatUnit,
        groupName,
        price: row.precio ? parseFloat(row.precio) : null,
        offerPrice: row.offer_price ? parseFloat(row.offer_price) : null,
        priceSource: row.price_source || 'LP01',
        stock: parseFloat(row.total_stock) || 0,
        minUnit: row.min_unit || 1,
        stepSize: row.step_size || 1,
        description: row.description,
        imageUrl: (row as any).imagen_url || null,
        packaging: {
          // Pallet desde price_list_offers (offer_type='pallet'); incluye ambos modos:
          // discountPct (% sobre precio de lista) o palletPrice (total fijo del pallet).
          palletEnabled: row.pallet_enabled === true,
          amountPerPallet: row.pallet_units != null ? Number(row.pallet_units) : null,
          palletDiscountPct: row.pallet_discount_pct != null ? Number(row.pallet_discount_pct) : null,
          palletPrice: row.pallet_price != null ? Number(row.pallet_price) : null,
        },
      });
    }

    let catalog = Array.from(productsMap.values()).map(p => ({
      genericName: p.genericName,
      groupName: p.groupName,
      categories: p.categories,
      tags: p.tags,
      breveResena: p.breveResena,
      descripcion: p.descripcion,
      usos: p.usos,
      presentacion: p.presentacion,
      imageUrl: p.imageUrl,
      colors: Object.fromEntries(p.colors),
      // Precompute searchable text for fast filtering (sin tildes para búsqueda insensible a acentos)
      _searchText: normalizeSearch([
        p.genericName,
        p.groupName || '',
        p.tags?.join(' ') || '',
        p.breveResena || '',
        p.descripcion || '',
        p.usos || '',
        p.presentacion || '',
        ...(Array.from(p.colors.values()).flat().map((v: any) => `${v.sku} ${v.name || ''} ${v.color} ${v.format} ${v.description || ''}`)),
      ].join(' ')),
    }));

    // Apply custom display order from app_config
    try {
      const orderResult = await db.execute(sql`
        SELECT value FROM app_config WHERE key = 'ecommerce_product_order'
      `);
      const orderRow = (orderResult as any).rows?.[0];
      const productOrder: string[] = orderRow?.value || [];
      
      if (productOrder.length > 0) {
        const orderMap = new Map<string, number>();
        productOrder.forEach((name, idx) => orderMap.set(name, idx));
        
        catalog.sort((a, b) => {
          const orderA = orderMap.has(a.genericName) ? orderMap.get(a.genericName)! : Number.MAX_SAFE_INTEGER;
          const orderB = orderMap.has(b.genericName) ? orderMap.get(b.genericName)! : Number.MAX_SAFE_INTEGER;
          if (orderA !== orderB) return orderA - orderB;
          return a.genericName.localeCompare(b.genericName);
        });
      }
    } catch (orderError) {
      console.log('[store/products/grouped] product order lookup skipped:', orderError);
    }

    // Apply manual image overrides from app_config
    try {
      const imgResult = await db.execute(sql`
        SELECT value FROM app_config WHERE key = 'ecommerce_product_group_images'
      `);
      const imgRow = (imgResult as any).rows?.[0];
      const manualImages: Record<string, string> = imgRow?.value || {};
      
      if (Object.keys(manualImages).length > 0) {
        catalog.forEach(p => {
          if (manualImages[p.genericName]) {
            p.imageUrl = manualImages[p.genericName];
          }
        });
      }
    } catch (imgError) {
      console.log('[store/products/grouped] manual images lookup skipped:', imgError);
    }

    const result2 = { catalog, totalProducts: (rows as any[]).length, builtAt: Date.now() };
    if (useCache) {
      _storeCatalogCache = result2;
    }
    console.log(`[STORE CACHE] Built catalog: ${catalog.length} groups, ${(rows as any[]).length} products` + (priceList ? ` (priceList: ${priceList})` : ''));
    return result2;
  };

  // ─── Get branches accessible to current client user ───
  app.get('/api/store/my-branches', async (req: any, res) => {
    try {
      if (!req.user || req.user.role !== 'client') {
        return res.json({ branches: [] });
      }

      const { clients: clientsTable, userBranchAssignments } = await import('@shared/schema');
      const { eq, or, inArray } = await import('drizzle-orm');
      const { db: dbInstance } = await import('./db');

      // Resolve the user's current client record (for backward compat / default branch)
      const clientRecord = await storage.getClientByUserId(req.user.id);

      // Strategy: combine branches from junction table + parent hierarchy
      const branchClientIds = new Set<string>();

      // 1. Get branches from junction table (new multi-branch system)
      const junctionAssignments = await dbInstance.select()
        .from(userBranchAssignments)
        .where(eq(userBranchAssignments.userId, req.user.id));

      for (const a of junctionAssignments) {
        branchClientIds.add(a.clientId);
      }

      // 2. Get branches from parent hierarchy (legacy / backward compat)
      if (clientRecord) {
        const rootId = clientRecord.parentClientId || clientRecord.id;
        const hierarchyBranches = await dbInstance.select().from(clientsTable)
          .where(
            or(
              eq(clientsTable.id, rootId),
              eq(clientsTable.parentClientId, rootId)
            )
          );
        for (const b of hierarchyBranches) {
          branchClientIds.add(b.id);
        }
      }

      if (branchClientIds.size === 0) {
        return res.json({ branches: [] });
      }

      // Fetch all branch records
      const allBranches = await dbInstance.select().from(clientsTable)
        .where(inArray(clientsTable.id, Array.from(branchClientIds)));

      const branches = allBranches.map(b => ({
        id: b.id,
        name: b.nokoen || b.branchLabel || 'Sin nombre',
        branchLabel: b.branchLabel || null,
        isRoot: !b.parentClientId,
        address: b.dien || null,
        discountPercent: b.branchDiscountPercent ? parseFloat(b.branchDiscountPercent as string) : 0,
        priceList: effectivePriceList(b),
      }));

      res.json({
        branches,
        currentBranchId: clientRecord?.id || (branches.length > 0 ? branches[0].id : null),
      });
    } catch (error) {
      console.error('Error fetching user branches:', error);
      res.status(500).json({ message: 'Error al obtener sucursales' });
    }
  });

  app.get('/api/store/products/grouped', async (req: any, res) => {
    try {
      const { search, category, priceList } = req.query;
      const fullCatalog = await buildStoreCatalog(priceList as string | undefined);

      let filtered = fullCatalog.catalog;

      // Filter by category first
      if (category && category !== 'all') {
        filtered = filtered.filter((p: any) => {
          // Check multi-category assignments first, then fallback to groupName
          const cats: string[] = p.categories || (p.groupName ? [p.groupName] : []);
          return cats.includes(category as string);
        });
      }

      // Filter by search text sequentially
      if (search) {
        const s = normalizeSearch((search as string).trim());
        filtered = filtered.filter(p => (p as any)._searchText.includes(s));
      }

      // Strip internal _searchText field before sending
      let cleanCatalog = filtered.map(({ _searchText, ...rest }: any) => rest);

      // ─── Resolve client context (for branch discount and targeted offers) ───
      let branchDiscountApplied = 0;
      let targetedOffersApplied = 0;
      if (req.user && req.user.role === 'client') {
        try {
          const { branchId } = req.query;
          let clientRecord: any;

          if (branchId) {
            const { clients: clientsLookup } = await import('@shared/schema');
            const { eq: eqLookup } = await import('drizzle-orm');
            const { db: dbLookup } = await import('./db');
            const [explicitBranch] = await dbLookup.select().from(clientsLookup).where(eqLookup(clientsLookup.id, branchId as string)).limit(1);
            if (explicitBranch) clientRecord = explicitBranch;
          } else {
            clientRecord = await storage.getClientByUserId(req.user.id);
          }

          // Look up offers targeted to this client (by id or same RUT — to cover all
          // branches of a company even when the user is on the parent). The catalog
          // already includes all_clients=true offers; we layer the targeted ones on top.
          const targetedOfferMap = new Map<string, number>();
          if (clientRecord) {
            const targetClientId = (clientRecord.id || '').toString();
            const targetClientRut = (clientRecord.rten || '').toString().trim();
            try {
              const offerRes: any = await db.execute(sql`
                SELECT UPPER(o.codigo) AS codigo, o.precio
                FROM price_list_offers o
                WHERE (o.paused IS NULL OR o.paused = false)
                  AND o.all_clients = false
                  AND EXISTS (
                    SELECT 1 FROM price_list_offer_clients oc
                    JOIN clients oc_c ON oc_c.id = oc.client_id
                    WHERE oc.offer_id = o.id
                      AND (oc_c.id = ${targetClientId} OR (${targetClientRut} <> '' AND oc_c.rten = ${targetClientRut}))
                  )
              `);
              const offerRows = Array.isArray(offerRes) ? offerRes : (offerRes.rows || []);
              for (const r of offerRows as any[]) {
                if (!r.codigo) continue;
                const p = parseFloat(r.precio?.toString() || '0');
                if (p > 0) targetedOfferMap.set(r.codigo, p);
              }
            } catch (offerErr) {
              console.warn('[STORE] Error resolving targeted offers, serving catalog without them:', offerErr);
            }
          }

          const branchDiscountPct = clientRecord?.branchDiscountPercent
            ? parseFloat(clientRecord.branchDiscountPercent as string) : 0;
          const hasBranchDiscount = branchDiscountPct > 0 && branchDiscountPct <= 100;
          const hasTargetedOffers = targetedOfferMap.size > 0;

          if (hasBranchDiscount || hasTargetedOffers) {
            const factor = hasBranchDiscount ? 1 - branchDiscountPct / 100 : 1;
            if (hasBranchDiscount) branchDiscountApplied = branchDiscountPct;

            // Single deep-copy pass: patch targeted offerPrice and apply convenio to list.
            // Convenio discount applies only to LIST price, never to offers (double-discount).
            cleanCatalog = cleanCatalog.map((product: any) => {
              const newColors: Record<string, any[]> = {};
              for (const [color, variants] of Object.entries(product.colors)) {
                newColors[color] = (variants as any[]).map((v: any) => {
                  const skuUpper = (v.sku || '').toString().toUpperCase();
                  const targetedOffer = targetedOfferMap.get(skuUpper);
                  let nextOfferPrice = v.offerPrice;
                  if (targetedOffer != null) {
                    // Targeted offer beats catalog offer if cheaper (or if catalog has none).
                    if (nextOfferPrice == null || targetedOffer < nextOfferPrice) {
                      nextOfferPrice = targetedOffer;
                      targetedOffersApplied++;
                    }
                  }
                  return {
                    ...v,
                    originalPrice: v.price,
                    price: hasBranchDiscount && v.price != null
                      ? Math.max(0, Math.round(v.price * factor))
                      : v.price,
                    offerPrice: nextOfferPrice,
                  };
                });
              }
              return { ...product, colors: newColors };
            });

            if (hasBranchDiscount) {
              console.log(`[STORE] Applied convenio discount ${branchDiscountPct}% to list prices (offers untouched) for client user ${req.user.id}${branchId ? ` (branch: ${branchId})` : ''}`);
            }
            if (hasTargetedOffers) {
              console.log(`[STORE] Applied ${targetedOffersApplied} targeted offer price(s) for client user ${req.user.id} (client ${clientRecord?.id}, rut ${clientRecord?.rten})`);
            }
          }
        } catch (discountError) {
          console.warn('[STORE] Error resolving client pricing context, serving without overrides:', discountError);
        }
      }

      // Cache control: disable cache when client has custom price list, branch discount,
      // or per-client targeted offers (any of these makes the response client-specific).
      if ((priceList && priceList !== 'LP01') || branchDiscountApplied > 0 || targetedOffersApplied > 0) {
        res.set('Cache-Control', 'no-store');
      } else {
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
      }
      res.json({ catalog: cleanCatalog, totalProducts: fullCatalog.totalProducts, branchDiscountPercent: branchDiscountApplied || undefined });
    } catch (error) {
      console.error('Error fetching store grouped products:', error);
      res.status(500).json({ message: 'Error al cargar productos agrupados' });
    }
  });

  // ───────────────────────────────────────────────────────────────────────────
  // LOOKUP DE CÓDIGO OCULTO / PERSONALIZADO POR SKU EXACTO
  // ───────────────────────────────────────────────────────────────────────────
  // El catálogo de la tienda (/api/store/products/grouped) solo muestra
  // ecommerce_products activos. Pero el equipo comercial crea "códigos
  // personalizados" para un cliente: se agregan a SU lista de precios
  // (custom_price_list_items: Mix/LP02, Panorámica Store, etc.) y se comparten
  // por fuera para que el cliente los inserte a mano, SIN que aparezcan en la
  // vitrina (no tienen fila activa en ecommerce_products).
  //
  // Este endpoint resuelve un SKU EXACTO contra la lista efectiva del cliente +
  // ofertas dirigidas + convenio, devolviendo el producto con la MISMA forma que
  // una variante del catálogo (price/offerPrice/originalPrice) para que el front
  // lo agregue por el mismo flujo. El precio definitivo igual lo recalcula
  // resolveItemsPricing en el checkout (candado de precios), así que esto es solo
  // para descubrir/mostrar el código.
  //
  // Gate de seguridad (modelo "por lista de precios"): solo devuelve el código si
  // pertenece a la lista custom del cliente, o si está marcado es_personalizado
  // en price_list. Así NO se expone todo el catálogo ERP adivinando SKUs.
  app.get('/api/store/products/sku-lookup', requireAuth, asyncHandler(async (req: any, res: any) => {
    if (!req.user || req.user.role !== 'client') {
      return res.status(403).json({ message: 'Solo clientes pueden buscar códigos personalizados' });
    }
    const rawSku = (req.query.sku || '').toString().trim();
    if (rawSku.length < 2) {
      return res.status(400).json({ message: 'SKU inválido' });
    }
    const skuUpper = rawSku.toUpperCase();

    // Resolver el cliente (sucursal explícita o cuenta por defecto) — misma lógica
    // que /grouped, para usar su lista (lcen/override), convenio y RUT.
    let clientRecord: any = null;
    try {
      const { branchId } = req.query;
      if (branchId) {
        const { clients: clientsLookup } = await import('@shared/schema');
        const { eq: eqLookup } = await import('drizzle-orm');
        const { db: dbLookup } = await import('./db');
        const [explicitBranch] = await dbLookup.select().from(clientsLookup).where(eqLookup(clientsLookup.id, branchId as string)).limit(1);
        if (explicitBranch) clientRecord = explicitBranch;
      }
      if (!clientRecord) clientRecord = await storage.getClientByUserId(req.user.id);
    } catch (e) {
      console.warn('[sku-lookup] client resolution failed:', e);
    }

    const priceListCode = (effectivePriceList(clientRecord) || 'LP01').toUpperCase();
    const useCustomList = priceListCode !== 'LP01';
    const branchDiscountPct = clientRecord?.branchDiscountPercent ? parseFloat(clientRecord.branchDiscountPercent as string) || 0 : 0;
    const discountFactor = branchDiscountPct > 0 && branchDiscountPct <= 100 ? 1 - branchDiscountPct / 100 : 1;

    const offerClientId = (clientRecord?.id || '').toString();
    const offerClientRut = (clientRecord?.rten || '').toString().trim();
    const offerAudienceClause = sql`(
      offers.all_clients = true
      OR EXISTS (
        SELECT 1 FROM price_list_offer_clients oc
        JOIN clients oc_c ON oc_c.id = oc.client_id
        WHERE oc.offer_id = offers.id
          AND (oc_c.id = ${offerClientId} OR (${offerClientRut} <> '' AND oc_c.rten = ${offerClientRut}))
      )
    )`;

    try {
      const result: any = await db.execute(sql`
        SELECT
          pl.codigo            AS sku,
          pl.producto          AS product_name,
          pl.unidad            AS unit,
          pl.es_personalizado  AS es_personalizado,
          pl.lista             AS lista,
          ${useCustomList ? sql`cpli.precio` : sql`NULL::numeric`} AS custom_precio,
          COALESCE(offers.precio, pl.offer_price) AS offer_price,
          ep.variant_generic_display_name AS generic_name,
          ep.color             AS color,
          ep.format_unit       AS format_unit,
          ep.min_unit          AS min_unit,
          ep.step_size         AS step_size,
          ep.imagen_url        AS imagen_url,
          ep.activo            AS ep_activo,
          pc.imagen_destacada  AS imagen_destacada
        FROM price_list pl
        ${useCustomList
          ? sql`LEFT JOIN custom_price_list_items cpli ON UPPER(cpli.codigo) = UPPER(pl.codigo) AND cpli.list_code = ${priceListCode}`
          : sql``}
        LEFT JOIN price_list_offers offers
          ON UPPER(offers.codigo) = UPPER(pl.codigo) AND (offers.paused IS NULL OR offers.paused = false) AND ${offerAudienceClause}
        LEFT JOIN ecommerce_products ep ON ep.price_list_id = pl.id
        LEFT JOIN product_content pc ON pc.codigo = pl.codigo
        WHERE UPPER(pl.codigo) = ${skuUpper}
        LIMIT 1
      `);
      const rows = Array.isArray(result) ? result : (result.rows || []);
      const row = rows[0];
      if (!row) {
        return res.status(404).json({ message: 'Código no encontrado' });
      }

      // Gate: el código debe pertenecer a la lista custom del cliente, o estar
      // marcado como personalizado. Si no, no se entrega (evita exponer el ERP).
      const inCustomList = useCustomList && row.custom_precio != null;
      const isPersonalizado = (row.es_personalizado || '').toString().trim().toLowerCase() === 'yes';
      if (!inCustomList && !isPersonalizado) {
        return res.status(404).json({ message: 'Código no disponible para este cliente' });
      }

      // Precio: misma forma que el catálogo para clientes. El convenio se aplica
      // SIEMPRE a la lista (nunca a la oferta); la oferta se decide en el front.
      const baseList = parseFloat((inCustomList ? row.custom_precio : row.lista)?.toString() || '0') || 0;
      const offerNum = row.offer_price != null ? (parseFloat(row.offer_price.toString()) || 0) : 0;
      const hasOffer = offerNum > 0;
      const discountedList = Math.max(0, Math.round(baseList * discountFactor));

      if (discountedList <= 0 && !hasOffer) {
        return res.status(404).json({ message: 'Código sin precio en tu lista' });
      }

      return res.json({
        sku: row.sku,
        productName: row.generic_name || row.product_name || row.sku,
        color: row.color || 'Sin Color',
        format: row.format_unit || row.unit || 'Sin formato',
        price: discountedList,                                  // lista con convenio (base)
        offerPrice: hasOffer ? Math.round(offerNum) : null,     // oferta (gana si menor)
        originalPrice: Math.round(baseList),                    // lista sin convenio
        minUnit: row.min_unit != null ? Number(row.min_unit) : 1,
        stepSize: row.step_size != null ? Number(row.step_size) : 1,
        imageUrl: row.imagen_url || row.imagen_destacada || null,
        hidden: row.ep_activo !== true,                         // true si no está en vitrina
        priceList: priceListCode,
      });
    } catch (error: any) {
      console.error('[sku-lookup] error:', error);
      return res.status(500).json({ message: 'Error al buscar el código' });
    }
  }));

  // Object Storage endpoints

  // Serve public objects from Object Storage with local fallback
  app.get("/public-objects/:filePath(*)", asyncHandler(async (req: any, res: any) => {
    const filePath = req.params.filePath;
    const objectStorageService = new ObjectStorageService();
    const wantsDownload = req.query.download === 'true';

    try {
      // First try Object Storage
      const file = await objectStorageService.searchPublicObject(filePath);
      if (file) {
        // Get metadata to check content type
        const [metadata] = await file.getMetadata();
        const contentType = metadata.contentType || 'application/octet-stream';

        // Set Content-Type header
        res.setHeader('Content-Type', contentType);

        // Set Content-Disposition for download if requested
        if (wantsDownload) {
          const fileName = filePath.split('/').pop() || 'download';
          res.setHeader('Content-Disposition', `attachment; filename="${fileName}"`);
        } else {
          res.setHeader('Content-Disposition', 'inline');
        }

        // Stream the file
        const stream = file.createReadStream();
        stream.on('error', (err) => {
          console.error('Stream error:', err);
          if (!res.headersSent) res.status(500).json({ error: 'Error streaming file' });
        });
        return stream.pipe(res);
      }
    } catch (error) {
      console.warn("Object Storage search failed, trying local fallback:", error);
    }

    // Fallback to local file system for any files (product-images, gastos, fondos, etc.)
    const localPath = path.join(process.cwd(), 'public', filePath);
    try {
      const fs = await import('fs/promises');
      await fs.access(localPath);

      // Set Content-Type based on extension
      const ext = path.extname(filePath).toLowerCase();
      const contentTypes: Record<string, string> = {
        '.pdf': 'application/pdf', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
        '.png': 'image/png', '.gif': 'image/gif', '.webp': 'image/webp',
      };
      const contentType = contentTypes[ext] || 'application/octet-stream';
      res.setHeader('Content-Type', contentType);

      if (wantsDownload) {
        const fileName = filePath.split('/').pop() || 'download';
        res.setHeader('Content-Disposition', `attachment; filename="${fileName}"`);
      } else {
        res.setHeader('Content-Disposition', 'inline');
      }

      return res.sendFile(localPath);
    } catch {
      // File doesn't exist locally either
    }

    return res.status(404).json({ error: "File not found" });
  }));

  // Single image uploader for eCommerce products
  const uploadSingleImage = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 10 * 1024 * 1024 }, // 10MB limit for single images
    fileFilter: (req, file, cb) => {
      const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
      if (validTypes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new Error('Only image files (JPG, PNG, GIF, WEBP) are allowed'));
      }
    }
  });

  // GET Store Config
  app.get('/api/ecommerce/store-config', asyncHandler(async (req: any, res: any) => {
    try {
      const { storeConfig } = await import('@shared/schema');
      const [config] = await db.select().from(storeConfig).limit(1);
      if (!config) {
        return res.json({ id: 'default', seoSettings: { carouselDelay: 5 } });
      }
      res.json(config);
    } catch (error: any) {
      console.error('Error fetching store config:', error);
      res.status(500).json({ message: 'Error fetching config', error: error.message });
    }
  }));

  // UPDATE Store Config
  app.patch('/api/ecommerce/store-config', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const { storeConfig } = await import('@shared/schema');
      const updates = req.body;
      const [existing] = await db.select().from(storeConfig).limit(1);
      
      let updated;
      if (!existing) {
        [updated] = await db.insert(storeConfig).values({ id: 'default', ...updates }).returning();
      } else {
        const mergedSeoSettings = updates.seoSettings ? { ...existing.seoSettings, ...updates.seoSettings } : existing.seoSettings;
        const mergedAdSettings = updates.adSettings ? { ...existing.adSettings, ...updates.adSettings } : existing.adSettings;
        const mergedCheckoutSettings = updates.checkoutSettings ? { ...existing.checkoutSettings, ...updates.checkoutSettings } : existing.checkoutSettings;
        [updated] = await db.update(storeConfig).set({ ...updates, seoSettings: mergedSeoSettings, adSettings: mergedAdSettings, checkoutSettings: mergedCheckoutSettings, updatedAt: new Date() }).where(eq(storeConfig.id, existing.id)).returning();
      }
      res.json(updated);
    } catch (error: any) {
      console.error('Error updating store config:', error);
      res.status(500).json({ message: 'Error updating config', error: error.message });
    }
  }));

  // =====================================
  // COUPONS API
  // =====================================

  // GET /api/admin/coupons — Admin: list all coupons
  app.get('/api/admin/coupons', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const coupons = await storage.getCoupons();
      res.json(coupons);
    } catch (error: any) {
      console.error('[coupons GET] ❌ error:', { message: error?.message, code: error?.code, detail: error?.detail, hint: error?.hint, stack: error?.stack });
      res.status(500).json({ error: 'Error al obtener cupones', details: error?.message });
    }
  }));

  // POST /api/admin/coupons — Admin: create coupon
  app.post('/api/admin/coupons', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      console.log('[coupons POST] ▶️ body recibido:', { ...req.body });
      const data = insertEcommerceCouponSchema.parse(req.body);
      // Coerción: expiresAt llega como ISO string desde el frontend, Drizzle timestamp espera Date
      const sanitized: any = { ...data };
      if (sanitized.expiresAt && typeof sanitized.expiresAt === 'string') {
        const d = new Date(sanitized.expiresAt);
        if (!isNaN(d.getTime())) sanitized.expiresAt = d;
      }
      console.log('[coupons POST] 📝 datos sanitizados:', sanitized);
      const coupon = await storage.createCoupon(sanitized);
      console.log('[coupons POST] ✅ cupón creado:', coupon.id, coupon.code);
      res.status(201).json(coupon);
    } catch (error: any) {
      if (error?.name === 'ZodError') {
        console.warn('[coupons POST] ❌ validación zod:', error.errors);
        return res.status(400).json({ error: 'Datos inválidos', details: error.errors });
      }
      if (error?.code === '23505') {
        console.warn('[coupons POST] ❌ código duplicado');
        return res.status(409).json({ error: 'El código de cupón ya existe' });
      }
      console.error('[coupons POST] ❌ error:', { message: error?.message, code: error?.code, detail: error?.detail, hint: error?.hint, table: error?.table, column: error?.column, stack: error?.stack });
      res.status(500).json({ error: 'Error al crear cupón', details: error?.message });
    }
  }));

  // PUT /api/admin/coupons/:id — Admin: update coupon
  app.put('/api/admin/coupons/:id', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const data = updateEcommerceCouponSchema.parse(req.body);
      const coupon = await storage.updateCoupon(req.params.id, data);
      if (!coupon) return res.status(404).json({ error: 'Cupón no encontrado' });
      res.json(coupon);
    } catch (error: any) {
      if (error?.name === 'ZodError') {
        return res.status(400).json({ error: 'Datos inválidos', details: error.errors });
      }
      console.error('Error updating coupon:', error);
      res.status(500).json({ error: 'Error al actualizar cupón' });
    }
  }));

  // DELETE /api/admin/coupons/:id — Admin: delete coupon
  app.delete('/api/admin/coupons/:id', requireAuth, requireAdminOrSupervisor, asyncHandler(async (req: any, res: any) => {
    try {
      const success = await storage.deleteCoupon(req.params.id);
      if (!success) return res.status(404).json({ error: 'Cupón no encontrado' });
      res.json({ success: true });
    } catch (error) {
      console.error('Error deleting coupon:', error);
      res.status(500).json({ error: 'Error al eliminar cupón' });
    }
  }));

  // POST /api/coupons/validate — Public (with auth): validate and return coupon data
  app.post('/api/coupons/validate', requireAuth, asyncHandler(async (req: any, res: any) => {
    try {
      const { code, cartSubtotal } = req.body;
      if (!code || typeof code !== 'string') {
        return res.status(400).json({ isValid: false, error: 'Código requerido' });
      }
      const subtotal = Number(cartSubtotal) || 0;
      const result = await storage.validateCoupon(code, subtotal);

      if (!result.isValid || !result.coupon) {
        return res.json({ isValid: false, error: result.error });
      }
      const coupon = result.coupon;
      const discountValue = Number(coupon.discountValue);

      // Increment usage when coupon is applied
      await storage.incrementCouponUsage(code);

      return res.json({
        isValid: true,
        code: coupon.code,
        description: coupon.description,
        type: coupon.discountType,
        discount: discountValue,
        appliesTo: coupon.appliesTo,
        productSku: coupon.productSku,
      });
    } catch (error) {
      console.error('Error validating coupon:', error);
      res.status(500).json({ isValid: false, error: 'Error al validar cupón' });
    }
  }));

  // Build a banner uploader that picks Supabase, Replit ObjStore, or local
  // filesystem depending on which env vars are configured. Mirrors the 3-tier
  // fallback used by /api/upload (line ~805) so banners no longer crash on
  // environments without Supabase credentials.
  async function buildBannerUploader() {
    const path = await import('path');
    const hasSupabase = !!(
      process.env.SUPABASE_URL &&
      process.env.SUPABASE_SERVICE_KEY &&
      process.env.SUPABASE_STORAGE_BUCKET
    );
    const hasReplitObjStore = !!process.env.PUBLIC_OBJECT_SEARCH_PATHS;

    let supabase: any = null;
    let bucket = '';
    if (hasSupabase) {
      supabase = await createSupabase(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_KEY!);
      bucket = process.env.SUPABASE_STORAGE_BUCKET!;
    }

    return async (file: Express.Multer.File, prefix: string): Promise<string> => {
      const fileExtension = path.extname(file.originalname);
      const fileName = `${prefix}_${Date.now()}_${Math.random().toString(36).substring(7)}${fileExtension}`;
      const objectPath = `banners/${fileName}`;

      if (hasSupabase) {
        const { error } = await supabase.storage.from(bucket).upload(objectPath, file.buffer, {
          contentType: file.mimetype || 'image/png',
          upsert: false,
        });
        if (error) throw error;
        const { data } = supabase.storage.from(bucket).getPublicUrl(objectPath);
        return data.publicUrl;
      }

      if (hasReplitObjStore) {
        const objectStorageService = new ObjectStorageService();
        return await objectStorageService.uploadImage(objectPath, file.buffer, file.mimetype);
      }

      const fs = await import('fs');
      const uploadsDir = path.join(process.cwd(), 'server', 'uploads');
      if (!fs.existsSync(uploadsDir)) fs.mkdirSync(uploadsDir, { recursive: true });
      const localFileName = `banner_${fileName}`;
      fs.writeFileSync(path.join(uploadsDir, localFileName), file.buffer);
      return `/api/uploads/${localFileName}`;
    };
  }

  // Create banner with image upload
  app.post('/api/ecommerce/admin/banners',
    requireAuth,
    requireAdminOrSupervisor,
    uploadSingleImage.fields([
      { name: 'imagenDesktop', maxCount: 1 },
      { name: 'imagenMobile', maxCount: 1 },
    ]),
    asyncHandler(async (req: any, res: any) => {
      try {
        const files = req.files as { [fieldname: string]: Express.Multer.File[] };
        const uploadBanner = await buildBannerUploader();

        let imagenDesktopUrl = req.body.imagenDesktop || '';
        let imagenMobileUrl = req.body.imagenMobile || '';

        if (files?.imagenDesktop?.[0]) {
          imagenDesktopUrl = await uploadBanner(files.imagenDesktop[0], 'desktop');
        }

        if (files?.imagenMobile?.[0]) {
          imagenMobileUrl = await uploadBanner(files.imagenMobile[0], 'mobile');
        }

        if (!imagenDesktopUrl) {
          return res.status(400).json({ message: 'Se requiere una imagen de escritorio' });
        }

        const [banner] = await db.insert(storeBanners).values({
          titulo: req.body.titulo || 'Banner',
          subtitulo: req.body.subtitulo || null,
          descripcion: req.body.descripcion || null,
          imagenDesktop: imagenDesktopUrl,
          imagenMobile: imagenMobileUrl || null,
          colorFondo: req.body.colorFondo || '#FF6B35',
          colorTexto: req.body.colorTexto || '#FFFFFF',
          linkUrl: req.body.linkUrl || null,
          orden: parseInt(req.body.orden) || 0,
          activo: req.body.activo !== 'false',
          tipoVisualizacion: req.body.tipoVisualizacion || 'hero',
        }).returning();

        delete _storeEndpointCache?.['banners'];
        res.json(banner);
      } catch (error: any) {
        console.error('Error creating banner:', error);
        res.status(500).json({ message: 'Error creating banner', error: error.message });
      }
    })
  );

  // Update banner
  app.patch('/api/ecommerce/admin/banners/:id',
    requireAuth,
    requireAdminOrSupervisor,
    uploadSingleImage.fields([
      { name: 'imagenDesktop', maxCount: 1 },
      { name: 'imagenMobile', maxCount: 1 },
    ]),
    asyncHandler(async (req: any, res: any) => {
      try {
        const { id } = req.params;
        const files = req.files as { [fieldname: string]: Express.Multer.File[] };
        const uploadBanner = await buildBannerUploader();

        const updates: any = {};

        if (files?.imagenDesktop?.[0]) {
          updates.imagenDesktop = await uploadBanner(files.imagenDesktop[0], 'desktop');
        }

        if (files?.imagenMobile?.[0]) {
          updates.imagenMobile = await uploadBanner(files.imagenMobile[0], 'mobile');
        }

        if (req.body.titulo !== undefined) updates.titulo = req.body.titulo;
        if (req.body.subtitulo !== undefined) updates.subtitulo = req.body.subtitulo;
        if (req.body.descripcion !== undefined) updates.descripcion = req.body.descripcion;
        if (req.body.colorFondo !== undefined) updates.colorFondo = req.body.colorFondo;
        if (req.body.colorTexto !== undefined) updates.colorTexto = req.body.colorTexto;
        if (req.body.linkUrl !== undefined) updates.linkUrl = req.body.linkUrl;
        if (req.body.orden !== undefined) updates.orden = parseInt(req.body.orden);
        if (req.body.tipoVisualizacion !== undefined) updates.tipoVisualizacion = req.body.tipoVisualizacion;
        if (req.body.activo !== undefined) updates.activo = req.body.activo === 'true' || req.body.activo === true;

        updates.updatedAt = new Date();

        const [updated] = await db.update(storeBanners)
          .set(updates)
          .where(eq(storeBanners.id, id))
          .returning();

        if (!updated) {
          return res.status(404).json({ message: 'Banner no encontrado' });
        }

        delete _storeEndpointCache?.['banners'];
        res.json(updated);
      } catch (error: any) {
        console.error('Error updating banner:', error);
        res.status(500).json({ message: 'Error updating banner', error: error.message });
      }
    })
  );

