  // NVV Chart Data - daily/weekly/monthly trend (mirrors /api/sales/chart-data)
  app.get('/api/nvv/chart-data', requireAuth, responseCacheMiddleware(120), asyncHandler(async (req: any, res: any) => {
    const { period = 'daily', selectedPeriod, filterType, salesperson, segment, client } = req.query;

    const dateRange = selectedPeriod && filterType
      ? getDateRange(selectedPeriod as string, filterType as string)
      : { startDate: undefined, endDate: undefined };

    // Build WHERE conditions
    const conditions: string[] = [];
    const params: string[] = [];
    let paramIdx = 1;

    if (dateRange.startDate) {
      conditions.push(`feemdo >= $${paramIdx}`);
      params.push(dateRange.startDate);
      paramIdx++;
    }
    if (dateRange.endDate) {
      conditions.push(`feemdo <= $${paramIdx}`);
      params.push(dateRange.endDate);
      paramIdx++;
    }
    if (salesperson) {
      conditions.push(`nombre_vendedor = $${paramIdx}`);
      params.push(salesperson as string);
      paramIdx++;
    }
    if (segment) {
      if (isIndustrialSegment(segment as string)) {
        // Segmento Industrial (ex "Modular"): match por token, insensible a caja/acentos
        conditions.push(`(TRIM(nombre_segmento_cliente) ILIKE 'industrial' OR nombre_segmento_cliente ILIKE '%modular%')`);
      } else {
        conditions.push(`nombre_segmento_cliente = $${paramIdx}`);
        params.push(segment as string);
        paramIdx++;
      }
    }
    if (client) {
      conditions.push(`nokoen = $${paramIdx}`);
      params.push(client as string);
      paramIdx++;
    }
    // Scope de datos para encargado_area (sucursales asignadas), por código de cliente (endo)
    const clientScope = await getEncargadoScopeKoens(req.user);
    if (clientScope.length > 0) {
      const placeholders = clientScope.map((_, i) => `$${paramIdx + i}`).join(', ');
      conditions.push(`endo IN (${placeholders})`);
      params.push(...clientScope);
      paramIdx += clientScope.length;
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

    // Bucket expression and label format per granularity
    let bucketExpr: string;
    let labelExpr: string;
    let intervalStr: string;
    let truncUnit: string;
    if (period === 'daily') {
      bucketExpr = "feemdo::date";
      labelExpr = "TO_CHAR(s.bucket, 'YYYY-MM-DD')";
      intervalStr = "'1 day'";
      truncUnit = 'day';
    } else if (period === 'weekly') {
      bucketExpr = "DATE_TRUNC('week', feemdo::date)::date";
      labelExpr = "TO_CHAR(s.bucket, 'YYYY-\"W\"IW')";
      intervalStr = "'1 week'";
      truncUnit = 'week';
    } else {
      bucketExpr = "DATE_TRUNC('month', feemdo::date)::date";
      labelExpr = "TO_CHAR(s.bucket, 'YYYY-MM')";
      intervalStr = "'1 month'";
      truncUnit = 'month';
    }

    // When we have a date range, zero-fill missing buckets via generate_series + LEFT JOIN
    // so the chart shows $0 for days/weeks/months with no documents instead of skipping them.
    let query: string;
    if (dateRange.startDate && dateRange.endDate) {
      const startParam = `$1`;
      const endParam = `$2`;
      query = `
        WITH series AS (
          SELECT generate_series(
            DATE_TRUNC('${truncUnit}', ${startParam}::date),
            DATE_TRUNC('${truncUnit}', ${endParam}::date),
            ${intervalStr}::interval
          )::date AS bucket
        ),
        agg AS (
          SELECT ${bucketExpr} AS bucket,
                 COALESCE(SUM(CAST(monto AS numeric)), 0) AS sales
          FROM nvv.fact_nvv
          ${whereClause}
          GROUP BY ${bucketExpr}
        )
        SELECT ${labelExpr} AS period,
               COALESCE(agg.sales, 0) AS sales
        FROM series s
        LEFT JOIN agg ON s.bucket = agg.bucket
        ORDER BY s.bucket ASC
      `;
    } else {
      query = `
        SELECT ${labelExpr.replace('s.bucket', bucketExpr)} as period,
               COALESCE(SUM(CAST(monto AS numeric)), 0) as sales
        FROM nvv.fact_nvv
        ${whereClause}
        GROUP BY ${bucketExpr}
        ORDER BY ${bucketExpr} ASC
      `;
    }

    // Use raw SQL with parameter interpolation (safe — params are validated strings).
    // Regex avoids $1-vs-$10 collisions when there are 10+ params, and replaces
    // every occurrence (CTE references $1/$2 twice — in series and in agg).
    const finalQuery = query.replace(/\$(\d+)/g, (_, idx) => {
      const p = params[parseInt(idx, 10) - 1];
      return `'${p.replace(/'/g, "''")}'`;
    });

    const result = await db.execute(sql.raw(finalQuery));
    const rows = (result as any).rows || result;

    let chartData = rows.map((r: any) => ({
      period: r.period,
      sales: Number(r.sales) || 0,
    }));

    // Transform labels to Spanish month names for yearly monthly view
    if (filterType === 'year' && period === 'monthly') {
      const monthNames: { [key: string]: string } = {
        '01': 'Enero', '02': 'Febrero', '03': 'Marzo', '04': 'Abril',
        '05': 'Mayo', '06': 'Junio', '07': 'Julio', '08': 'Agosto',
        '09': 'Septiembre', '10': 'Octubre', '11': 'Noviembre', '12': 'Diciembre'
      };
      chartData = chartData.map((item: any) => ({
        ...item,
        period: monthNames[item.period.split('-')[1]] || item.period
      }));
    }

    res.json(chartData);
  }));

