  // Helper: resolve internal CC list from email_notification_settings (recipients + cc) for a given type
  const getInternalCcList = async (notificationType: string): Promise<string[]> => {
    try {
      const settings = await db.select()
        .from(emailNotificationSettings)
        .where(eq(emailNotificationSettings.notificationType, notificationType));
      const setting = settings[0];
      if (!setting || !setting.enabled) return [];
      const list: string[] = [];
      if (setting.recipients) list.push(...setting.recipients.split(',').map((s: string) => s.trim()).filter(Boolean));
      if (setting.ccRecipients) list.push(...setting.ccRecipients.split(',').map((s: string) => s.trim()).filter(Boolean));
      return Array.from(new Set(list));
    } catch (e) {
      console.error('Error resolviendo CC interno:', e);
      return [];
    }
  };

  const sendSaleNotificationSchema = z.object({
    koen: z.string().min(1),
    clientEmailOverride: z.string().email().optional().or(z.literal('')),
    monto: z.union([z.number(), z.string()]).optional(),
    detalle: z.string().optional(),
    numeroDocumento: z.string().optional(),
    sendToClient: z.boolean().optional().default(true),
    ccInternal: z.boolean().optional().default(true),
    extraCc: z.string().optional(),
  }).strict();

  app.post('/api/admin/mailing/send-sale', requireMailingAccess, asyncHandler(async (req: any, res: any) => {
    const TAG = '[send-sale]';
    const t0 = Date.now();
    try {
      console.log(`${TAG} ▶️ inicio request`, {
        userId: req.user?.id,
        bodyKeys: Object.keys(req.body || {}),
        body: { ...req.body, detalle: req.body?.detalle ? '[redacted]' : undefined },
      });

      const parsed = sendSaleNotificationSchema.safeParse(req.body);
      if (!parsed.success) {
        console.warn(`${TAG} ❌ validación falló`, parsed.error.errors);
        return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      }
      const { koen, clientEmailOverride, monto, detalle, numeroDocumento, sendToClient, ccInternal, extraCc } = parsed.data;

      console.log(`${TAG} 🔎 buscando cliente`, { koen });
      const client = await storage.getClientByKoen(koen);
      if (!client) {
        console.warn(`${TAG} ❌ cliente no encontrado`, { koen });
        return res.status(404).json({ message: 'Cliente no encontrado' });
      }
      console.log(`${TAG} ✅ cliente`, { koen: client.koen, nokoen: client.nokoen, hasEmail: !!client.email });

      const clientEmail = (clientEmailOverride || client.email || '').trim();
      if (sendToClient && !clientEmail) {
        console.warn(`${TAG} ❌ sin email para cliente`);
        return res.status(400).json({ message: 'El cliente no tiene email registrado. Ingrese uno manualmente.' });
      }

      const recipients: string[] = [];
      if (sendToClient && clientEmail) recipients.push(clientEmail);
      const cc: string[] = [];
      if (ccInternal) {
        try {
          const internalCc = await getInternalCcList('mailing_venta');
          console.log(`${TAG} 📋 CC internos`, { count: internalCc.length, list: internalCc });
          cc.push(...internalCc);
        } catch (e: any) {
          console.error(`${TAG} ❌ error obteniendo CC internos`, { message: e?.message, stack: e?.stack });
          throw e;
        }
      }
      if (extraCc) cc.push(...extraCc.split(',').map(s => s.trim()).filter(Boolean));
      const ccUnique = Array.from(new Set(cc.filter(e => !recipients.includes(e))));

      if (recipients.length === 0 && ccUnique.length === 0) {
        console.warn(`${TAG} ❌ sin destinatarios`);
        return res.status(400).json({ message: 'No hay destinatarios para enviar el correo' });
      }

      let subject = '';
      let html = '';
      try {
        const built = buildSaleNotificationEmail({
          clientName: client.nokoen || 'Cliente',
          clientRut: client.rten || undefined,
          monto,
          detalle,
          numeroDocumento,
          fecha: new Date(),
        });
        subject = built.subject;
        html = built.html;
        console.log(`${TAG} 📝 template OK`, { subjectLen: subject.length, htmlLen: html.length });
      } catch (e: any) {
        console.error(`${TAG} ❌ error en buildSaleNotificationEmail`, { message: e?.message, stack: e?.stack });
        throw e;
      }

      const to = recipients.length > 0 ? recipients.join(', ') : ccUnique.join(', ');
      const ccStr = recipients.length > 0 && ccUnique.length > 0 ? ccUnique.join(', ') : undefined;
      console.log(`${TAG} ✉️ destinatarios`, { to, cc: ccStr });

      let logId: string | undefined;
      try {
        const logEntry = await db.insert(emailLogs).values({
          recipient: [to, ccStr].filter(Boolean).join(' | '),
          subject,
          notificationType: 'mailing_venta_manual',
          status: 'pending',
        }).returning({ id: emailLogs.id });
        logId = logEntry[0]?.id;
        console.log(`${TAG} 🗒️ emailLogs insert`, { logId });
      } catch (e: any) {
        console.error(`${TAG} ❌ error insertando emailLogs`, { message: e?.message, code: e?.code, detail: e?.detail, stack: e?.stack });
        throw e;
      }

      try {
        console.log(`${TAG} 📤 enviando vía emailService.sendEmail...`);
        await emailService.sendEmail({ to, subject, html, cc: ccStr });
        console.log(`${TAG} ✅ enviado en ${Date.now() - t0}ms`);
        if (logId) {
          await db.update(emailLogs).set({ status: 'sent', sentAt: new Date() }).where(eq(emailLogs.id, logId));
        }
        res.json({ success: true, to, cc: ccStr });
      } catch (error: any) {
        console.error(`${TAG} ❌ Error enviando correo de venta:`, {
          message: error?.message,
          name: error?.name,
          code: error?.code,
          response: error?.response,
          responseCode: error?.responseCode,
          command: error?.command,
          stack: error?.stack,
        });
        if (logId) {
          await db.update(emailLogs).set({ status: 'failed', errorMessage: error?.message || 'Error desconocido' }).where(eq(emailLogs.id, logId));
        }
        res.status(500).json({ message: `Error al enviar correo: ${error?.message || 'desconocido'}`, error: error?.message });
      }
    } catch (outerError: any) {
      console.error(`${TAG} 💥 error no manejado en handler`, {
        message: outerError?.message,
        name: outerError?.name,
        code: outerError?.code,
        stack: outerError?.stack,
      });
      if (!res.headersSent) {
        res.status(500).json({ message: `Error al enviar correo: ${outerError?.message || 'desconocido'}`, error: outerError?.message });
      }
    }
  }));

  const sendCobranzaSchema = z.object({
    koen: z.string().min(1),
    clientEmailOverride: z.string().email().optional().or(z.literal('')),
    montoAdeudado: z.union([z.number(), z.string()]),
    fechaVencimiento: z.string().min(1),
    numeroDocumento: z.string().optional(),
    mensajeAdicional: z.string().optional(),
    subjectOverride: z.string().optional(),
    sendToClient: z.boolean().optional().default(true),
    ccInternal: z.boolean().optional().default(true),
    extraCc: z.string().optional(),
  }).strict();

  app.post('/api/admin/mailing/send-cobranza', requireMailingAccess, asyncHandler(async (req: any, res: any) => {
    const TAG = '[cobranza]';
    const t0 = Date.now();
    try {
      console.log(`${TAG} ▶️ inicio request`, {
        userId: req.user?.id,
        bodyKeys: Object.keys(req.body || {}),
        body: { ...req.body, mensajeAdicional: req.body?.mensajeAdicional ? '[redacted]' : undefined },
      });

      const parsed = sendCobranzaSchema.safeParse(req.body);
      if (!parsed.success) {
        console.warn(`${TAG} ❌ validación falló`, parsed.error.errors);
        return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
      }
      const { koen, clientEmailOverride, montoAdeudado, fechaVencimiento, numeroDocumento, mensajeAdicional, subjectOverride, sendToClient, ccInternal, extraCc } = parsed.data;

      const montoNum = Number(montoAdeudado);
      if (!isFinite(montoNum) || montoNum <= 0) {
        console.warn(`${TAG} ❌ monto inválido`, { montoAdeudado, montoNum });
        return res.status(400).json({ message: 'Monto adeudado inválido' });
      }
      const venc = new Date(fechaVencimiento);
      if (isNaN(venc.getTime())) {
        console.warn(`${TAG} ❌ fecha inválida`, { fechaVencimiento });
        return res.status(400).json({ message: 'Fecha de vencimiento inválida' });
      }

      console.log(`${TAG} 🔎 buscando cliente`, { koen });
      const client = await storage.getClientByKoen(koen);
      if (!client) {
        console.warn(`${TAG} ❌ cliente no encontrado`, { koen });
        return res.status(404).json({ message: 'Cliente no encontrado' });
      }
      console.log(`${TAG} ✅ cliente`, { koen: client.koen, nokoen: client.nokoen, hasEmail: !!client.email });

      const clientEmail = (clientEmailOverride || client.email || '').trim();
      if (sendToClient && !clientEmail) {
        console.warn(`${TAG} ❌ sin email para cliente`);
        return res.status(400).json({ message: 'El cliente no tiene email registrado. Ingrese uno manualmente.' });
      }

      const recipients: string[] = [];
      if (sendToClient && clientEmail) recipients.push(clientEmail);
      const cc: string[] = [];
      if (ccInternal) {
        try {
          const internalCc = await getInternalCcList('cobranza');
          console.log(`${TAG} 📋 CC internos`, { count: internalCc.length, list: internalCc });
          cc.push(...internalCc);
        } catch (e: any) {
          console.error(`${TAG} ❌ error obteniendo CC internos`, { message: e?.message, stack: e?.stack });
          throw e;
        }
      }
      if (extraCc) cc.push(...extraCc.split(',').map(s => s.trim()).filter(Boolean));
      const ccUnique = Array.from(new Set(cc.filter(e => !recipients.includes(e))));

      if (recipients.length === 0 && ccUnique.length === 0) {
        console.warn(`${TAG} ❌ sin destinatarios`);
        return res.status(400).json({ message: 'No hay destinatarios para enviar el correo' });
      }

      let subject = '';
      let html = '';
      try {
        const built = buildCobranzaEmail({
          clientName: client.nokoen || 'Cliente',
          clientRut: client.rten || undefined,
          montoAdeudado: montoNum,
          fechaVencimiento: venc,
          numeroDocumento,
          mensajeAdicional,
        });
        subject = (subjectOverride && subjectOverride.trim()) || built.subject;
        html = built.html;
        console.log(`${TAG} 📝 template OK`, { subjectLen: subject.length, htmlLen: html.length });
      } catch (e: any) {
        console.error(`${TAG} ❌ error en buildCobranzaEmail`, { message: e?.message, stack: e?.stack });
        throw e;
      }

      const to = recipients.length > 0 ? recipients.join(', ') : ccUnique.join(', ');
      const ccStr = recipients.length > 0 && ccUnique.length > 0 ? ccUnique.join(', ') : undefined;
      console.log(`${TAG} ✉️ destinatarios`, { to, cc: ccStr });

      let logId: string | undefined;
      try {
        const logEntry = await db.insert(emailLogs).values({
          recipient: [to, ccStr].filter(Boolean).join(' | '),
          subject,
          notificationType: 'mailing_cobranza_manual',
          status: 'pending',
        }).returning({ id: emailLogs.id });
        logId = logEntry[0]?.id;
        console.log(`${TAG} 🗒️ emailLogs insert`, { logId });
      } catch (e: any) {
        console.error(`${TAG} ❌ error insertando emailLogs`, { message: e?.message, code: e?.code, detail: e?.detail, stack: e?.stack });
        throw e;
      }

      try {
        console.log(`${TAG} 📤 enviando vía emailService.sendEmail...`);
        await emailService.sendEmail({ to, subject, html, cc: ccStr });
        console.log(`${TAG} ✅ enviado en ${Date.now() - t0}ms`);
        if (logId) {
          await db.update(emailLogs).set({ status: 'sent', sentAt: new Date() }).where(eq(emailLogs.id, logId));
        }
        res.json({ success: true, to, cc: ccStr });
      } catch (error: any) {
        console.error(`${TAG} ❌ Error enviando correo de cobranza:`, {
          message: error?.message,
          name: error?.name,
          code: error?.code,
          response: error?.response,
          responseCode: error?.responseCode,
          command: error?.command,
          stack: error?.stack,
        });
        if (logId) {
          await db.update(emailLogs).set({ status: 'failed', errorMessage: error?.message || 'Error desconocido' }).where(eq(emailLogs.id, logId));
        }
        res.status(500).json({ message: `Error al enviar correo: ${error?.message || 'desconocido'}`, error: error?.message });
      }
    } catch (outerError: any) {
      console.error(`${TAG} 💥 error no manejado en handler`, {
        message: outerError?.message,
        name: outerError?.name,
        code: outerError?.code,
        stack: outerError?.stack,
      });
      if (!res.headersSent) {
        res.status(500).json({ message: `Error al enviar correo: ${outerError?.message || 'desconocido'}`, error: outerError?.message });
      }
    }
  }));

  // Vista previa del correo de cobranza (sin enviar ni registrar) — para revisar/editar antes de enviar.
  app.post('/api/admin/mailing/cobranza-preview', requireMailingAccess, asyncHandler(async (req: any, res: any) => {
    const previewSchema = z.object({
      clientName: z.string().min(1),
      clientRut: z.string().optional(),
      montoAdeudado: z.union([z.number(), z.string()]),
      fechaVencimiento: z.string().min(1),
      numeroDocumento: z.string().optional(),
      mensajeAdicional: z.string().optional(),
      subjectOverride: z.string().optional(),
    }).strict();
    const parsed = previewSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ message: 'Datos inválidos', errors: parsed.error.errors });
    }
    const montoNum = Number(parsed.data.montoAdeudado);
    if (!isFinite(montoNum) || montoNum <= 0) {
      return res.status(400).json({ message: 'Monto adeudado inválido' });
    }
    const venc = new Date(parsed.data.fechaVencimiento);
    if (isNaN(venc.getTime())) {
      return res.status(400).json({ message: 'Fecha de vencimiento inválida' });
    }
    const built = buildCobranzaEmail({
      clientName: parsed.data.clientName,
      clientRut: parsed.data.clientRut || undefined,
      montoAdeudado: montoNum,
      fechaVencimiento: venc,
      numeroDocumento: parsed.data.numeroDocumento,
      mensajeAdicional: parsed.data.mensajeAdicional,
    });
    const subject = (parsed.data.subjectOverride && parsed.data.subjectOverride.trim()) || built.subject;
    res.json({ subject, html: built.html });
  }));

  // Auto-create cobranza notification setting if missing (so admins can configure CC internos)
  app.post('/api/admin/mailing/ensure-settings', requireMailingAccess, asyncHandler(async (_req: any, res: any) => {
    try {
      const ensure = async (notificationType: string, displayName: string, description: string) => {
        const existing = await db.select().from(emailNotificationSettings).where(eq(emailNotificationSettings.notificationType, notificationType));
        if (existing.length === 0) {
          await db.insert(emailNotificationSettings).values({
            notificationType, displayName, description, enabled: true, recipients: '', ccRecipients: '',
          });
        }
      };
      await ensure('cobranza', 'Cobranza', 'Destinatarios internos en copia para correos manuales de cobranza');
      await ensure('mailing_venta', 'Mailing - Venta manual', 'Destinatarios internos en copia para correos de notificación de venta enviados desde Mailing');
      await ensure('ecommerce_sale_auto', 'Auto: Venta recibida (tienda)', 'Cuando un cliente realiza un pedido en Panorámica Market, se envía un correo automático de confirmación. CC: copias internas opcionales.');
      await ensure('ecommerce_quote_auto', 'Auto: Cotización recibida (tienda)', 'Cuando un visitante envía una solicitud de cotización pública, se envía un correo automático de confirmación. CC: copias internas opcionales.');
      await ensure('pedido_modificado', 'Auto: Pedido modificado (tienda)', 'Cuando el equipo modifica un pedido (precios, items o estado), se envía un correo al cliente con el nuevo total y un recordatorio para actualizar el comprobante si paga por transferencia. CC: copias internas opcionales.');
      res.json({ success: true });
    } catch (error: any) {
      console.error('❌ Error inicializando settings de mailing:', error);
      res.status(500).json({ message: 'Error inicializando settings', error: error.message });
    }
  }));

