  // ==================================================================================
  // GASTOS EMPRESARIALES routes
  // ==================================================================================

  // Upload evidencia file for gastos empresariales
  // Nomenclatura: gastos/evidencia_{userId}_{YYYYMMDD}_{randomId}.{ext}
  app.post('/api/gastos-empresariales/upload-evidencia', requireAuth, upload.single('file'), asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;

      // Only salesperson, supervisor, admin and recursos_humanos can upload evidence
      if (!['salesperson', 'supervisor', 'encargado_area', 'admin', 'recursos_humanos'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado para subir evidencia' });
      }

      if (!req.file) {
        return res.status(400).json({ message: 'No se ha subido ningún archivo' });
      }

      const file = req.file;
      const now = new Date();
      const dateStr = now.toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD
      const randomId = nanoid(6);
      const fileExtension = path.extname(file.originalname).toLowerCase();
      const userIdShort = user.id.slice(0, 8);

      // Estructura organizada: gastos/evidencia_{userId}_{fecha}_{randomId}.{ext}
      const fileName = `gastos/evidencia_${userIdShort}_${dateStr}_${randomId}${fileExtension}`;

      let imageUrl: string;
      let previewUrl: string | null = null;

      // Option 1: Supabase Storage (Railway deployment)
      if (process.env.SUPABASE_URL && process.env.SUPABASE_SERVICE_KEY && process.env.SUPABASE_STORAGE_BUCKET) {
        const supabase = await createSupabase(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);
        const bucket = process.env.SUPABASE_STORAGE_BUCKET;

        const { data, error } = await supabase.storage
          .from(bucket)
          .upload(fileName, file.buffer, {
            contentType: file.mimetype,
            upsert: false,
          });

        if (error) {
          console.error('❌ [GASTO-EVIDENCIA] Supabase Storage error:', error.message);
          throw error;
        }

        const { data: urlData } = supabase.storage.from(bucket).getPublicUrl(fileName);
        imageUrl = urlData.publicUrl;
        console.log(`☁️ [GASTO-EVIDENCIA] Uploaded to Supabase: ${fileName} -> ${imageUrl}`);

        // Generate PDF preview
        if (isPdfFile(file.mimetype, file.originalname)) {
          try {
            const previewBuffer = await convertPdfToImage(file.buffer, 600);
            if (previewBuffer) {
              const previewFileName = `gastos/evidencia_${userIdShort}_${dateStr}_${randomId}_preview.png`;
              const { error: prevErr } = await supabase.storage
                .from(bucket)
                .upload(previewFileName, previewBuffer, { contentType: 'image/png', upsert: false });
              if (!prevErr) {
                const { data: prevUrlData } = supabase.storage.from(bucket).getPublicUrl(previewFileName);
                previewUrl = prevUrlData.publicUrl;
              }
            }
          } catch (previewError) {
            console.warn('⚠️ [GASTO-EVIDENCIA] Failed to generate PDF preview:', previewError);
          }
        }
      }
      // Option 2: Replit Object Storage
      else if (process.env.PUBLIC_OBJECT_SEARCH_PATHS) {
        imageUrl = `/public-objects/${fileName}`;
        try {
          const objectStorageService = new ObjectStorageService();
          imageUrl = await objectStorageService.uploadImage(fileName, file.buffer, file.mimetype);
          console.log(`☁️ [GASTO-EVIDENCIA] Uploaded to Object Storage: ${fileName}`);
        } catch (objStorageErr) {
          console.warn(`⚠️ [GASTO-EVIDENCIA] Object Storage upload failed, using local fallback: ${objStorageErr}`);
        }

        if (isPdfFile(file.mimetype, file.originalname)) {
          try {
            const previewBuffer = await convertPdfToImage(file.buffer, 600);
            if (previewBuffer) {
              const previewFileName = `gastos/evidencia_${userIdShort}_${dateStr}_${randomId}_preview.png`;
              try {
                const objectStorageService = new ObjectStorageService();
                previewUrl = await objectStorageService.uploadImage(previewFileName, previewBuffer, 'image/png');
              } catch {
                previewUrl = `/public-objects/${previewFileName}`;
              }
            }
          } catch (previewError) {
            console.warn('⚠️ [GASTO-EVIDENCIA] Failed to generate PDF preview:', previewError);
          }
        }
      }
      // Option 3: Local file storage fallback
      else {
        const localDir = path.join(process.cwd(), 'public', 'gastos');
        const fs = await import('fs/promises');
        try {
          await fs.mkdir(localDir, { recursive: true });
          const localFilePath = path.join(process.cwd(), 'public', fileName);
          await fs.writeFile(localFilePath, file.buffer);
          console.log(`💾 [GASTO-EVIDENCIA] Local copy saved: ${localFilePath}`);
        } catch (localErr) {
          console.warn('⚠️ [GASTO-EVIDENCIA] Could not save local copy:', localErr);
        }
        imageUrl = `/${fileName}`;
      }

      res.json({ url: imageUrl, fileName, previewUrl });
    } catch (error: any) {
      console.error('Error uploading evidencia:', error);
      res.status(500).json({ message: 'Error al subir archivo', error: error.message });
    }
  }));

  // Upload comprobante de transferencia for fund allocations
  // Nomenclatura: fondos/comprobante_{fundId}_{YYYYMMDD}_{randomId}.{ext}
  app.post('/api/fund-allocations/upload-comprobante', requireAuth, upload.single('file'), asyncHandler(async (req: any, res: any) => {
    try {
      const user = req.user;

      // Only admin and HR can upload fund transfer receipts
      if (!['admin', 'recursos_humanos'].includes(user.role)) {
        return res.status(403).json({ message: 'No autorizado para subir comprobante de fondo' });
      }

      if (!req.file) {
        return res.status(400).json({ message: 'No se ha subido ningún archivo' });
      }

      const file = req.file;
      const fundId = req.body.fundId || 'sin-id';
      const now = new Date();
      const dateStr = now.toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD
      const randomId = nanoid(6);
      const fileExtension = path.extname(file.originalname).toLowerCase();
      const fundIdShort = fundId.slice(0, 8);

      // Estructura organizada: fondos/comprobante_{fundId}_{fecha}_{randomId}.{ext}
      const fileName = `fondos/comprobante_${fundIdShort}_${dateStr}_${randomId}${fileExtension}`;

      let imageUrl: string;
      let previewUrl: string | null = null;

      // Option 1: Supabase Storage (Railway deployment)
      if (process.env.SUPABASE_URL && process.env.SUPABASE_SERVICE_KEY && process.env.SUPABASE_STORAGE_BUCKET) {
        const supabase = await createSupabase(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);
        const bucket = process.env.SUPABASE_STORAGE_BUCKET;

        const { data, error } = await supabase.storage
          .from(bucket)
          .upload(fileName, file.buffer, {
            contentType: file.mimetype,
            upsert: false,
          });

        if (error) {
          console.error('❌ [FONDO-COMPROBANTE] Supabase Storage error:', error.message);
          throw error;
        }

        const { data: urlData } = supabase.storage.from(bucket).getPublicUrl(fileName);
        imageUrl = urlData.publicUrl;
        console.log(`☁️ [FONDO-COMPROBANTE] Uploaded to Supabase: ${fileName} -> ${imageUrl}`);

        // Generate PDF preview
        if (isPdfFile(file.mimetype, file.originalname)) {
          try {
            const previewBuffer = await convertPdfToImage(file.buffer, 600);
            if (previewBuffer) {
              const previewFileName = `fondos/comprobante_${fundIdShort}_${dateStr}_${randomId}_preview.png`;
              const { error: prevErr } = await supabase.storage
                .from(bucket)
                .upload(previewFileName, previewBuffer, {
                  contentType: 'image/png',
                  upsert: false,
                });
              if (!prevErr) {
                const { data: prevUrlData } = supabase.storage.from(bucket).getPublicUrl(previewFileName);
                previewUrl = prevUrlData.publicUrl;
                console.log(`🖼️ [FONDO-COMPROBANTE] Preview generated: ${previewFileName}`);
              }
            }
          } catch (previewError) {
            console.warn('⚠️ [FONDO-COMPROBANTE] Failed to generate PDF preview:', previewError);
          }
        }
      } else {
        // Option 2: Replit Object Storage (fallback)
        const objectStorageService = new ObjectStorageService();
        imageUrl = await objectStorageService.uploadImage(fileName, file.buffer, file.mimetype);
        console.log(`☁️ [FONDO-COMPROBANTE] Uploaded to Object Storage: ${fileName}`);

        if (isPdfFile(file.mimetype, file.originalname)) {
          try {
            const previewBuffer = await convertPdfToImage(file.buffer, 600);
            if (previewBuffer) {
              const previewFileName = `fondos/comprobante_${fundIdShort}_${dateStr}_${randomId}_preview.png`;
              previewUrl = await objectStorageService.uploadImage(previewFileName, previewBuffer, 'image/png');
              console.log(`🖼️ [FONDO-COMPROBANTE] Preview generated: ${previewFileName}`);
            }
          } catch (previewError) {
            console.warn('⚠️ [FONDO-COMPROBANTE] Failed to generate PDF preview:', previewError);
          }
        }
      }

      res.json({ url: imageUrl, fileName, previewUrl });
    } catch (error: any) {
      console.error('Error uploading comprobante de fondo:', error);
      res.status(500).json({ message: 'Error al subir archivo', error: error.message });
    }
  }));

